    "code": "/**\n * Component: User profile card with Cover Image\n * Author: @noob_dev (https://tailwindflex.com/@noob_dev)\n * Source: https://tailwindflex.com/@noob_dev/user-profile-card-with-cover-image\n * Attribution: Créé par @noob_dev sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function UserProfileCardWithCoverImage() {\n  return (\n    <div>\n    \n    \n    <div\n        className=\"max-w-2xl mx-4 sm md lg xl sm md lg xl mt-16 bg-white shadow-xl rounded-lg text-gray-900\">\n        <div className=\"rounded-t-lg h-32 overflow-hidden\">\n            <img className=\"object-cover object-top w-full\" src='https://images.unsplash.com/photo-1549880338-65ddcdfd017b?ixlib=rb-1.2.1&q=80&fm=jpg&crop=entropy&cs=tinysrgb&w=400&fit=max&ixid=eyJhcHBfaWQiOjE0NTg5fQ' alt='Mountain' />\n        </div>\n        <div className=\"mx-auto w-32 h-32 relative -mt-16 border-4 border-white rounded-full overflow-hidden\">\n            <img className=\"object-cover object-center h-32\" src='https://images.unsplash.com/photo-1438761681033-6461ffad8d80?ixlib=rb-1.2.1&q=80&fm=jpg&crop=entropy&cs=tinysrgb&w=400&fit=max&ixid=eyJhcHBfaWQiOjE0NTg5fQ' alt='Woman looking front' />\n        </div>\n        <div className=\"text-center mt-2\">\n            <h2 className=\"font-semibold\">Sarah Smith</h2>\n            <p className=\"text-gray-500\">Freelance Web Designer</p>\n        </div>\n        <ul className=\"py-4 mt-2 text-gray-700 flex items-center justify-around\">\n            <li className=\"flex flex-col items-center justify-around\">\n                <svg className=\"w-4 fill-current text-blue-900\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\">\n                    <path\n                        d=\"M10 15l-5.878 3.09 1.123-6.545L.489 6.91l6.572-.955L10 0l2.939 5.955 6.572.955-4.756 4.635 1.123 6.545z\" />\n                </svg>\n                <div>2k</div>\n            </li>\n            <li className=\"flex flex-col items-center justify-between\">\n                <svg className=\"w-4 fill-current text-blue-900\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\">\n                    <path\n                        d=\"M7 8a4 4 0 1 1 0-8 4 4 0 0 1 0 8zm0 1c2.15 0 4.2.4 6.1 1.09L12 16h-1.25L10 20H4l-.75-4H2L.9 10.09A17.93 17.93 0 0 1 7 9zm8.31.17c1.32.18 2.59.48 3.8.92L18 16h-1.25L16 20h-3.96l.37-2h1.25l1.65-8.83zM13 0a4 4 0 1 1-1.33 7.76 5.96 5.96 0 0 0 0-7.52C12.1.1 12.53 0 13 0z\" />\n                </svg>\n                <div>10k</div>\n            </li>\n            <li className=\"flex flex-col items-center justify-around\">\n                <svg className=\"w-4 fill-current text-blue-900\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\">\n                    <path\n                        d=\"M9 12H1v6a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-6h-8v2H9v-2zm0-1H0V5c0-1.1.9-2 2-2h4V2a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v1h4a2 2 0 0 1 2 2v6h-9V9H9v2zm3-8V2H8v1h4z\" />\n                </svg>\n                <div>15</div>\n            </li>\n        </ul>\n        <div className=\"p-4 border-t mx-8 mt-2\">\n            <button className=\"w-1/2 block mx-auto rounded-full bg-gray-900 hover font-semibold text-white px-6 py-2\">Follow</button>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<!-- https://gist.github.com/goodreds/5b8a4a2bf11ff67557d38c5e727ea86c -->\n\n<div\n    class=\"max-w-2xl mx-4 sm:max-w-sm md:max-w-sm lg:max-w-sm xl:max-w-sm sm:mx-auto md:mx-auto lg:mx-auto xl:mx-auto mt-16 bg-white shadow-xl rounded-lg text-gray-900\">\n    <div class=\"rounded-t-lg h-32 overflow-hidden\">\n        <img class=\"object-cover object-top w-full\" src='https://images.unsplash.com/photo-1549880338-65ddcdfd017b?ixlib=rb-1.2.1&q=80&fm=jpg&crop=entropy&cs=tinysrgb&w=400&fit=max&ixid=eyJhcHBfaWQiOjE0NTg5fQ' alt='Mountain'>\n    </div>\n    <div class=\"mx-auto w-32 h-32 relative -mt-16 border-4 border-white rounded-full overflow-hidden\">\n        <img class=\"object-cover object-center h-32\" src='https://images.unsplash.com/photo-1438761681033-6461ffad8d80?ixlib=rb-1.2.1&q=80&fm=jpg&crop=entropy&cs=tinysrgb&w=400&fit=max&ixid=eyJhcHBfaWQiOjE0NTg5fQ' alt='Woman looking front'>\n    </div>\n    <div class=\"text-center mt-2\">\n        <h2 class=\"font-semibold\">Sarah Smith</h2>\n        <p class=\"text-gray-500\">Freelance Web Designer</p>\n    </div>\n    <ul class=\"py-4 mt-2 text-gray-700 flex items-center justify-around\">\n        <li class=\"flex flex-col items-center justify-around\">\n            <svg class=\"w-4 fill-current text-blue-900\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\">\n                <path\n                    d=\"M10 15l-5.878 3.09 1.123-6.545L.489 6.91l6.572-.955L10 0l2.939 5.955 6.572.955-4.756 4.635 1.123 6.545z\" />\n            </svg>\n            <div>2k</div>\n        </li>\n        <li class=\"flex flex-col items-center justify-between\">\n            <svg class=\"w-4 fill-current text-blue-900\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\">\n                <path\n                    d=\"M7 8a4 4 0 1 1 0-8 4 4 0 0 1 0 8zm0 1c2.15 0 4.2.4 6.1 1.09L12 16h-1.25L10 20H4l-.75-4H2L.9 10.09A17.93 17.93 0 0 1 7 9zm8.31.17c1.32.18 2.59.48 3.8.92L18 16h-1.25L16 20h-3.96l.37-2h1.25l1.65-8.83zM13 0a4 4 0 1 1-1.33 7.76 5.96 5.96 0 0 0 0-7.52C12.1.1 12.53 0 13 0z\" />\n            </svg>\n            <div>10k</div>\n        </li>\n        <li class=\"flex flex-col items-center justify-around\">\n            <svg class=\"w-4 fill-current text-blue-900\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\">\n                <path\n                    d=\"M9 12H1v6a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-6h-8v2H9v-2zm0-1H0V5c0-1.1.9-2 2-2h4V2a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v1h4a2 2 0 0 1 2 2v6h-9V9H9v2zm3-8V2H8v1h4z\" />\n            </svg>\n            <div>15</div>\n        </li>\n    </ul>\n    <div class=\"p-4 border-t mx-8 mt-2\">\n        <button class=\"w-1/2 block mx-auto rounded-full bg-gray-900 hover:shadow-lg font-semibold text-white px-6 py-2\">Follow</button>\n    </div>\n</div>"
