    "code": "/**\n * Component: Otp-code template\n * Author: @anandu-ap (https://tailwindflex.com/@anandu-ap)\n * Source: https://tailwindflex.com/@anandu-ap/otp-code-template\n * Attribution: Créé par @anandu-ap sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function OtpCodeTemplate() {\n  return (\n    <div>\n    <html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\" />\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n        <title>Your OTP Code</title>\n        \n    </head>\n    <body className=\"bg-gray-100\">\n        <div className=\"max-w-2xl mx-auto my-8 bg-white rounded-lg shadow-md overflow-hidden\">\n            <div className=\"bg-indigo-600 py-6 px-8\">\n                <h1 className=\"text-3xl font-bold text-white text-center\">Your OTP Code</h1>\n            </div>\n            <div className=\"p-8\">\n                <p className=\"text-gray-700 mb-6\">Hello,</p>\n                <p className=\"text-gray-700 mb-6\">Your One-Time Password (OTP) for account verification is:</p>\n                <div className=\"bg-gray-100 rounded-lg p-4 mb-6\">\n                    <p className=\"text-4xl font-bold text-center text-indigo-600\">5695314</p>\n                </div>\n                <p className=\"text-gray-700 mb-6\">This OTP is valid for <span className=\"font-semibold\">2 minutes</span>. Please do not share this code with anyone.</p>\n                <p className=\"text-gray-700 mb-2\">If you didn't request this code, please ignore this email.</p>\n                <p className=\"text-gray-700\">Thank you for using our service!</p>\n            </div>\n            <div className=\"bg-gray-100 py-4 px-8\">\n                <p className=\"text-sm text-gray-600 text-center\">&copy; 2024 Your Company Name. All rights reserved.</p>\n            </div>\n        </div>\n    </body>\n    </html>\n    </div>\n  );\n}\n",
    "rawHtml": "<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Your OTP Code</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n</head>\n<body class=\"bg-gray-100\">\n    <div class=\"max-w-2xl mx-auto my-8 bg-white rounded-lg shadow-md overflow-hidden\">\n        <div class=\"bg-indigo-600 py-6 px-8\">\n            <h1 class=\"text-3xl font-bold text-white text-center\">Your OTP Code</h1>\n        </div>\n        <div class=\"p-8\">\n            <p class=\"text-gray-700 mb-6\">Hello,</p>\n            <p class=\"text-gray-700 mb-6\">Your One-Time Password (OTP) for account verification is:</p>\n            <div class=\"bg-gray-100 rounded-lg p-4 mb-6\">\n                <p class=\"text-4xl font-bold text-center text-indigo-600\">5695314</p>\n            </div>\n            <p class=\"text-gray-700 mb-6\">This OTP is valid for <span class=\"font-semibold\">2 minutes</span>. Please do not share this code with anyone.</p>\n            <p class=\"text-gray-700 mb-2\">If you didn't request this code, please ignore this email.</p>\n            <p class=\"text-gray-700\">Thank you for using our service!</p>\n        </div>\n        <div class=\"bg-gray-100 py-4 px-8\">\n            <p class=\"text-sm text-gray-600 text-center\">&copy; 2024 Your Company Name. All rights reserved.</p>\n        </div>\n    </div>\n</body>\n</html>"
