    "code": "/**\n * Component: Testimonial card\n * Author: @leon-bachmann (https://tailwindflex.com/@leon-bachmann)\n * Source: https://tailwindflex.com/@leon-bachmann/testimonial-card-4\n * Attribution: Créé par @leon-bachmann sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function TestimonialCard4() {\n  return (\n    <div>\n    <div className=\"flex sm md1/3 mb-8 md0 p-5 shadow-md rounded-xl mr-3 ml-3\">\n        <div className=\"w-full text-left\">\n            <img src=\"https://www.svgrepo.com/show/494336/apple.svg\"  className=\"mb-5 h-10 w-10\" />\n            <p className=\"text-md text-gray-800 text-left leading-normal mb-5 font-lf-normal\">\n               I had a great experience at Joe's Diner. The service was top-notch and the food was delicious.\n            </p>\n            <span className=\"flex item-center\">\n                <img src=\"https://www.svgrepo.com/show/497628/user-square.svg\"  className=\"rounded-md mr-3 h-14 w-14\"  /> \n                <div>\n                    <p className=\"text-sm text-gray-600\">Leon Bachmann </p> \n                    <p className=\"text-sm text-gray-400\">Profession</p>\n                </div>\n            </span>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
