    "code": "/**\n * Component: Gradient card\n * Author: @team-tailwindflex (https://tailwindflex.com/@team-tailwindflex)\n * Source: https://tailwindflex.com/@team-tailwindflex/gradient-card\n * Attribution: Créé par @team-tailwindflex sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function GradientCard() {\n  return (\n    <div>\n    <div className=\"bg-gray-900 h-screen flex flex-col justify-center items-center\">\n        <div className=\"bg-gradient-to-r from-purple-600 to-pink-600 rounded-lg shadow-lg p-8\">\n            <h1 className=\"text-4xl font-bold text-white mb-4\">\n                Tailwind CSS\n            </h1>\n            <p className=\"text-lg text-white mb-8\">\n                A utility-first CSS framework for rapidly building custom designs.\n            </p>\n            <a href=\"#\" className=\"bg-white hover200 text-purple-600 font-bold py-2 px-4 rounded\">\n                Get started\n            </a>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
