    "code": "/**\n * Component: Article card\n * Author: @sienna (https://tailwindflex.com/@sienna)\n * Source: https://tailwindflex.com/@sienna/article-card\n * Attribution: Créé par @sienna sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ArticleCard() {\n  return (\n    <div>\n    <article className=\"flex flex-col shadow max-w-[400px]\">\r\n        \r\n        <a href=\"#\" className=\"hover75\">\r\n            <img src=\"https://source.unsplash.com/collection/1346951/1000x500?sig=3\" />\r\n        </a>\r\n        <div className=\"bg-white flex flex-col justify-start p-6\">\r\n            <a href=\"#\" className=\"text-blue-700 text-sm font-bold uppercase pb-4\">Sports,Fitness</a>\r\n            <a href=\"#\" className=\"text-3xl font-bold hover700 pb-4\">Lorem Ipsum Dolor Sit Amet Dolor Sit Amet</a>\r\n            <p href=\"#\" className=\"text-sm pb-3\">\r\n                By <a href=\"#\" className=\"font-semibold hover800\">David Grzyb</a>, Published on October 22nd, 2019\r\n            </p>\r\n            <a href=\"#\" className=\"pb-6\">Lorem ipsum dolor sit amet, consectetur adipiscing elit. Vivamus quis porta dui. Ut eu\r\n                iaculis massa. Sed ornare ligula lacus, quis iaculis dui porta volutpat. In sit amet posuere magna..</a>\r\n            <a href=\"#\" className=\"uppercase text-gray-800 hover\">\r\n                Continue Reading\r\n            </a>\r\n        </div>\r\n    </article>\n    </div>\n  );\n}\n",
    "rawHtml": "<article class=\"flex flex-col shadow max-w-[400px]\">\r\n    <!-- Article Image -->\r\n    <a href=\"#\" class=\"hover:opacity-75\">\r\n        <img src=\"https://source.unsplash.com/collection/1346951/1000x500?sig=3\">\r\n    </a>\r\n    <div class=\"bg-white flex flex-col justify-start p-6\">\r\n        <a href=\"#\" class=\"text-blue-700 text-sm font-bold uppercase pb-4\">Sports,Fitness</a>\r\n        <a href=\"#\" class=\"text-3xl font-bold hover:text-gray-700 pb-4\">Lorem Ipsum Dolor Sit Amet Dolor Sit Amet</a>\r\n        <p href=\"#\" class=\"text-sm pb-3\">\r\n            By <a href=\"#\" class=\"font-semibold hover:text-gray-800\">David Grzyb</a>, Published on October 22nd, 2019\r\n        </p>\r\n        <a href=\"#\" class=\"pb-6\">Lorem ipsum dolor sit amet, consectetur adipiscing elit. Vivamus quis porta dui. Ut eu\r\n            iaculis massa. Sed ornare ligula lacus, quis iaculis dui porta volutpat. In sit amet posuere magna..</a>\r\n        <a href=\"#\" class=\"uppercase text-gray-800 hover:text-black\">\r\n            Continue Reading\r\n        </a>\r\n    </div>\r\n</article>"
