    "code": "/**\n * Component: IMDB score and votes box\n * Author: @dxgx82 (https://tailwindflex.com/@dxgx82)\n * Source: https://tailwindflex.com/@dxgx82/imdb-score-and-votes-box\n * Attribution: Créé par @dxgx82 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ImdbScoreAndVotesBox() {\n  return (\n    <div>\n    <div className=\"flex flex-col items-center\">\n    <div className=\"imdb-box w-20\">\n      <div className=\"flex flex-col border rounded-md p-1 bg-yellow-400 w-full\">\n          <div className=\"imdb-score text-3xl text-center font-bold\">4.7</div>\n          <div className=\"imdb-title text-center\">IMDb</div>\n          <div className=\"imdb-voted text-xs\">45.7K votes</div>\n      </div>\n    </div>\n    <div className=\"text-xs text-gray-400 mt-5\">\n    Used in project <a className=\"font-bold\" href=\"https://tvfilmai.lt\" target=\"_blank\">tvfilmai.lt</a>\n    </div>\n    </div>\n    </div>\n  );\n}\n",
