    "code": "/**\n * Component: Why Us section with hover animation\n * Author: @amit (https://tailwindflex.com/@amit)\n * Source: https://tailwindflex.com/@amit/why-us-section-with-hover-animation\n * Attribution: Créé par @amit sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function WhyUsSectionWithHoverAnimation() {\n  return (\n    <div>\n    <section className=\"text-gray-700 body-font\">\n      <div className=\"flex justify-center mt-10 text-4xl font-regular\">\n        Why Us?\n      </div>\n      <div className=\"container px-5 py-12 mx-auto\">\n        <div className=\"flex flex-wrap text-center justify-center\">\n          <div className=\"p-4 md1/4 sm1/2\">\n            <div className=\"px-4 py-6 transform transition duration-500 hover110\">\n              <div className=\"flex justify-center\">\n                <img src=\"https://image3.jdomni.in/banner/13062021/58/97/7C/E53960D1295621EFCB5B13F335_1623567851299.png?output-format=webp\" className=\"w-32 mb-3\" />\n              </div>\n              <h2 className=\"title-font font-regular text-2xl text-gray-900\">Latest Milling Machinery</h2>\n            </div>\n          </div>\n    \n          <div className=\"p-4 md1/4 sm1/2\">\n            <div className=\"px-4 py-6 transform transition duration-500 hover110\">\n              <div className=\"flex justify-center\">\n                <img src=\"https://image2.jdomni.in/banner/13062021/3E/57/E8/1D6E23DD7E12571705CAC761E7_1623567977295.png?output-format=webp\" className=\"w-32 mb-3\" />\n              </div>\n              <h2 className=\"title-font font-regular text-2xl text-gray-900\">Reasonable Rates</h2>\n            </div>\n          </div>\n    \n          <div className=\"p-4 md1/4 sm1/2\">\n            <div className=\"px-4 py-6 transform transition duration-500 hover110\">\n              <div className=\"flex justify-center\">\n                <img src=\"https://image3.jdomni.in/banner/13062021/16/7E/7E/5A9920439E52EF309F27B43EEB_1623568010437.png?output-format=webp\" className=\"w-32 mb-3\" />\n              </div>\n              <h2 className=\"title-font font-regular text-2xl text-gray-900\">Time Efficiency</h2>\n            </div>\n          </div>\n    \n          <div className=\"p-4 md1/4 sm1/2\">\n            <div className=\"px-4 py-6 transform transition duration-500 hover110\">\n              <div className=\"flex justify-center\">\n                <img src=\"https://image3.jdomni.in/banner/13062021/EB/99/EE/8B46027500E987A5142ECC1CE1_1623567959360.png?output-format=webp\" className=\"w-32 mb-3\" />\n              </div>\n              <h2 className=\"title-font font-regular text-2xl text-gray-900\">Expertise in Industry</h2>\n            </div>\n          </div>\n    \n        </div>\n      </div>\n    </section>\n    </div>\n  );\n}\n",
    "rawHtml": "<section class=\"text-gray-700 body-font\">\n  <div class=\"flex justify-center mt-10 text-4xl font-regular\">\n    Why Us?\n  </div>\n  <div class=\"container px-5 py-12 mx-auto\">\n    <div class=\"flex flex-wrap text-center justify-center\">\n      <div class=\"p-4 md:w-1/4 sm:w-1/2\">\n        <div class=\"px-4 py-6 transform transition duration-500 hover:scale-110\">\n          <div class=\"flex justify-center\">\n            <img src=\"https://image3.jdomni.in/banner/13062021/58/97/7C/E53960D1295621EFCB5B13F335_1623567851299.png?output-format=webp\" class=\"w-32 mb-3\">\n          </div>\n          <h2 class=\"title-font font-regular text-2xl text-gray-900\">Latest Milling Machinery</h2>\n        </div>\n      </div>\n\n      <div class=\"p-4 md:w-1/4 sm:w-1/2\">\n        <div class=\"px-4 py-6 transform transition duration-500 hover:scale-110\">\n          <div class=\"flex justify-center\">\n            <img src=\"https://image2.jdomni.in/banner/13062021/3E/57/E8/1D6E23DD7E12571705CAC761E7_1623567977295.png?output-format=webp\" class=\"w-32 mb-3\">\n          </div>\n          <h2 class=\"title-font font-regular text-2xl text-gray-900\">Reasonable Rates</h2>\n        </div>\n      </div>\n\n      <div class=\"p-4 md:w-1/4 sm:w-1/2\">\n        <div class=\"px-4 py-6 transform transition duration-500 hover:scale-110\">\n          <div class=\"flex justify-center\">\n            <img src=\"https://image3.jdomni.in/banner/13062021/16/7E/7E/5A9920439E52EF309F27B43EEB_1623568010437.png?output-format=webp\" class=\"w-32 mb-3\">\n          </div>\n          <h2 class=\"title-font font-regular text-2xl text-gray-900\">Time Efficiency</h2>\n        </div>\n      </div>\n\n      <div class=\"p-4 md:w-1/4 sm:w-1/2\">\n        <div class=\"px-4 py-6 transform transition duration-500 hover:scale-110\">\n          <div class=\"flex justify-center\">\n            <img src=\"https://image3.jdomni.in/banner/13062021/EB/99/EE/8B46027500E987A5142ECC1CE1_1623567959360.png?output-format=webp\" class=\"w-32 mb-3\">\n          </div>\n          <h2 class=\"title-font font-regular text-2xl text-gray-900\">Expertise in Industry</h2>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</section>"
