    "code": "/**\n * Component: Simple product card\n * Author: @farid (https://tailwindflex.com/@farid)\n * Source: https://tailwindflex.com/@farid/simple-product-card\n * Attribution: Créé par @farid sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function SimpleProductCard() {\n  return (\n    <div>\n    <div className=\"mx-auto max-w-[475px] min-h-[690px] overflow-hidden rounded-xl bg-white shadow-xl p-8 pt-o relative border border-gray-200\">\n      <span className=\"bg-neutral-300 text-black text-lg mx-auto p-4 rounded-b-lg absolute top-0 shadow-lg inset-x-0 max-w-44 text-center z-1\">October 20th </span>\n      <div className=\"rounded-full aspect-square bg-gray-200 size-1/2 mx-auto mt-12 flex flex-col justify-center items-center\">\n        <svg width=\"36\" height=\"36\" viewBox=\"0 0 36 36\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n          <path d=\"M18 25.1999V28.7999M12.6 30.5999H23.4M7.20001 25.1999H28.8C30.7882 25.1999 32.4 23.5881 32.4 21.5999V8.9999C32.4 7.01168 30.7882 5.3999 28.8 5.3999H7.20001C5.21178 5.3999 3.60001 7.01168 3.60001 8.9999V21.5999C3.60001 23.5881 5.21178 25.1999 7.20001 25.1999Z\" stroke=\"black\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" />\n        </svg>\n    \n      </div>\n      <h3 className=\"text-center text-3xl mt-12\">Online Training</h3>\n      <p className=\"text-xl text-center text-neutral-400 my-8 max-w-[400px] mx-auto\">Lorem ipsum dolor sit amet consecte tur adipiscing elit semper dalar dolor elementum tempus hac.</p>\n      <div className=\"flex flex-col items-center justify-center\">\n        <a href=\"#\" className=\"transition w-64 inline-flex bg-neutral-500 justify-center items-center rounded-full px-6 py-2 text-lg text-center font-medium transition duration-150 ease-in-out px-6 bg-primary text-white hover700 hover focus500 focus focus focus0 active700 mb-8\">Main action</a>\n    \n        <a href=\"\" className=\"transition w-64 border border-neutral-500 inline-flex items-center justify-center rounded-full px-6 py-2 text-lg font-medium transition duration-150 ease-in-out px-6 focus2 focus focus0 hover hover400 hover200 text-neutral-500\">More action</a>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
