    "rawHtml": "<div class=\"w-full min-h-screen flex items-center justify-center bg-gray-200 dark:bg-gray-900\">\r\n\r\n    <div\r\n        class=\"w-full relative md:w-11/12 lg:w-8/12 bg-whie dark:bg-gray-900 border border-gray-300 dark:border-gray-500 rounded-xl pb-6\">\r\n        <h4 class=\"text-left m-4 font-semibold dark:text-white\">Jobs recommended for you</h4>\r\n\r\n        <div class=\"mt-8 flex flex-wrap items-center justify-center gap-4\">\r\n\r\n            <!-- 1 -->\r\n            <div class=\"w-[15rem] flex flex-col bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-500 rounded-xl pb-4\">\r\n                <div\r\n                    class=\"h-[3.5rem] relative rounded-t-xl bg-cover bg-center bg-[url('https://images.unsplash.com/photo-1519389950473-47ba0277781c?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxMXx8Z3JvdXAlMjBwaG90byUyMG9mZmljZXxlbnwwfDB8fHwxNzQ0MTExNDU5fDA&ixlib=rb-4.0.3&q=80&w=1080')]\">\r\n                    <img class=\"absolute -bottom-8 left-2 z-10 w-[3.5rem] h-[3.5rem] rounded object-cover\" src=\"https://images.unsplash.com/photo-1665686310934-8fab52b3821b?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw2fHx3b21hbnxlbnwwfDB8fHwxNzQ0MTExNjkzfDA&ixlib=rb-4.0.3&q=80&w=1080\" alt=\"avater\" />\r\n                </div>\r\n                <div class=\"mt-10 pl-4 w-[88%] flex flex-col\">\r\n                    <h4 class=\"text-[14px] font-semibold dark:text-white\">\r\n                        Arts Project Manager\r\n                        British Council\r\n                    </h4>\r\n                    <p class=\" text-[13px] mt-1 text-gray-600 dark:text-gray-300\">\r\n                        Addis Ababa, Addis Ababa, Ethiopia\r\n                    </p>\r\n\r\n                    <hr class=\"border-[1.5px] w-12 mt-6 mb-2 border-gray-200 dark:border-gray-600 rounded\" />\r\n\r\n                    <p class=\"text-[13px] text-gray-600 dark:text-gray-300\">3 months ago</p>\r\n                </div>\r\n            </div>\r\n            <!-- 2 -->\r\n            <div class=\"w-[15rem] flex flex-col bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-500 rounded-xl pb-4\">\r\n                <div\r\n                    class=\"h-[3.5rem] relative rounded-t-xl bg-cover bg-center bg-[url('https://images.unsplash.com/photo-1451187580459-43490279c0fa?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw5fHxjb3ZlcnxlbnwwfDB8fHwxNzQ0MDIxNjg5fDA&ixlib=rb-4.0.3&q=80&w=1080')]\">\r\n                    <img class=\"absolute -bottom-8 left-2 z-10 w-[3.5rem] h-[3.5rem] rounded object-cover\" src=\"https://images.unsplash.com/photo-1511367461989-f85a21fda167?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxfHxwcm9maWxlfGVufDB8MHx8fDE3NDQwMjIxMjR8MA&ixlib=rb-4.0.3&q=80&w=1080\" alt=\"avater\" />\r\n                </div>\r\n                <div class=\"mt-10 pl-4 w-[88%] flex flex-col\">\r\n                    <h4 class=\"text-[14px] font-semibold dark:text-white\">\r\n                        Project Coordinator- (SALSA Project)\r\n                        ABH PARTNERS PLC</h4>\r\n                    <p class=\" text-[13px] mt-1 text-gray-600 dark:text-gray-300\">\r\n                        Addis Ababa, Addis Ababa, Ethiopia\r\n                    </p>\r\n\r\n                    <hr class=\"border-[1.5px] w-12 mt-6 mb-2 border-gray-200 rounded dark:border-gray-600\" />\r\n\r\n                    <p class=\"text-[13px] text-gray-600 dark:text-gray-300\">3 months ago</p>\r\n                </div>\r\n            </div>\r\n            <!-- 3 -->\r\n            <div class=\"w-[15rem] flex flex-col bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-500 rounded-xl pb-4\">\r\n                <div\r\n                    class=\"h-[3.5rem] relative rounded-t-xl bg-cover bg-center bg-[url('https://images.unsplash.com/photo-1504805572947-34fad45aed93?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxMnx8Z3JvdXAlMjBwaG90byUyMG9mZmljZXxlbnwwfDB8fHwxNzQ0MTExNDU5fDA&ixlib=rb-4.0.3&q=80&w=1080')]\">\r\n                    <img class=\"absolute -bottom-8 left-2 z-10 w-[3.5rem] h-[3.5rem] rounded object-cover\" src=\"https://images.unsplash.com/photo-1507679799987-c73779587ccf?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxMHx8bWFufGVufDB8MHx8fDE3NDQxMTE2MzZ8MA&ixlib=rb-4.0.3&q=80&w=1080\" alt=\"avater\" />\r\n                </div>\r\n                <div class=\"mt-10 pl-4 w-[88%] flex flex-col\">\r\n                    <h4 class=\"text-[14px] font-semibold dark:text-white\">\r\n                        Project Coordinator- (SALSA Project)\r\n                        ABH PARTNERS PLC</h4>\r\n                    <p class=\" text-[13px] mt-1 text-gray-600 dark:text-gray-300\">\r\n                        Addis Ababa, Addis Ababa, Ethiopia\r\n                    </p>\r\n\r\n                    <hr class=\"border-[1.5px] w-12 mt-6 mb-2 border-gray-200 dark:text-gray-600 rounded\" />\r\n\r\n                    <p class=\"text-[13px] text-gray-600 dark:text-gray-300\">3 months ago</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</div>"
