    "code": "/**\n * Component: zoom in effect card\n * Author: @anum-shahana (https://tailwindflex.com/@anum-shahana)\n * Source: https://tailwindflex.com/@anum-shahana/zoom-in-effect-card\n * Attribution: Créé par @anum-shahana sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ZoomInEffectCard() {\n  return (\n    <div>\n    <div className=\"bg-white dark800 flex justify-center items-center w-screen h-screen p-5\">\n      <div className=\"border shadow-teal-300 shadow-md max-w-xl p-2 rounded-lg dark700 dark300\">\n        \n        <div className=\"overflow-hidden\">\n          <img \n            src=\"https://i0.wp.com/picjumbo.com/wp-content/uploads/beautiful-nature-mountain-scenery-with-flowers-free-photo.jpg?w=2210&quality=70\" \n            alt=\"Scenic View\" \n            className=\"w-full h-auto transition-transform duration-300 ease-in-out hover110\" \n          />\n        </div>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
