    "rawHtml": "<div class=\"flex space-x-5\">\n\n<div class=\"white w-fit p-20 border-2 border border-green-500 rounded-2xl\">\n<div class=\"flex justify-center items-center\">\n<div class=\"flex justify-evenly items-center w-24 h-12 border-4 border-gray-300 rounded-lg bg-white\">\n  <div class=\"w-3 h-8 bg-green-500 \"></div>\n  <div class=\"w-3 h-8 bg-green-500\"></div>\n  <div class=\"w-3 h-8 bg-green-500\"></div>\n  <div class=\"w-3 h-8 bg-green-500\"></div>\n  <div class=\"w-3 h-8 bg-gray-300\"></div> \n</div>\n<div class=\"w-2 h-4 bg-gray-300 rounded-tr-sm rounded-br-sm\"></div>\n</div>\n</div>\n\n<div class=\"white w-fit p-20 border-2 border border-green-500 rounded-2xl\">\n  <div class=\"flex justify-evenly items-end w-24 h-12 rounded-lg bg-white\">\n  <div class=\"w-3 h-4 bg-green-500 rounded-full\"></div>\n  <div class=\"w-3 h-6 bg-green-500 rounded-full\"></div>\n  <div class=\"w-3 h-8 bg-green-500 rounded-full\"></div>\n  <div class=\"w-3 h-10 bg-green-500 rounded-full\"></div>\n  <div class=\"w-3 h-12 bg-gray-300 rounded-full\"></div>\n  </div>\n</div>\n\n</div>"
