    "code": "/**\n * Component: Personal card\n * Author: @farid (https://tailwindflex.com/@farid)\n * Source: https://tailwindflex.com/@farid/personal-card\n * Attribution: Créé par @farid sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function PersonalCard() {\n  return (\n    <div>\n    <article className=\"mx-auto flex flex-col items-center justify-between p-4 py-8 text-center transition-all bg-white dark800 border-2 rounded border-gray-200 dark600 text-black dark max-w-min hover\">\n        <picture className=\"w-40 overflow-hidden border-8 rounded-full fade-in aspect-square border-orange-200 dark600 transition duration-300 hover4\">\n          <img alt=\"photo\" src=\"data/svg+xml,%3Csvg width='800px' height='800px' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M8 7C9.65685 7 11 5.65685 11 4C11 2.34315 9.65685 1 8 1C6.34315 1 5 2.34315 5 4C5 5.65685 6.34315 7 8 7Z' fill='%23ccc'/%3E%3Cpath d='M14 12C14 10.3431 12.6569 9 11 9H5C3.34315 9 2 10.3431 2 12V15H14V12Z' fill='%23cccccc'/%3E%3C/svg%3E\" className=\"hover110 transition duration-300\" />\n        </picture>\n        <h3 className=\"py-2 mb-4 font-semibold xl\">\n          Name Surname\n        </h3>\n    \n        <h4 className=\"mb-0\">Position</h4>\n        <p className=\"mb-0\">email.com</p>\n        <p className=\"font-bold\">+1 23456789</p>\n      </article>\n    </div>\n  );\n}\n",
