    "code": "/**\n * Component: News Feed\n * Author: @sammytg7 (https://tailwindflex.com/@sammytg7)\n * Source: https://tailwindflex.com/@sammytg7/news-feed-2\n * Attribution: Créé par @sammytg7 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function NewsFeed2() {\n  return (\n    <div>\n    <div className=\"w-full min-h-screen flex flex-col items-center justify-center py-10\">\n      <span className=\"text-md md font-bold text-[#117278] flex items-center gap-1\"><ion-icon name=\"heart-outline\"></ion-icon>Our Insights</span>\n      <h2 className=\"text-4xl sm5xl md7xl text-center chelsea-market-regular font-bold text-[#117278] md16 mb-10\">News Feeds</h2>\n    \n      <div className=\"px-4 md[2rem] xl[6rem] flex flex-col lg gap-10\">\n        \n        <div className=\"lg[80%] xl[60%]\">\n          \n          <img className=\"w-full object-cover h-[12rem] md[18rem] aspect-square\" src=\"https://images.unsplash.com/photo-1498050108023-c5249f4df085?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxfHx3ZWJ8ZW58MHwwfHx8MTc2NDA1NTA0MXww&ixlib=rb-4.1.0&q=80&w=1080\" alt=\"blog image\" />\n    \n          <div className=\"flex flex-col px-6 py-8 border-l border-r border-b\">\n            \n            <div className=\"flex gap-4 text-sm text-gray-700 font-semibold\">\n              <span className=\"flex gap-1 items-center\"><ion-icon name=\"person-outline\"></ion-icon>By Sammytg7</span>\n              <span className=\"flex gap-1 items-center\"><ion-icon className=\"-rotate-90\" name=\"pricetags-outline\"></ion-icon>TechNews</span>\n            </div>\n            \n            <h3 className=\"text-2xl md3xl font-semibold text-teal-900 chelsea-market-regular\">A Beginner's Guide to Modern Web Design</h3>\n            \n            <p className=\"text-md text-gray-500\">Step into the world of Tailwind CSS with this beginner-friendly guide. Learn\n              the basics of Tailwind's utility classes, responsive design features, and customization options to kickstart\n              your journey in modern web design.</p>\n          </div>\n        </div>\n    \n    \n        \n        <div className=\"w-full flex flex-col items-stretch justify-center\">\n          \n          <div className=\"flex flex-col sm gap-6 pb-6 border-b-2 border-gray-100\">\n            \n            <div className=\"w-full h-[7rem] sm[10rem] sm[10rem] aspect-square rounded-l px-6 py-2 bg-yellow-500 text-white flex flex-col items-center justify-center\">\n              <span className=\"text-7xl font-semibold\">13</span>\n              <span className=\"font-semibold\">January</span>\n            </div>\n            \n            <div className=\"flex flex-col justify-between\">\n              \n              <div className=\"flex md4 gap-2 text-sm text-gray-700 font-semibold\">\n                <span className=\"flex gap-1 items-center\"><ion-icon name=\"person-outline\"></ion-icon>By Sammytg7</span>\n                <span className=\"flex gap-1 items-center\"><ion-icon className=\"-rotate-90\" name=\"pricetags-outline\"></ion-icon>TechNews</span>\n              </div>\n              \n              <h3 className=\"text-2xl md3xl font-semibold text-teal-900 capitalize chelsea-market-regular\">Effortless Styling: Unleashing the Power of\n                Tailwind CSS</h3>\n              \n              <p className=\"text-md text-gray-500\">Discover how Tailwind CSS revolutionizes web development with its\n                utility-first approach.</p>\n            </div>\n          </div>\n    \n          \n          <div className=\"flex flex-col sm gap-6 pb-6 border-b-2 border-gray-100\">\n            \n            <div className=\"w-full h-[7rem] sm[10rem] sm[10rem] aspect-square rounded-l px-6 py-2 bg-teal-500 text-white flex flex-col items-center justify-center\">\n              <span className=\"text-7xl font-semibold\">13</span>\n              <span className=\"font-semibold\">January</span>\n            </div>\n            \n            <div className=\"flex flex-col justify-between\">\n              \n              <div className=\"flex md4 gap-2 text-sm text-gray-700 font-semibold\">\n                <span className=\"flex gap-1 items-center\"><ion-icon name=\"person-outline\"></ion-icon>By Sammytg7</span>\n                <span className=\"flex gap-1 items-center\"><ion-icon className=\"-rotate-90\" name=\"pricetags-outline\"></ion-icon>TechNews</span>\n              </div>\n              \n              <h3 className=\"text-2xl md3xl font-semibold text-teal-900 capitalize chelsea-market-regular\">Tailwind CSS Pro Tips: Advanced Techniques for\n                Stunning Web Interfaces</h3>\n              \n              <p className=\"text-md text-gray-500\">Elevate your web design skills with advanced tips and tricks for Tailwind\n                CSS. Uncover techniques for optimizing your workflow</p>\n            </div>\n          </div>\n    \n          \n          <div className=\"flex flex-col sm gap-6 pb-6 border-b-2 border-gray-100\">\n            \n            <div className=\"w-full h-[7rem] sm[10rem] sm[10rem] aspect-square rounded-l px-6 py-2 bg-red-500 text-white flex flex-col items-center justify-center\">\n              <span className=\"text-7xl font-semibold\">13</span>\n              <span className=\"font-semibold\">January</span>\n            </div>\n            \n            <div className=\"flex flex-col justify-between\">\n              \n              <div className=\"flex md4 gap-2 text-sm text-gray-700 font-semibold\">\n                <span className=\"flex gap-1 items-center\"><ion-icon name=\"person-outline\"></ion-icon>By Sammytg7</span>\n                <span className=\"flex gap-1 items-center\"><ion-icon className=\"-rotate-90\" name=\"pricetags-outline\"></ion-icon>TechNews</span>\n              </div>\n              \n              <h3 className=\"text-2xl md3xl font-semibold text-teal-900 capitalize chelsea-market-regular\">Responsive Design Made Easy: Harnessing Tailwind\n                CSS for Mobile-First Websites</h3>\n              \n              <p className=\"text-md text-gray-500\">Explore how Tailwind CSS simplifies responsive design for mobile-first\n                websites.</p>\n            </div>\n          </div>\n    \n        </div>\n      </div>\n    </div>\n    \n    \n    \n    \n    </div>\n  );\n}\n",
