    "code": "/**\n * Component: Feature Section Cards\n * Author: @akram6t (https://tailwindflex.com/@akram6t)\n * Source: https://tailwindflex.com/@akram6t/feature-section-cards\n * Attribution: Créé par @akram6t sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function FeatureSectionCards() {\n  return (\n    <div>\n    \n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\" />\n    \n    \n    <div className=\"features\">\n        <div className=\"feature\">\n            <i className=\"feature-icon fas fa-rocket\"></i>\n            <h3 className=\"feature-title\">Blazing Fast</h3>\n            <p className=\"feature-description\">Experience lightning-quick load times and smooth interactions that push the\n                boundaries of web performance.</p>\n        </div>\n        <div className=\"feature\">\n            <i className=\"feature-icon fas fa-paint-brush\"></i>\n            <h3 className=\"feature-title\">Stunning Design</h3>\n            <p className=\"feature-description\">Immerse yourself in a visually captivating interface that combines futuristic\n                aesthetics with intuitive usability.</p>\n        </div>\n        <div className=\"feature\">\n            <i className=\"feature-icon fas fa-shield-alt\"></i>\n            <h3 className=\"feature-title\">Robust Security</h3>\n            <p className=\"feature-description\">Rest easy knowing your data is protected by state-of-the-art security\n                measures and encryption protocols.</p>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<!-- Add Icons link -->\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n\n\n<div class=\"features\">\n    <div class=\"feature\">\n        <i class=\"feature-icon fas fa-rocket\"></i>\n        <h3 class=\"feature-title\">Blazing Fast</h3>\n        <p class=\"feature-description\">Experience lightning-quick load times and smooth interactions that push the\n            boundaries of web performance.</p>\n    </div>\n    <div class=\"feature\">\n        <i class=\"feature-icon fas fa-paint-brush\"></i>\n        <h3 class=\"feature-title\">Stunning Design</h3>\n        <p class=\"feature-description\">Immerse yourself in a visually captivating interface that combines futuristic\n            aesthetics with intuitive usability.</p>\n    </div>\n    <div class=\"feature\">\n        <i class=\"feature-icon fas fa-shield-alt\"></i>\n        <h3 class=\"feature-title\">Robust Security</h3>\n        <p class=\"feature-description\">Rest easy knowing your data is protected by state-of-the-art security\n            measures and encryption protocols.</p>\n    </div>\n</div>"
