    "rawHtml": "<!DOCTYPE html>\n<html lang=\"es\" class=\"\">\n\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale-1.0\">\n  <title>Tarjetas de Blog Impactantes</title>\n\n\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n  <style>\n    body {\n      font-family: 'Inter', sans-serif;\n    }\n  </style>\n</head>\n\n<body class=\"bg-gray-100 dark:bg-gray-900 min-h-screen p-8 transition-colors duration-300\">\n\n  <div class=\"max-w-7xl mx-auto\">\n\n\n\n    <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8\">\n\n\n      <a href=\"#\" class=\"group relative block h-96 rounded-2xl overflow-hidden shadow-xl\"\n        aria-label=\"Leer artículo sobre El Futuro de la IA\">\n\n\n        <img src=\"https://placehold.co/600x400/0E7490/FFFFFF?text=IA\"\n                     alt=\"\"\n                     class=\"absolute inset-0 w-full h-full object-cover transition-transform duration-500 ease-in-out group-hover:scale-110\"/>\n\n        <div class=\"absolute inset-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent\"></div>\n\n\n        <div class=\"absolute bottom-0 left-0 p-6 text-white\">\n          <span class=\"bg-cyan-600 px-3 py-1 rounded-full text-xs font-semibold uppercase tracking-wider\">Tecnología</span>\n          <h3 class=\"text-2xl font-bold mt-3 transition-colors duration-300 group-hover:text-cyan-300\">\n            El Futuro de la IA: Más Allá de los Modelos de Lenguaje\n          </h3>\n\n\n          <div class=\"flex items-center mt-4 space-x-2\">\n            <img class=\"w-8 h-8 rounded-full object-cover\" src=\"https://placehold.co/40x40/E2E8F0/333333?text=A1\" alt=\"Avatar del autor\">\n            <div>\n              <p class=\"text-sm font-medium text-gray-200\">Ana Torres</p>\n              <p class=\"text-xs text-gray-400\">Hace 2 días</p>\n            </div>\n          </div>\n        </div>\n\n\n        <div\n          class=\"absolute top-6 right-6 p-2 bg-white/20 rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-300 scale-90 group-hover:scale-100\">\n          <svg class=\"w-5 h-5 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"\n            xmlns=\"http://www.w3.org/2000/svg\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"></path>\n          </svg>\n        </div>\n      </a>\n\n      <a href=\"#\" class=\"group relative block h-96 rounded-2xl overflow-hidden shadow-xl\"\n        aria-label=\"Leer artículo sobre Principios de Diseño UI\">\n\n        <img src=\"https://placehold.co/600x400/7C3AED/FFFFFF?text=Diseño\"\n                     alt=\"\"\n                     class=\"absolute inset-0 w-full h-full object-cover transition-transform duration-500 ease-in-out group-hover:scale-110\"/>\n\n        <div class=\"absolute inset-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent\"></div>\n\n        <div class=\"absolute bottom-0 left-0 p-6 text-white\">\n          <span class=\"bg-purple-600 px-3 py-1 rounded-full text-xs font-semibold uppercase tracking-wider\">Diseño</span>\n          <h3 class=\"text-2xl font-bold mt-3 transition-colors duration-300 group-hover:text-purple-300\">\n            Los 5 Principios del Diseño UI que No Puedes Ignorar\n          </h3>\n\n          <div class=\"flex items-center mt-4 space-x-2\">\n            <img class=\"w-8 h-8 rounded-full object-cover\" src=\"https://placehold.co/40x40/E2E8F0/333333?text=M2\" alt=\"Avatar del autor\">\n            <div>\n              <p class=\"text-sm font-medium text-gray-200\">Marcos Reyes</p>\n              <p class=\"text-xs text-gray-400\">Hace 1 semana</p>\n            </div>\n          </div>\n        </div>\n\n        <div\n          class=\"absolute top-6 right-6 p-2 bg-white/20 rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-300 scale-90 group-hover:scale-100\">\n          <svg class=\"w-5 h-5 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"\n            xmlns=\"http://www.w3.org/2000/svg\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"></path>\n          </svg>\n        </div>\n      </a>\n\n\n      <a href=\"#\" class=\"group relative block h-96 rounded-2xl overflow-hidden shadow-xl\"\n        aria-label=\"Leer artículo sobre Guía de Viaje a la Patagonia\">\n\n        <img src=\"https://placehold.co/600x400/059669/FFFFFF?text=Viajes\"\n                     alt=\"\"\n                     class=\"absolute inset-0 w-full h-full object-cover transition-transform duration-500 ease-in-out group-hover:scale-110\"/>\n\n        <div class=\"absolute inset-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent\"></div>\n\n        <div class=\"absolute bottom-0 left-0 p-6 text-white\">\n          <span class=\"bg-green-600 px-3 py-1 rounded-full text-xs font-semibold uppercase tracking-wider\">Viajes</span>\n          <h3 class=\"text-2xl font-bold mt-3 transition-colors duration-300 group-hover:text-green-300\">\n            Guía Definitiva para tu Aventura en la Patagonia\n          </h3>\n\n          <div class=\"flex items-center mt-4 space-x-2\">\n            <img class=\"w-8 h-8 rounded-full object-cover\" src=\"https://placehold.co/40x40/E2E8F0/333333?text=C3\" alt=\"Avatar del autor\">\n            <div>\n              <p class=\"text-sm font-medium text-gray-200\">Carla Gómez</p>\n              <p class=\"text-xs text-gray-400\">Hace 3 horas</p>\n            </div>\n          </div>\n        </div>\n\n        <div\n          class=\"absolute top-6 right-6 p-2 bg-white/20 rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-300 scale-90 group-hover:scale-100\">\n          <svg class=\"w-5 h-5 text-white\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"\n            xmlns=\"http://www.w3.org/2000/svg\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"></path>\n          </svg>\n        </div>\n      </a>\n\n    </div>\n  </div>\n\n\n</body>\n\n</html>"
