    "code": "/**\n * Component: 3d card\n * Author: @irahoza-daniel (https://tailwindflex.com/@irahoza-daniel)\n * Source: https://tailwindflex.com/@irahoza-daniel/3d-card\n * Attribution: Créé par @irahoza-daniel sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function Comp3dCard() {\n  return (\n    <div dangerouslySetInnerHTML={{ __html: \"<!DOCTYPE html>\\n<html lang=\\\"en\\\">\\n<head>\\n  <meta charset=\\\"UTF-8\\\">\\n  <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n  <title>3D Profile Card</title>\\n  \\n  <style>\\n    .perspective {\\n      perspective: 1500px;\\n    }\\n    .card-3d {\\n      transform-style: preserve-3d;\\n      transition: transform 0.5s ease;\\n    }\\n    .card-3d:hover {\\n      transform: rotateY(10deg) rotateX(5deg);\\n    }\\n    .bg-3d {\\n      background: linear-gradient(135deg, #6b46c1 0%, #3b82f6 100%);\\n      transform: translateZ(-50px);\\n    }\\n    .floating {\\n      animation: float 6s ease-in-out infinite;\\n    }\\n    @keyframes float {\\n      0%, 100% { transform: translateY(0) translateZ(20px); }\\n      50% { transform: translateY(-20px) translateZ(20px); }\\n    }\\n  </style>\\n</head>\\n<body class=\\\"bg-gray-900 flex items-center justify-center min-h-screen perspective overflow-hidden\\\">\\n  <!-- 3D Background Elements -->\\n  <div class=\\\"fixed inset-0 overflow-hidden\\\">\\n    <div class=\\\"absolute top-20 left-20 w-40 h-40 rounded-full bg-purple-500 opacity-20 blur-xl floating\\\" style=\\\"animation-delay: 0s;\\\"></div>\\n    <div class=\\\"absolute bottom-40 right-32 w-64 h-64 rounded-full bg-blue-500 opacity-20 blur-xl floating\\\" style=\\\"animation-delay: 2s;\\\"></div>\\n    <div class=\\\"absolute top-1/3 right-1/4 w-32 h-32 rounded-lg bg-indigo-500 opacity-15 blur-lg floating\\\" style=\\\"animation-delay: 4s;\\\"></div>\\n  </div>\\n\\n  <!-- 3D Card -->\\n  <div class=\\\"card-3d relative z-10 w-full max-w-sm mx-4\\\">\\n    <div class=\\\"bg-3d rounded-2xl shadow-2xl overflow-hidden\\\">\\n      <!-- Profile Image (Floating) -->\\n      <div class=\\\"relative -mt-16 flex justify-center\\\">\\n        <div class=\\\"floating\\\">\\n          <img \\n            src=\\\"https://images.unsplash.com/photo-1633332755192-727a05c4013d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8dXNlcnxlbnwwfHwwfHx8MA%3D%3D&auto=format&fit=crop&w=500&q=60\\\" \\n            alt=\\\"Profile\\\" \\n            class=\\\"w-32 h-32 rounded-full border-4 border-white object-cover shadow-xl\\\"\\n          >\\n        </div>\\n      </div>\\n\\n      <!-- Content -->\\n      <div class=\\\"px-8 py-6 text-center bg-white/90 backdrop-blur-sm\\\">\\n        <h1 class=\\\"text-2xl font-bold text-gray-800\\\">Alex Johnson</h1>\\n        <p class=\\\"text-blue-600 font-medium mt-1\\\">Senior Marketing Consultant</p>\\n        \\n        <p class=\\\"mt-4 text-gray-600\\\">\\n          Helping businesses grow through strategic marketing solutions.\\n        </p>\\n\\n        <!-- Stats -->\\n        <div class=\\\"flex justify-between mt-6 pt-4 border-t border-gray-200\\\">\\n          <div>\\n            <p class=\\\"text-gray-500 text-sm\\\">Projects</p>\\n            <p class=\\\"font-bold text-gray-800\\\">120+</p>\\n          </div>\\n          <div>\\n            <p class=\\\"text-gray-500 text-sm\\\">Clients</p>\\n            <p class=\\\"font-bold text-gray-800\\\">45+</p>\\n          </div>\\n          <div>\\n            <p class=\\\"text-gray-500 text-sm\\\">Experience</p>\\n            <p class=\\\"font-bold text-gray-800\\\">8 yrs</p>\\n          </div>\\n        </div>\\n      </div>\\n\\n      <!-- Glowing Border Effect -->\\n      <div class=\\\"absolute inset-0 rounded-2xl border-2 border-white/10 pointer-events-none\\\"></div>\\n    </div>\\n  </div>\\n\\n  <!-- Optional: Tilt effect on mouse move -->\\n  \\n</body>\\n</html>\" }} />\n  );\n}\n",
    "rawHtml": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>3D Profile Card</title>\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <style>\n    .perspective {\n      perspective: 1500px;\n    }\n    .card-3d {\n      transform-style: preserve-3d;\n      transition: transform 0.5s ease;\n    }\n    .card-3d:hover {\n      transform: rotateY(10deg) rotateX(5deg);\n    }\n    .bg-3d {\n      background: linear-gradient(135deg, #6b46c1 0%, #3b82f6 100%);\n      transform: translateZ(-50px);\n    }\n    .floating {\n      animation: float 6s ease-in-out infinite;\n    }\n    @keyframes float {\n      0%, 100% { transform: translateY(0) translateZ(20px); }\n      50% { transform: translateY(-20px) translateZ(20px); }\n    }\n  </style>\n</head>\n<body class=\"bg-gray-900 flex items-center justify-center min-h-screen perspective overflow-hidden\">\n  <!-- 3D Background Elements -->\n  <div class=\"fixed inset-0 overflow-hidden\">\n    <div class=\"absolute top-20 left-20 w-40 h-40 rounded-full bg-purple-500 opacity-20 blur-xl floating\" style=\"animation-delay: 0s;\"></div>\n    <div class=\"absolute bottom-40 right-32 w-64 h-64 rounded-full bg-blue-500 opacity-20 blur-xl floating\" style=\"animation-delay: 2s;\"></div>\n    <div class=\"absolute top-1/3 right-1/4 w-32 h-32 rounded-lg bg-indigo-500 opacity-15 blur-lg floating\" style=\"animation-delay: 4s;\"></div>\n  </div>\n\n  <!-- 3D Card -->\n  <div class=\"card-3d relative z-10 w-full max-w-sm mx-4\">\n    <div class=\"bg-3d rounded-2xl shadow-2xl overflow-hidden\">\n      <!-- Profile Image (Floating) -->\n      <div class=\"relative -mt-16 flex justify-center\">\n        <div class=\"floating\">\n          <img \n            src=\"https://images.unsplash.com/photo-1633332755192-727a05c4013d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8dXNlcnxlbnwwfHwwfHx8MA%3D%3D&auto=format&fit=crop&w=500&q=60\" \n            alt=\"Profile\" \n            class=\"w-32 h-32 rounded-full border-4 border-white object-cover shadow-xl\"\n          >\n        </div>\n      </div>\n\n      <!-- Content -->\n      <div class=\"px-8 py-6 text-center bg-white/90 backdrop-blur-sm\">\n        <h1 class=\"text-2xl font-bold text-gray-800\">Alex Johnson</h1>\n        <p class=\"text-blue-600 font-medium mt-1\">Senior Marketing Consultant</p>\n        \n        <p class=\"mt-4 text-gray-600\">\n          Helping businesses grow through strategic marketing solutions.\n        </p>\n\n        <!-- Stats -->\n        <div class=\"flex justify-between mt-6 pt-4 border-t border-gray-200\">\n          <div>\n            <p class=\"text-gray-500 text-sm\">Projects</p>\n            <p class=\"font-bold text-gray-800\">120+</p>\n          </div>\n          <div>\n            <p class=\"text-gray-500 text-sm\">Clients</p>\n            <p class=\"font-bold text-gray-800\">45+</p>\n          </div>\n          <div>\n            <p class=\"text-gray-500 text-sm\">Experience</p>\n            <p class=\"font-bold text-gray-800\">8 yrs</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- Glowing Border Effect -->\n      <div class=\"absolute inset-0 rounded-2xl border-2 border-white/10 pointer-events-none\"></div>\n    </div>\n  </div>\n\n  <!-- Optional: Tilt effect on mouse move -->\n  <script>\n    document.querySelector('.card-3d').addEventListener('mousemove', (e) => {\n      const xAxis = (window.innerWidth / 2 - e.pageX) / 25;\n      const yAxis = (window.innerHeight / 2 - e.pageY) / 25;\n      e.currentTarget.style.transform = `rotateY(${xAxis}deg) rotateX(${yAxis}deg) translateZ(20px)`;\n    });\n    document.querySelector('.card-3d').addEventListener('mouseleave', (e) => {\n      e.currentTarget.style.transform = 'rotateY(0) rotateX(0)';\n    });\n  </script>\n</body>\n</html>"
