    "code": "/**\n * Component: Food Ordering Dashboard\n * Author: @umairarshad-dev (https://tailwindflex.com/@umairarshad-dev)\n * Source: https://tailwindflex.com/@umairarshad-dev/food-ordering-dashboard\n * Attribution: Créé par @umairarshad-dev sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function FoodOrderingDashboard() {\n  return (\n    <div>\n    <div className=\"w-full h-full bg-rose-100/30 dark[#1b1b1b] py-16\">\n      <div className=\"max-w-6xl mx-auto flex flex-col justify-center items-center\">\n        \n        <p className=\"pb-2 text-lg lg2xl text-rose-600 font-semibold\">Category</p>\n        <h2 className=\"text-3xl lg5xl text-center font-serif font-semibold mb-12 dark\">\n          Choose Your Best Food\n        </h2>\n    \n        \n        <div className=\"flex flex-wrap gap-8 justify-center items-center\">\n          \n          <div\n            className=\"group w-[18rem] sm[20rem] bg-white dark[#262525] rounded-2xl overflow-hidden shadow-lg hover2xl transition-all duration-300 transform hover105\">\n            <img\n              className=\"w-full h-[14rem] object-cover\"\n              src=\"https://images.unsplash.com/photo-1600891964599-f61ba0e24092?auto=format&fit=crop&w=800&q=80\"\n              alt=\"Sushi\"\n            />\n            <div className=\"p-5\">\n              <h2 className=\"text-2xl font-semibold mb-1 group-hover600 dark\">Sushi Delight</h2>\n              <p className=\"text-gray-700 dark300 mb-4\">Salmon, Rice & Avocado</p>\n              <div className=\"flex justify-between items-center mb-4\">\n                <div className=\"flex -space-x-3\">\n                  <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/women/68.jpg\" alt=\"\" />\n                  <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/men/45.jpg\" alt=\"\" />\n                  <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/women/52.jpg\" alt=\"\" />\n                </div>\n                <div className=\"flex items-center text-yellow-500 text-xl font-bold\">\n                  <ion-icon name=\"star\"></ion-icon>\n                  <span className=\"text-black dark ml-1\">4.9</span>\n                </div>\n              </div>\n              <button\n                className=\"w-full py-2 border border-rose-600 dark500 text-rose-700 dark rounded-full uppercase font-bold transition duration-300 hover600 hover dark dark\">\n                Order now\n              </button>\n            </div>\n          </div>\n    \n          \n     <div\n      className=\"group w-[18rem] sm[20rem] bg-white dark[#262525] rounded-2xl overflow-hidden shadow-lg hover2xl transition-all duration-300 transform hover105\">\n       <img\n              className=\"w-full h-[14rem] object-cover\"\n              src=\"https://images.unsplash.com/photo-1600891964599-f61ba0e24092?auto=format&fit=crop&w=800&q=80\"\n              alt=\"Sushi\"\n            />\n      <div className=\"p-5\">\n        <h2 className=\"text-2xl font-semibold mb-1 group-hover600 dark\">Creamy Pasta</h2>\n        <p className=\"text-gray-700 dark300 mb-4\">Cream, Cheese & Basil</p>\n        <div className=\"flex items-center justify-between\">\n          <div className=\"flex -space-x-3\">\n            <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/men/11.jpg\" alt=\"\" />\n            <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/men/12.jpg\" alt=\"\" />\n            <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/men/13.jpg\" alt=\"\" />\n          </div>\n          <span className=\"flex items-center text-yellow-500 font-semibold text-lg\">\n            <svg className=\"w-5 h-5 mr-1\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n              <path d=\"M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.186 3.655a1 1 0 00.95.69h3.813c.969 0 1.371 1.24.588 1.81l-3.087 2.24a1 1 0 00-.364 1.118l1.186 3.655c.3.921-.755 1.688-1.54 1.118l-3.087-2.24a1 1 0 00-1.175 0l-3.087 2.24c-.785.57-1.84-.197-1.54-1.118l1.186-3.655a1 1 0 00-.364-1.118L2.421 9.082c-.783-.57-.38-1.81.588-1.81h3.813a1 1 0 00.95-.69l1.186-3.655z\"/>\n            </svg>\n            4.8\n          </span>\n        </div>\n        <button\n          className=\"mt-4 w-full border border-rose-500 text-rose-500 hover500 hover font-semibold py-2 px-4 rounded-full transition duration-300\">\n          ORDER NOW\n        </button>\n      </div>\n    </div>\n    \n    \n          \n          <div\n            className=\"group w-[18rem] sm[20rem] bg-white dark[#262525] rounded-2xl overflow-hidden shadow-lg hover2xl transition-all duration-300 transform hover105\">\n             <img\n              className=\"w-full h-[14rem] object-cover\"\n              src=\"https://images.unsplash.com/photo-1600891964599-f61ba0e24092?auto=format&fit=crop&w=800&q=80\"\n              alt=\"Sushi\"\n            />\n    \n            <div className=\"p-5\">\n              <h2 className=\"text-2xl font-semibold mb-1 group-hover600 dark\">Chocolate Bliss</h2>\n              <p className=\"text-gray-700 dark300 mb-4\">Dark Chocolate & Cream</p>\n              <div className=\"flex justify-between items-center mb-4\">\n                <div className=\"flex -space-x-3\">\n                  <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/women/25.jpg\" alt=\"\" />\n                  <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/men/21.jpg\" alt=\"\" />\n                  <img className=\"w-9 h-9 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/women/62.jpg\" alt=\"\" />\n                </div>\n                <div className=\"flex items-center text-yellow-500 text-xl font-bold\">\n                  <ion-icon name=\"star\"></ion-icon>\n                  <span className=\"text-black dark ml-1\">5.0</span>\n                </div>\n              </div>\n              <button\n                className=\"w-full py-2 border border-rose-600 dark500 text-rose-700 dark rounded-full uppercase font-bold transition duration-300 hover600 hover dark dark\">\n                Order now\n              </button>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n    \n    \n    \n    \n    </div>\n  );\n}\n",
