    "code": "/**\n * Component: image\n * Author: @pablitodgb (https://tailwindflex.com/@pablitodgb)\n * Source: https://tailwindflex.com/@pablitodgb/rgsgsd\n * Attribution: Créé par @pablitodgb sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function Rgsgsd() {\n  return (\n    <div>\n    <div className=\"h-dvh w-dvh text-slate-100 bg-gradient-to-t from-slate-400 to-gray-300 flex justify-center items-center dark600 dark700 dark200\">\n      <div className=\"p-1 m-1 space-y-2 h-full overflow-auto min-w-xs w-full max-w-full bg-transparent place-items-center grid grid-cols-1 sm2 md3 lg4 xl5 gap-2 outline outline-2 outline-slate-200 shadow-xl dark300 dark500 rounded-xl\">\n        <img className=\"w-52 h-52 object-cover rounded-full outline outline-2 outline-slate-200 shadow-xl dark300 dark500\" src=\"https://images.unsplash.com/photo-1591475247035-5b01b01636b3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw3fHxsYW5kfGVufDB8MXx8fDE3NTEyMTY1Njh8MA&ixlib=rb-4.1.0&q=80&w=1080\" alt=\"#\"/>\n        <img className=\"w-52 h-52 object-cover rounded-full outline outline-2 outline-slate-200 shadow-xl dark300 dark500\" src=\"https://images.unsplash.com/photo-1591475247035-5b01b01636b3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw3fHxsYW5kfGVufDB8MXx8fDE3NTEyMTY1Njh8MA&ixlib=rb-4.1.0&q=80&w=1080\" alt=\"#\"/>\n        <img className=\"w-52 h-52 object-cover rounded-full outline outline-2 outline-slate-200 shadow-xl dark300 dark500\" src=\"https://images.unsplash.com/photo-1591475247035-5b01b01636b3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw3fHxsYW5kfGVufDB8MXx8fDE3NTEyMTY1Njh8MA&ixlib=rb-4.1.0&q=80&w=1080\" alt=\"#\"/>\n        <img className=\"w-52 h-52 object-cover rounded-full outline outline-2 outline-slate-200 shadow-xl dark300 dark500\" src=\"https://images.unsplash.com/photo-1591475247035-5b01b01636b3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw3fHxsYW5kfGVufDB8MXx8fDE3NTEyMTY1Njh8MA&ixlib=rb-4.1.0&q=80&w=1080\" alt=\"#\"/>\n        <img className=\"w-52 h-52 object-cover rounded-full outline outline-2 outline-slate-200 shadow-xl dark300 dark500\" src=\"https://images.unsplash.com/photo-1591475247035-5b01b01636b3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw3fHxsYW5kfGVufDB8MXx8fDE3NTEyMTY1Njh8MA&ixlib=rb-4.1.0&q=80&w=1080\" alt=\"#\"/>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
