    "rawHtml": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Bento Grid Section</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style>\n        body { font-family: 'Inter', sans-serif; }\n    </style>\n</head>\n<body class=\"bg-[#2B2926] flex items-center justify-center min-h-screen p-6\">\n\n    <section class=\"max-w-6xl mx-auto w-full\">\n        \n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-6\">\n\n            <div class=\"flex flex-col gap-6\">\n                <div class=\"bg-gradient-to-br from-[#D8C6F6] to-[#C4A9F3] p-8 rounded-3xl h-64 flex flex-col justify-between transition-transform hover:scale-[1.02] duration-300\">\n                    <div class=\"bg-white w-10 h-10 rounded-lg flex items-center justify-center shadow-sm\">\n                        <svg class=\"w-6 h-6 text-gray-800\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 10V3L4 14h7v7l9-11h-7z\"></path></svg>\n                    </div>\n                    <div>\n                        <h3 class=\"text-xl font-bold text-gray-900 mb-2\">Our Mission</h3>\n                        <p class=\"text-sm text-gray-700 leading-relaxed\">\n                            To make financial management simple, transparent, and accessible for everyone.\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"relative h-80 rounded-3xl overflow-hidden group\">\n                    <img src=\"https://images.unsplash.com/photo-1531538606174-0f90ff5dce83?q=80&w=800&auto=format&fit=crop\" \n                         alt=\"Working on laptop\" \n                         class=\"w-full h-full object-cover transition-transform duration-500 group-hover:scale-110\">\n                </div>\n            </div>\n\n            <div class=\"flex flex-col gap-6\">\n                <div class=\"relative h-96 rounded-3xl overflow-hidden group\">\n                    <img src=\"https://media.istockphoto.com/id/1597475039/photo/abstract-colorful-glass-background.jpg?s=612x612&w=0&k=20&c=Gv5iCYYzRnE7F_RwFDacJGmEgLfArYnkeyORu1umeZM=\" \n                         alt=\"Counting money\" \n                         class=\"w-full h-full object-cover transition-transform duration-500 group-hover:scale-110\">\n                </div>\n\n                <div class=\"bg-gradient-to-br from-[#FFD685] to-[#FFC247] p-8 rounded-3xl flex-1 flex flex-col justify-between transition-transform hover:scale-[1.02] duration-300\">\n                    <h3 class=\"text-xl font-bold text-gray-900 max-w-[150px]\">Trusted by 25,000+ happy customers</h3>\n                    \n                    <div class=\"flex items-center mt-4\">\n                        <img class=\"w-10 h-10 rounded-full border-2 border-white object-cover\" src=\"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=64&h=64\" alt=\"\">\n                        <img class=\"w-10 h-10 rounded-full border-2 border-white -ml-3 object-cover\" src=\"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=64&h=64\" alt=\"\">\n                        <img class=\"w-10 h-10 rounded-full border-2 border-white -ml-3 object-cover\" src=\"https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=64&h=64\" alt=\"\">\n                        <div class=\"w-10 h-10 rounded-full border-2 border-white -ml-3 bg-white/50 flex items-center justify-center text-xs font-bold text-gray-800\">\n                            +\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"flex flex-col gap-6\">\n                <div class=\"bg-gradient-to-br from-[#FCA5A5] to-[#F87171] p-8 rounded-3xl h-64 flex flex-col justify-between transition-transform hover:scale-[1.02] duration-300\">\n                    <div class=\"bg-white w-10 h-10 rounded-lg flex items-center justify-center shadow-sm\">\n                         <svg class=\"w-6 h-6 text-gray-800\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z\"></path></svg>\n                    </div>\n                    <div>\n                        <h3 class=\"text-xl font-bold text-gray-900 mb-2\">Our Vision</h3>\n                        <p class=\"text-sm text-gray-800 leading-relaxed\">\n                            A world where businesses spend less time worrying about numbers and more time growing.\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"relative h-80 rounded-3xl overflow-hidden group\">\n                    <img src=\"https://images.unsplash.com/photo-1542744173-8e7e53415bb0?q=80&w=800&auto=format&fit=crop\" \n                         alt=\"Discussion\" \n                         class=\"w-full h-full object-cover transition-transform duration-500 group-hover:scale-110\">\n                </div>\n            </div>\n\n        </div>\n    </section>\n\n</body>\n</html>"
