"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                            <rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\" ry=\"5\"></rect>\n                            <path d=\"M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z\"></path>\n                            <line x1=\"17.5\" y1=\"6.5\" x2=\"17.51\" y2=\"6.5\"></line>\n                        </svg>\n                </a>\n                <a href=\"#\" class=\"social-link text-2xl hover:text-indigo-600\">\n                    \n                        <svg viewBox=\"0 0 24 24\" fill=\"currentColor\">\n                            <path d=\"M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z\"/>\n                        </svg>\n                </a>\n                <a href=\"#\" class=\"social-link text-2xl hover:text-indigo-600\">\n                    \n                        <svg viewBox=\"0 0 24 24\" fill=\"currentColor\">\n                            <path d=\"M12.186 24h-.007c-3.581-.024-6.334-1.205-8.184-3.509C2.35 18.44 1.5 15.586 1.5 12.068V12c.007-3.513.858-6.359 2.53-8.462C5.866 1.482 8.592.287 12.107.254h.028c2.529.019 4.725.718 6.532 2.078 1.746 1.314 3.017 3.22 3.78 5.67l-1.919.547c-.639-2.058-1.69-3.636-3.126-4.693-1.455-1.07-3.238-1.618-5.301-1.63-2.886.027-5.098.987-6.575 2.854-1.418 1.79-2.137 4.262-2.137 7.348v.042c0 2.993.697 5.39 2.073 7.127 1.395 1.761 3.57 2.691 6.468 2.768 2.186-.058 3.98-.593 5.339-1.593 1.304-.96 1.944-2.18 1.944-3.628 0-1.167-.396-2.07-1.176-2.683-.729-.572-1.739-.867-3.003-.878-1.003.005-1.79.239-2.34.696-.525.437-.8 1.028-.8 1.756 0 .567.178 1.014.53 1.328.339.303.817.463 1.42.477l-.056 1.972c-1.088-.031-1.993-.392-2.691-1.073-.72-.702-1.1-1.635-1.1-2.704 0-1.292.52-2.36 1.505-3.089.937-.692 2.171-1.05 3.671-1.062 1.72.017 3.117.434 4.151 1.24 1.088.849 1.64 2.112 1.64 3.754 0 2.003-.896 3.677-2.664 4.98-1.673 1.234-3.869 1.885-6.532 1.94z\"/>\n                            <path d=\"M12.517 17.633c-2.009-.035-3.537-.695-4.545-1.962-.974-1.224-1.468-2.976-1.468-5.209 0-2.27.516-4.044 1.533-5.274 1.044-1.263 2.59-1.904 4.593-1.904 1.523 0 2.775.418 3.722 1.244.91.793 1.518 1.898 1.807 3.285l-1.924.47c-.208-.994-.604-1.78-1.177-2.337-.586-.57-1.387-.859-2.38-.859-1.435 0-2.457.457-3.037 1.358-.602.936-.907 2.357-.907 4.225 0 1.824.29 3.212.861 4.127.553.885 1.504 1.334 2.829 1.334.867 0 1.577-.22 2.11-.654.518-.423.827-.99.918-1.687l1.962.284c-.166 1.188-.687 2.142-1.546 2.838-.873.706-2.008 1.078-3.374 1.121z\"/>\n                        </svg>\n                </a>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        function toggleTheme() {\n            const html = document.documentElement;\n            const icon = document.getElementById('theme-icon');\n            \n            if (html.getAttribute('data-theme') === 'light') {\n                html.setAttribute('data-theme', 'dark');\n                icon.classList.remove('bi-moon-fill');\n                icon.classList.add('bi-sun-fill');\n            } else {\n                html.setAttribute('data-theme', 'light');\n                icon.classList.remove('bi-sun-fill');\n                icon.classList.add('bi-moon-fill');\n            }\n        }\n\n        function toggleFollow(btn) {\n            if (btn.textContent.includes('Follow')) {\n                btn.innerHTML = 'Following <i class=\"bi bi-check\"></i>';\n                btn.style.backgroundColor = '#6366f1';\n                btn.style.color = 'white';\n            } else {\n                btn.innerHTML = 'Follow <i class=\"bi bi-plus\"></i>';\n                btn.style.backgroundColor = '';\n                btn.style.color = '';\n            }\n        }\n    </script>\n</body>\n</html>"
