    "code": "/**\n * Component: Hero section with search\n * Author: @team-tailwindflex (https://tailwindflex.com/@team-tailwindflex)\n * Source: https://tailwindflex.com/@team-tailwindflex/hero-header-with-search-button\n * Attribution: Créé par @team-tailwindflex sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroHeaderWithSearchButton() {\n  return (\n    <div>\n    <div className=\"dark800\">\n        <div className=\"dark\">\n            <div className=\"mx-auto flex flex-col items-center py-12 sm24\">\n                <div className=\"w-11/12 sm2/3 lg justify-center items-center flex-col mb-5 sm10\">\n                    <h1\n                        className=\"text-4xl sm5xl md5xl lg5xl xl6xl text-center text-gray-800 dark font-black leading-10\">\n                        Let's not stress for\n                        <span className=\"text-violet-800 dark500\">Website</span>\n                        designs.\n                    </h1>\n                    <p className=\"mt-5 sm10 lg10/12 text-gray-600 dark300 font-normal text-center text-xl\">\n                        A Community build tailwind component library.\n                    </p>\n                </div>\n                <div className=\"flex w-11/12 md8/12 xl6/12\">\n                    <div className=\"flex rounded-md w-full\">\n                        <input type=\"text\" name=\"q\"\n                            className=\"w-full p-3 rounded-md rounded-r-none border border-2 border-gray-300 placeholder-current dark500  dark300 dark \"\n                            placeholder=\"keyword\" />\n                        <button\n                            className=\"inline-flex items-center gap-2 bg-violet-700 text-white text-lg font-semibold py-3 px-6 rounded-r-md\">\n                            <span>Find</span>\n                            <svg className=\"text-gray-200 h-5 w-5 p-0 fill-current\" xmlns=\"http://www.w3.org/2000/svg\"\n                                xmlns version=\"1.1\" x=\"0px\" y=\"0px\"\n                                viewBox=\"0 0 56.966 56.966\" style=\"enable-background 0 0 56.966 56.966;\"\n                                xml>\n                                <path\n                                    d=\"M55.146,51.887L41.588,37.786c3.486-4.144,5.396-9.358,5.396-14.786c0-12.682-10.318-23-23-23s-23,10.318-23,23  s10.318,23,23,23c4.761,0,9.298-1.436,13.177-4.162l13.661,14.208c0.571,0.593,1.339,0.92,2.162,0.92  c0.779,0,1.518-0.297,2.079-0.837C56.255,54.982,56.293,53.08,55.146,51.887z M23.984,6c9.374,0,17,7.626,17,17s-7.626,17-17,17  s-17-7.626-17-17S14.61,6,23.984,6z\" />\n                            </svg>\n                    </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"dark:bg-gray-800\">\n    <div class=\"dark:bg-transparent\">\n        <div class=\"mx-auto flex flex-col items-center py-12 sm:py-24\">\n            <div class=\"w-11/12 sm:w-2/3 lg:flex justify-center items-center flex-col mb-5 sm:mb-10\">\n                <h1\n                    class=\"text-4xl sm:text-5xl md:text-5xl lg:text-5xl xl:text-6xl text-center text-gray-800 dark:text-white font-black leading-10\">\n                    Let's not stress for\n                    <span class=\"text-violet-800 dark:text-violet-500\">Website</span>\n                    designs.\n                </h1>\n                <p class=\"mt-5 sm:mt-10 lg:w-10/12 text-gray-600 dark:text-gray-300 font-normal text-center text-xl\">\n                    A Community build tailwind component library.\n                </p>\n            </div>\n            <div class=\"flex w-11/12 md:w-8/12 xl:w-6/12\">\n                <div class=\"flex rounded-md w-full\">\n                    <input type=\"text\" name=\"q\"\n                        class=\"w-full p-3 rounded-md rounded-r-none border border-2 border-gray-300 placeholder-current dark:bg-gray-500  dark:text-gray-300 dark:border-none \"\n                        placeholder=\"keyword\" />\n                    <button\n                        class=\"inline-flex items-center gap-2 bg-violet-700 text-white text-lg font-semibold py-3 px-6 rounded-r-md\">\n                        <span>Find</span>\n                        <svg class=\"text-gray-200 h-5 w-5 p-0 fill-current\" xmlns=\"http://www.w3.org/2000/svg\"\n                            xmlns:xlink=\"http://www.w3.org/1999/xlink\" version=\"1.1\" x=\"0px\" y=\"0px\"\n                            viewBox=\"0 0 56.966 56.966\" style=\"enable-background:new 0 0 56.966 56.966;\"\n                            xml:space=\"preserve\">\n                            <path\n                                d=\"M55.146,51.887L41.588,37.786c3.486-4.144,5.396-9.358,5.396-14.786c0-12.682-10.318-23-23-23s-23,10.318-23,23  s10.318,23,23,23c4.761,0,9.298-1.436,13.177-4.162l13.661,14.208c0.571,0.593,1.339,0.92,2.162,0.92  c0.779,0,1.518-0.297,2.079-0.837C56.255,54.982,56.293,53.08,55.146,51.887z M23.984,6c9.374,0,17,7.626,17,17s-7.626,17-17,17  s-17-7.626-17-17S14.61,6,23.984,6z\" />\n                        </svg>\n                </button>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>"
