    "code": "/**\n * Component: Typical SAAS hero section\n * Author: @eamon-carter (https://tailwindflex.com/@eamon-carter)\n * Source: https://tailwindflex.com/@eamon-carter/typical-saas-hero-section\n * Attribution: Créé par @eamon-carter sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function TypicalSaasHeroSection() {\n  return (\n    <div>\n    <div className=\"py-12 sm24\">\n        <div className=\"mx-auto max-w-7xl px-6 lg8\">\n            <div className=\"mb-8 flex justify-center\">\n                <p\n                    className=\"relative rounded-full px-4 py-1.5 text-sm leading-6 text-gray-600 ring-1 ring-inset ring-gray-900/10 hover900/20\">\n                    <span className=\"hidden md\">Cachet is back.</span>\n                    <a href=\"#\" target=\"_blank\" className=\"font-semibold text-lime-600\">\n                        <span className=\"absolute inset-0\" ></span> Read\n                        the update <span>→</span>\n                    </a>\n                </p>\n            </div>\n            <div className=\"mx-auto max-w-2xl text-center\">\n                <h1 className=\"text-4xl font-bold tracking-tight text-gray-900 sm6xl\">\n                    SecureCloud Backup Solution\n                </h1>\n                <p className=\"mt-6 text-lg leading-8 text-gray-600\">\n                    Introducing our cutting-edge SecureCloud Backup Solution, the ultimate safeguard for your critical data.\n                    In today's rapidly evolving IT landscape, data security and disaster recovery have never been more\n                    crucial.\n                </p>\n                <div className=\"mt-10 flex items-center justify-center gap-x-6\">\n                    <a href=\"#\"\n                        className=\"rounded-md bg-lime-500 px-3.5 py-2.5 text-sm font-semibold text-white shadow-sm hover500 focus-visible focus-visible2 focus-visible2 focus-visible600\">Check\n                        out the demo\n                    </a>\n                    <a href=\"#\" className=\"text-sm font-semibold leading-6 text-gray-900\">\n                        Learn more\n                        <span>→</span>\n                    </a>\n                </div>\n            </div>\n            <div className=\"mt-10 flow-root sm20\">\n                <div\n                    className=\"-m-2 rounded-xl bg-gray-900/5 p-2 ring-1 ring-inset ring-gray-900/10 lg4 lg2xl lg4\">\n                    \n                    <img src=\"https://images.unsplash.com/photo-1558494949-ef010cbdcc31?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw1fHxiYWNrdXB8ZW58MHwwfHx8MTY5MjAwMjg2M3ww&ixlib=rb-4.0.3&q=80&w=1080\" width=\"2432\" height=\"1442\" className=\"rounded-md shadow-2xl ring-1 ring-gray-900/10\" />\n                </div>\n            </div>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"py-12 sm:py-24\">\n    <div class=\"mx-auto max-w-7xl px-6 lg:px-8\">\n        <div class=\"mb-8 flex justify-center\">\n            <p\n                class=\"relative rounded-full px-4 py-1.5 text-sm leading-6 text-gray-600 ring-1 ring-inset ring-gray-900/10 hover:ring-gray-900/20\">\n                <span class=\"hidden md:inline\">Cachet is back.</span>\n                <a href=\"#\" target=\"_blank\" class=\"font-semibold text-lime-600\">\n                    <span class=\"absolute inset-0\" ></span> Read\n                    the update <span>→</span>\n                </a>\n            </p>\n        </div>\n        <div class=\"mx-auto max-w-2xl text-center\">\n            <h1 class=\"text-4xl font-bold tracking-tight text-gray-900 sm:text-6xl\">\n                SecureCloud Backup Solution\n            </h1>\n            <p class=\"mt-6 text-lg leading-8 text-gray-600\">\n                Introducing our cutting-edge SecureCloud Backup Solution, the ultimate safeguard for your critical data.\n                In today's rapidly evolving IT landscape, data security and disaster recovery have never been more\n                crucial.\n            </p>\n            <div class=\"mt-10 flex items-center justify-center gap-x-6\">\n                <a href=\"#\"\n                    class=\"rounded-md bg-lime-500 px-3.5 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-lime-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-lime-600\">Check\n                    out the demo\n                </a>\n                <a href=\"#\" class=\"text-sm font-semibold leading-6 text-gray-900\">\n                    Learn more\n                    <span>→</span>\n                </a>\n            </div>\n        </div>\n        <div class=\"mt-10 flow-root sm:mt-20\">\n            <div\n                class=\"-m-2 rounded-xl bg-gray-900/5 p-2 ring-1 ring-inset ring-gray-900/10 lg:-m-4 lg:rounded-2xl lg:p-4\">\n                <!-- Photo by '@tvick' on Unsplash -->\n                <img src=\"https://images.unsplash.com/photo-1558494949-ef010cbdcc31?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw1fHxiYWNrdXB8ZW58MHwwfHx8MTY5MjAwMjg2M3ww&ixlib=rb-4.0.3&q=80&w=1080\" width=\"2432\" height=\"1442\" class=\"rounded-md shadow-2xl ring-1 ring-gray-900/10\">\n            </div>\n        </div>\n    </div>\n</div>"
