    "dependencies": [],
    "code": "/**\n * Component: Hero section with Big Heading\n * Author: @mereani (https://tailwindflex.com/@mereani)\n * Source: https://tailwindflex.com/@mereani/hero-section-with-big-heading\n * Attribution: Créé par @mereani sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroSectionWithBigHeading() {\n  return (\n    <div>\n    <div\n      className=\"flex flex-1 w-full flex-col items-center justify-center text-center px-4 py-20 bg-gradient-to-r from-green-50/50 via-teal-50 to-green-50/50 dark800 dark700 dark800\">\n      <a href=\"\"\n        className=\"border border-white-700 dark300 rounded-lg py-2 px-4 text-white-400 dark300 text-sm mb-5 transition duration-300 ease-in-out hover500 dark400\">\n        Forget about spending hundreds $\n      </a>\n      <h1\n        className=\"mx-auto max-w-4xl font-display text-5xl font-bold tracking-normal text-white-300 dark300 sm7xl\">\n        Revolutionize Your Insurance\n        <span className=\"relative whitespace-nowrap text-white-600 dark300\">Operations</span>\n        <span className=\"relative whitespace-nowrap text-orange-500 dark300\">\n          <svg aria-hidden=\"true\" viewBox=\"0 0 418 42\" className=\"absolute top-2/3 left-0 h-[0.58em] w-full fill-orange-500 dark300/60\" preserveAspectRatio=\"none\">\n            <path d=\"M203.371.916c-26.013-2.078-76.686 1.963-124.73 9.946L67.3 12.749C35.421 18.062 18.2 21.766 6.004 25.934 1.244 27.561.828 27.778.874 28.61c.07 1.214.828 1.121 9.595-1.176 9.072-2.377 17.15-3.92 39.246-7.496C123.565 7.986 157.869 4.492 195.942 5.046c7.461.108 19.25 1.696 19.17 2.582-.107 1.183-7.874 4.31-25.75 10.366-21.992 7.45-35.43 12.534-36.701 13.884-2.173 2.308-.202 4.407 4.442 4.734 2.654.187 3.263.157 15.593-.780 35.401-2.686 57.944-3.488 88.365-3.143 46.327.526 75.721 2.23 130.788 7.584 19.787 1.924 20.814 1.98 24.557 1.332l.066-.011c1.201-.203 1.53-1.825.399-2.335-2.911-1.31-4.893-1.604-22.048-3.261-57.509-5.556-87.871-7.36-132.059-7.842-23.239-.254-33.617-.116-50.627.674-11.629.540-42.371 2.494-46.696 2.967-2.359.259 8.133-3.625 26.504-9.810 23.239-7.825 27.934-10.149 28.304-14.005 .417-4.348-3.529-6-16.878-7.066Z\"></path>\n          </svg>\n          <span className=\"relative\">with AI</span>\n        </span>\n      </h1>\n      <h2 className=\"mx-auto mt-12 max-w-xl text-lg sm400 text-white-500 dark300 leading-7\">\n        Experience the future of insurance with our cutting-edge AI tool. From underwriting to claims processing, our\n        intelligent system streamlines and enhances every aspect of your insurance operations.\n      </h2>\n      <a className=\"bg-orange-600 dark800 rounded-xl text-white dark300 font-medium px-4 py-3 sm10 mt-8 hover500 dark600 transition\"\n        href=\"\">Get started</a>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div\n  class=\"flex flex-1 w-full flex-col items-center justify-center text-center px-4 py-20 bg-gradient-to-r from-green-50/50 via-teal-50 to-green-50/50 dark:from-gray-800 dark:via-gray-700 dark:to-gray-800\">\n  <a href=\"\"\n    class=\"border border-white-700 dark:border-gray-300 rounded-lg py-2 px-4 text-white-400 dark:text-gray-300 text-sm mb-5 transition duration-300 ease-in-out hover:text-gray-500 dark:hover:text-gray-400\">\n    Forget about spending hundreds $\n  </a>\n  <h1\n    class=\"mx-auto max-w-4xl font-display text-5xl font-bold tracking-normal text-white-300 dark:text-gray-300 sm:text-7xl\">\n    Revolutionize Your Insurance\n    <span class=\"relative whitespace-nowrap text-white-600 dark:text-gray-300\">Operations</span>\n    <span class=\"relative whitespace-nowrap text-orange-500 dark:text-orange-300\">\n      <svg aria-hidden=\"true\" viewBox=\"0 0 418 42\" class=\"absolute top-2/3 left-0 h-[0.58em] w-full fill-orange-500 dark:fill-orange-300/60\" preserveAspectRatio=\"none\">\n        <path d=\"M203.371.916c-26.013-2.078-76.686 1.963-124.73 9.946L67.3 12.749C35.421 18.062 18.2 21.766 6.004 25.934 1.244 27.561.828 27.778.874 28.61c.07 1.214.828 1.121 9.595-1.176 9.072-2.377 17.15-3.92 39.246-7.496C123.565 7.986 157.869 4.492 195.942 5.046c7.461.108 19.25 1.696 19.17 2.582-.107 1.183-7.874 4.31-25.75 10.366-21.992 7.45-35.43 12.534-36.701 13.884-2.173 2.308-.202 4.407 4.442 4.734 2.654.187 3.263.157 15.593-.780 35.401-2.686 57.944-3.488 88.365-3.143 46.327.526 75.721 2.23 130.788 7.584 19.787 1.924 20.814 1.98 24.557 1.332l.066-.011c1.201-.203 1.53-1.825.399-2.335-2.911-1.31-4.893-1.604-22.048-3.261-57.509-5.556-87.871-7.36-132.059-7.842-23.239-.254-33.617-.116-50.627.674-11.629.540-42.371 2.494-46.696 2.967-2.359.259 8.133-3.625 26.504-9.810 23.239-7.825 27.934-10.149 28.304-14.005 .417-4.348-3.529-6-16.878-7.066Z\"></path>\n      </svg>\n      <span class=\"relative\">with AI</span>\n    </span>\n  </h1>\n  <h2 class=\"mx-auto mt-12 max-w-xl text-lg sm:text-white-400 text-white-500 dark:text-gray-300 leading-7\">\n    Experience the future of insurance with our cutting-edge AI tool. From underwriting to claims processing, our\n    intelligent system streamlines and enhances every aspect of your insurance operations.\n  </h2>\n  <a class=\"bg-orange-600 dark:bg-gray-800 rounded-xl text-white dark:text-gray-300 font-medium px-4 py-3 sm:mt-10 mt-8 hover:bg-orange-500 dark:hover:bg-gray-600 transition\"\n    href=\"\">Get started</a>\n</div>"
