    "code": "/**\n * Component: Hero section with call to action buttons\n * Author: @prashant (https://tailwindflex.com/@prashant)\n * Source: https://tailwindflex.com/@prashant/hero-section-with-call-to-action-buttons\n * Attribution: Créé par @prashant sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroSectionWithCallToActionButtons() {\n  return (\n    <div>\n    <section className=\"sm6 lg8 mt-12 max-w-7xl mx-auto px-4 sm6 lg8\">\n    \n        <div\n            className=\"my-10 mx-auto max-w-7xl px-4 sm12 sm6 md16 lg20 lg8 xl28 flex gap-3 lg lg flex-col lg\">\n            <div className=\"sm lg\">\n                <h1 className=\"text-4xl tracking-tight font-extrabold text-gray-800 sm5xl md6xl\">\n                    <span className=\"block xl\">Data to enrich your</span>\n                    <span className=\"block text-indigo-600 xl\">online business</span>\n                </h1>\n                <p\n                    className=\"mt-3 text-base text-gray-500 sm5 sm sm sm md5 md lg0\">\n                    Anim aute id magna aliqua ad ad non deserunt sunt. Qui irure qui lorem cupidatat commodo. Elit sunt amet\n                    fugiat veniam occaecat fugiat aliqua.\n                </p>\n                \n                <div className=\"mt-5 sm8 sm sm lg\">\n                    <div className=\"rounded-md shadow\">\n                        <a href=\"#\"\n                            className=\"w-full flex items-center justify-center px-8 py-3 border border-transparent text-base font-medium rounded-md text-white bg-gray-800 hover600 md4 md md10\">\n                            Get started\n                        </a>\n                    </div>\n                    <div className=\"mt-3 sm0 sm3\">\n                        <a href=\"#\"\n                            className=\"w-full flex items-center justify-center px-8 py-3 border border-transparent text-base font-medium rounded-md text-gray-800 bg-indigo-100 hover200 md4 md md10\">\n                            Live demo\n                        </a>\n                    </div>\n                </div>\n                \n            </div>\n    \n            \n            <div className=\"lg0 lg0 lg1/2 my-4\">\n                <img className=\"h-56 w-full object-cover sm72 md96 lg lg\" src=\"https://images.unsplash.com/photo-1551434678-e076c223a692?ixlib=rb-1.2.1&ixid=eyJhcHBfaWQiOjEyMDd9&auto=format&fit=crop&w=2850&q=80\" alt=\"\" />\n            </div>\n            \n        </div>\n    \n    </section>\n    </div>\n  );\n}\n",
    "rawHtml": "<section class=\"sm:mt-6 lg:mt-8 mt-12 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n\n    <div\n        class=\"my-10 mx-auto max-w-7xl px-4 sm:mt-12 sm:px-6 md:mt-16 lg:mt-20 lg:px-8 xl:mt-28 flex gap-3 lg:flex-justify lg:flex flex-col lg:flex-row\">\n        <div class=\"sm:text-center lg:text-left\">\n            <h1 class=\"text-4xl tracking-tight font-extrabold text-gray-800 sm:text-5xl md:text-6xl\">\n                <span class=\"block xl:inline\">Data to enrich your</span>\n                <span class=\"block text-indigo-600 xl:inline\">online business</span>\n            </h1>\n            <p\n                class=\"mt-3 text-base text-gray-500 sm:mt-5 sm:text-lg sm:max-w-xl sm:mx-auto md:mt-5 md:text-xl lg:mx-0\">\n                Anim aute id magna aliqua ad ad non deserunt sunt. Qui irure qui lorem cupidatat commodo. Elit sunt amet\n                fugiat veniam occaecat fugiat aliqua.\n            </p>\n            <!-- Button Section -->\n            <div class=\"mt-5 sm:mt-8 sm:flex sm:justify-center lg:justify-start\">\n                <div class=\"rounded-md shadow\">\n                    <a href=\"#\"\n                        class=\"w-full flex items-center justify-center px-8 py-3 border border-transparent text-base font-medium rounded-md text-white bg-gray-800 hover:bg-gray-600 md:py-4 md:text-lg md:px-10\">\n                        Get started\n                    </a>\n                </div>\n                <div class=\"mt-3 sm:mt-0 sm:ml-3\">\n                    <a href=\"#\"\n                        class=\"w-full flex items-center justify-center px-8 py-3 border border-transparent text-base font-medium rounded-md text-gray-800 bg-indigo-100 hover:bg-indigo-200 md:py-4 md:text-lg md:px-10\">\n                        Live demo\n                    </a>\n                </div>\n            </div>\n            <!-- End of Button Section -->\n        </div>\n\n        <!--   Image Section     -->\n        <div class=\"lg:inset-y-0 lg:right-0 lg:w-1/2 my-4\">\n            <img class=\"h-56 w-full object-cover sm:h-72 md:h-96 lg:w-full lg:h-full\" src=\"https://images.unsplash.com/photo-1551434678-e076c223a692?ixlib=rb-1.2.1&ixid=eyJhcHBfaWQiOjEyMDd9&auto=format&fit=crop&w=2850&q=80\" alt=\"\">\n        </div>\n        <!--   End of Image Section     -->\n    </div>\n\n</section>"
