    "code": "/**\n * Component: Hero section with background gradient\n * Author: @freja-jensen (https://tailwindflex.com/@freja-jensen)\n * Source: https://tailwindflex.com/@freja-jensen/hero-section-with-background-gradient\n * Attribution: Créé par @freja-jensen sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroSectionWithBackgroundGradient() {\n  return (\n    <div>\n    <section className=\"bg-gradient-to-br from-purple-500 to-pink-500 py-16 md32\">\n        <div className=\"container mx-auto px-4 md8 text-center\">\n            <h1 className=\"text-white font-bold text-4xl md6xl leading-tight mb-6\">Welcome to our <br />Colorful World</h1>\n            <p className=\"text-white text-lg md2xl mb-12\">Experience the magic of colors with our unique products and\n                services.</p>\n            <a href=\"#\"\n                className=\"bg-white text-purple-500 font-bold py-2 px-8 rounded-full hover500 hover transition duration-200\">Shop\n                Now</a>\n        </div>\n    </section>\n    </div>\n  );\n}\n",
