    "mention": "Créé par @dipti sur TailwindFlex",
    "registryDependencies": [],
    "dependencies": [],
    "code": "/**\n * Component: Hero section with sample code\n * Author: @dipti (https://tailwindflex.com/@dipti)\n * Source: https://tailwindflex.com/@dipti/hero-section-with-sample-code\n * Attribution: Créé par @dipti sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroSectionWithSampleCode() {\n  return (\n    <div>\n    <div className=\"max-w-screen-xl px-4 mx-auto mt-8 sm12 sm6 md16\">\n      <div className=\"lg lg12 lg8\">\n        <div className=\"sm md2xl md lg6 lg\">\n          <div className=\"text-sm font-semibold tracking-wide text-gray-500 uppercase sm lg xl\">\n            New version 3\n          </div>\n          <h2\n            className=\"mt-1 text-4xl font-extrabold leading-10 tracking-tight text-gray-900 sm sm6xl lg5xl xl6xl\">\n            DataGuard Pro\n          </h2>\n          <p className=\"mt-3 text-base text-gray-600 sm5 sm lg xl\">\n            DataGuard Pro is a cutting-edge data protection and security software solution designed to safeguard your\n            sensitive information and keep your digital assets secure.\n          </p>\n          <div className=\"mt-5 sm8 sm sm lg\">\n            <div className=\"rounded-md shadow\">\n              <a href=\"/docs\"\n                className=\"flex items-center justify-center w-full px-8 py-3 text-base font-medium leading-6 text-white transition duration-150 ease-in-out bg-indigo-600 border border-transparent rounded-md hover500 focus focus md4 md md10\">\n                Documentation\n              </a>\n            </div>\n            <div className=\"mt-3 sm0 sm3\">\n              <a href=\"\"\n                className=\"flex items-center justify-center w-full px-8 py-3 text-base font-medium leading-6 text-indigo-700 transition duration-150 ease-in-out bg-indigo-100 border border-transparent rounded-md hover600 hover50 focus focus focus300 md4 md md10\">\n                Tutorial\n              </a>\n            </div>\n          </div>\n        </div>\n        <div\n          className=\"relative mt-12 sm sm lg0 lg lg0 lg6 lg lg\">\n          <svg\n            className=\"absolute top-0 hidden origin-top transform scale-75 -translate-x-1/2 -translate-y-8 left-1/2 sm100 lg\"\n            width=\"640\" height=\"784\" fill=\"none\" viewBox=\"0 0 640 784\">\n            <defs>\n              <pattern id=\"4f4f415c-a0e9-44c2-9601-6ded5a34a13e\" x=\"118\" y=\"0\" width=\"20\" height=\"20\"\n                patternUnits=\"userSpaceOnUse\">\n                <rect x=\"0\" y=\"0\" width=\"4\" height=\"4\" className=\"text-gray-200\" fill=\"currentColor\"></rect>\n              </pattern>\n            </defs>\n            <rect y=\"72\" width=\"640\" height=\"640\" className=\"text-gray-50\" fill=\"currentColor\"></rect>\n            <rect x=\"118\" width=\"404\" height=\"784\" fill=\"url(#4f4f415c-a0e9-44c2-9601-6ded5a34a13e)\"></rect>\n          </svg>\n          <div className=\"relative justify-end hidden w-full lg\">\n            <div\n              className=\"flex justify-end inline-block p-8 pr-8 text-base leading-relaxed text-blue-400 bg-indigo-900 rounded-lg shadow-lg xl xl16\">\n              <pre><span className=\"text-blue-100\">// Create a tenant</span>\n    $tenant = Tenant::create();\n    $tenant-&gt;createDomain([\n      'domain' =&gt; 'acme.com',\n    ]);\n    \n    <span className=\"text-blue-100\">// Write your app like you're used to</span>\n    Order::where('status', 'shipped')-&gt;get();\n    Cache::get('order_count');\n    asset('logo.png');\n    dispatch(new SendOrderCreatedMail);</pre>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"max-w-screen-xl px-4 mx-auto mt-8 sm:mt-12 sm:px-6 md:mt-16\">\n  <div class=\"lg:grid lg:grid-cols-12 lg:gap-8\">\n    <div class=\"sm:text-center md:max-w-2xl md:mx-auto lg:col-span-6 lg:text-left\">\n      <div class=\"text-sm font-semibold tracking-wide text-gray-500 uppercase sm:text-base lg:text-sm xl:text-base\">\n        New version 3\n      </div>\n      <h2\n        class=\"mt-1 text-4xl font-extrabold leading-10 tracking-tight text-gray-900 sm:leading-none sm:text-6xl lg:text-5xl xl:text-6xl\">\n        DataGuard Pro\n      </h2>\n      <p class=\"mt-3 text-base text-gray-600 sm:mt-5 sm:text-xl lg:text-lg xl:text-xl\">\n        DataGuard Pro is a cutting-edge data protection and security software solution designed to safeguard your\n        sensitive information and keep your digital assets secure.\n      </p>\n      <div class=\"mt-5 sm:mt-8 sm:flex sm:justify-center lg:justify-start\">\n        <div class=\"rounded-md shadow\">\n          <a href=\"/docs\"\n            class=\"flex items-center justify-center w-full px-8 py-3 text-base font-medium leading-6 text-white transition duration-150 ease-in-out bg-indigo-600 border border-transparent rounded-md hover:bg-indigo-500 focus:outline-none focus:shadow-outline md:py-4 md:text-lg md:px-10\">\n            Documentation\n          </a>\n        </div>\n        <div class=\"mt-3 sm:mt-0 sm:ml-3\">\n          <a href=\"\"\n            class=\"flex items-center justify-center w-full px-8 py-3 text-base font-medium leading-6 text-indigo-700 transition duration-150 ease-in-out bg-indigo-100 border border-transparent rounded-md hover:text-indigo-600 hover:bg-indigo-50 focus:outline-none focus:shadow-outline focus:border-indigo-300 md:py-4 md:text-lg md:px-10\">\n            Tutorial\n          </a>\n        </div>\n      </div>\n    </div>\n    <div\n      class=\"relative mt-12 sm:max-w-lg sm:mx-auto lg:mt-0 lg:max-w-none lg:mx-0 lg:col-span-6 lg:flex lg:items-center\">\n      <svg\n        class=\"absolute top-0 hidden origin-top transform scale-75 -translate-x-1/2 -translate-y-8 left-1/2 sm:scale-100 lg:hidden\"\n        width=\"640\" height=\"784\" fill=\"none\" viewBox=\"0 0 640 784\">\n        <defs>\n          <pattern id=\"4f4f415c-a0e9-44c2-9601-6ded5a34a13e\" x=\"118\" y=\"0\" width=\"20\" height=\"20\"\n            patternUnits=\"userSpaceOnUse\">\n            <rect x=\"0\" y=\"0\" width=\"4\" height=\"4\" class=\"text-gray-200\" fill=\"currentColor\"></rect>\n          </pattern>\n        </defs>\n        <rect y=\"72\" width=\"640\" height=\"640\" class=\"text-gray-50\" fill=\"currentColor\"></rect>\n        <rect x=\"118\" width=\"404\" height=\"784\" fill=\"url(#4f4f415c-a0e9-44c2-9601-6ded5a34a13e)\"></rect>\n      </svg>\n      <div class=\"relative justify-end hidden w-full lg:flex\">\n        <div\n          class=\"flex justify-end inline-block p-8 pr-8 text-base leading-relaxed text-blue-400 bg-indigo-900 rounded-lg shadow-lg xl:text-lg xl:pr-16\">\n          <pre><span class=\"text-blue-100\">// Create a tenant</span>\n$tenant = Tenant::create();\n$tenant-&gt;createDomain([\n  'domain' =&gt; 'acme.com',\n]);\n\n<span class=\"text-blue-100\">// Write your app like you're used to</span>\nOrder::where('status', 'shipped')-&gt;get();\nCache::get('order_count');\nasset('logo.png');\ndispatch(new SendOrderCreatedMail);</pre>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>"
