    "code": "/**\n * Component: Hero with description\n * Author: @laurits (https://tailwindflex.com/@laurits)\n * Source: https://tailwindflex.com/@laurits/hero-with-description\n * Attribution: Créé par @laurits sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroWithDescription() {\n  return (\n    <div>\n    <div className=\"relative px-6 lg8 dark800\">\r\n        <div className=\"mx-auto max-w-3xl pt-20 pb-32 sm48 sm40\">\r\n            <div>\r\n                <div>\r\n                    <h1 className=\"text-4xl font-bold tracking-tight sm sm6xl dark100\">\r\n                        Title of your website\r\n                    </h1>\r\n                    <p className=\"mt-6 text-lg leading-8 text-gray-600 sm dark200\">\r\n                        Long description of your website,\r\n                        Long description of your website,\r\n                        Long description of your website,\r\n                        Long description of your website,\r\n                        Long description of your website,\r\n                    </p>\r\n                    <div className=\"mt-8 flex gap-x-4 sm\">\r\n                        <a href=\"#\"\r\n                            className=\"inline-block rounded-lg bg-indigo-600 px-4 py-1.5 text-base font-semibold leading-7 text-white shadow-sm ring-1 ring-indigo-600 hover700 hover700\">\r\n                            Get started\r\n                            <span aria-hidden=\"true\" className=\"text-indigo-200\">→</span>\r\n                        </a>\r\n                        <a href=\"#\"\r\n                            className=\"inline-block rounded-lg px-4 py-1.5 text-base font-semibold leading-7 text-gray-900 dark100 ring-1 ring-gray-900/10 hover900/20\">\r\n                            Read the guide\r\n                            <span aria-hidden=\"true\" className=\"text-gray-400\">→</span>\r\n                        </a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"relative px-6 lg:px-8 dark:bg-gray-800\">\r\n    <div class=\"mx-auto max-w-3xl pt-20 pb-32 sm:pt-48 sm:pb-40\">\r\n        <div>\r\n            <div>\r\n                <h1 class=\"text-4xl font-bold tracking-tight sm:text-center sm:text-6xl dark:text-gray-100\">\r\n                    Title of your website\r\n                </h1>\r\n                <p class=\"mt-6 text-lg leading-8 text-gray-600 sm:text-center dark:text-gray-200\">\r\n                    Long description of your website,\r\n                    Long description of your website,\r\n                    Long description of your website,\r\n                    Long description of your website,\r\n                    Long description of your website,\r\n                </p>\r\n                <div class=\"mt-8 flex gap-x-4 sm:justify-center\">\r\n                    <a href=\"#\"\r\n                        class=\"inline-block rounded-lg bg-indigo-600 px-4 py-1.5 text-base font-semibold leading-7 text-white shadow-sm ring-1 ring-indigo-600 hover:bg-indigo-700 hover:ring-indigo-700\">\r\n                        Get started\r\n                        <span aria-hidden=\"true\" class=\"text-indigo-200\">→</span>\r\n                    </a>\r\n                    <a href=\"#\"\r\n                        class=\"inline-block rounded-lg px-4 py-1.5 text-base font-semibold leading-7 text-gray-900 dark:text-gray-100 ring-1 ring-gray-900/10 hover:ring-gray-900/20\">\r\n                        Read the guide\r\n                        <span aria-hidden=\"true\" class=\"text-gray-400\">→</span>\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>"
