    "code": "/**\n * Component: hero section fullpage\n * Author: @leon-bachmann (https://tailwindflex.com/@leon-bachmann)\n * Source: https://tailwindflex.com/@leon-bachmann/hero-section-fullpage\n * Attribution: Créé par @leon-bachmann sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroSectionFullpage() {\n  return (\n    <div>\n    <div className=\"h-screen flex items-center bg-green-700\">\n    \n        <div className=\"px-4 mx-auto mt-16 mb-16 max-w-7xl sm24\">\n            <div className=\"text-center\">\n                <h1 className=\"text-4xl font-extrabold tracking-tight text-gray-200 sm5xl md6xl font-title\">\n                    <span className=\"block\">Leading US-Based cycle maker</span>\n                    <span className=\"block pt-2\">New Product Launch</span>\n                </h1>\n                <p className=\"max-w-md mx-auto mt-3 text-base text-gray-300 sm md5 md md3xl\">\n                    Innovative technology to revolutionize industry standards,\n                    Available for pre-order now and shipping to customers in the coming months\n                </p>\n                <div className=\"max-w-md mx-auto mt-5 sm sm md8\">\n    \n                    <div className=\"mt-3 rounded-md shadow sm0 sm3\">\n                        <a href=\"\"\n                            className=\"block shadow-lg w-full px-8 py-3 text-base font-medium text-gray-200 hover100 bg-gray-100/10 hover200/30 hover backdrop-blur-lg rounded-md md4 md md10\">\n                            Pre-Book\n                        </a>\n                    </div>\n                </div>\n            </div>\n        </div>\n    \n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"h-screen flex items-center bg-green-700\">\n\n    <div class=\"px-4 mx-auto mt-16 mb-16 max-w-7xl sm:mt-24\">\n        <div class=\"text-center\">\n            <h1 class=\"text-4xl font-extrabold tracking-tight text-gray-200 sm:text-5xl md:text-6xl font-title\">\n                <span class=\"block\">Leading US-Based cycle maker</span>\n                <span class=\"block pt-2\">New Product Launch</span>\n            </h1>\n            <p class=\"max-w-md mx-auto mt-3 text-base text-gray-300 sm:text-lg md:mt-5 md:text-xl md:max-w-3xl\">\n                Innovative technology to revolutionize industry standards,\n                Available for pre-order now and shipping to customers in the coming months\n            </p>\n            <div class=\"max-w-md mx-auto mt-5 sm:flex sm:justify-center md:mt-8\">\n\n                <div class=\"mt-3 rounded-md shadow sm:mt-0 sm:ml-3\">\n                    <a href=\"\"\n                        class=\"block shadow-lg w-full px-8 py-3 text-base font-medium text-gray-200 hover:text-gray-100 bg-gray-100/10 hover:bg-gray-200/30 hover:backdrop-blur-xl backdrop-blur-lg rounded-md md:py-4 md:text-lg md:px-10\">\n                        Pre-Book\n                    </a>\n                </div>\n            </div>\n        </div>\n    </div>\n\n</div>"
