    "code": "/**\n * Component: Clean hero section\n * Author: @omkar007 (https://tailwindflex.com/@omkar007)\n * Source: https://tailwindflex.com/@omkar007/clean-hero-section-3\n * Attribution: Créé par @omkar007 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function CleanHeroSection3() {\n  return (\n    <div>\n    <div\n        className=\"px-7 lg10 max-w-6xl mx-auto flex flex-col gap-y-10 lg items-center gap-x-10 justify-center py-10 lg14 dark800\">\n        <div className=\"lg[650px] lg5 flex flex-col gap-y-5\">\n            <h1\n                className=\"text-4xl md5xl xl[50px] leading-[1.2] md md md lg lg0 lg font-semibold dark\">\n                Discover the power of streamlined services\n            </h1>\n            <p className=\"text-sm md md lg0 lg md lg dark300\">\n                With\n                efficient services available online, you can simplify your tasks and save valuable time.</p>\n            <div className=\"flex gap-x-5 flex-col gap-y-2.5 lg\">\n                <a href=\"#\"\n                    className=\"flex w-full lg items-center text-white justify-center rounded-lg bg-[#1053F3] px-6 py-2.5 font-semibold hover hover transition duration-200\"><span>Get\n                        started\n                    </span>\n                </a>\n                <a href=\"#\"\n                    className=\"flex w-full lg items-center text-[#1053F3] justify-center rounded-lg border border-[#6A65FF] px-6 py-2.5 font-semibold hover hover transition duration-200 bg-[#5138EE]/10 dark dark dark500/50\"><span>Learn\n                        more\n                    </span>\n                </a>\n            </div>\n        </div>\n        <div className=\"hero-image md5 lg0 w-full lg1/2 rounded-3xl md2 lg0 relative isolate z-10\">\n            <img className=\"rounded-3xl w-full\"\n                src=\"https://images.unsplash.com/photo-1590650516494-0c8e4a4dd67e?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxMnx8c2VydmljZXxlbnwwfDB8fHwxNzEyMjIyNjQ3fDA&ixlib=rb-4.0.3&q=80&w=1080\"\n                alt=\"\" />\n        </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div\n    class=\"px-7 lg:px-10 max-w-6xl mx-auto flex flex-col gap-y-10 lg:flex-row items-center gap-x-10 justify-center py-10 lg:py-14 dark:bg-gray-800\">\n    <div class=\"lg:w-[650px] lg:px-5 flex flex-col gap-y-5\">\n        <h1\n            class=\"text-4xl md:text-5xl xl:text-[50px] leading-[1.2] md:max-w-xl md:mx-auto md:text-center lg:text-left lg:mx-0 lg:max-w-full font-semibold dark:text-white\">\n            Discover the power of streamlined services\n        </h1>\n        <p class=\"text-sm md:max-w-xl md:mx-auto lg:mx-0 lg:max-w-full md:text-center lg:text-left dark:text-gray-300\">\n            With\n            efficient services available online, you can simplify your tasks and save valuable time.</p>\n        <div class=\"flex gap-x-5 flex-col gap-y-2.5 lg:flex-row\">\n            <a href=\"#\"\n                class=\"flex w-full lg:w-fit items-center text-white justify-center rounded-lg bg-[#1053F3] px-6 py-2.5 font-semibold hover:shadow-lg hover:drop-shadow transition duration-200\"><span>Get\n                    started\n                </span>\n            </a>\n            <a href=\"#\"\n                class=\"flex w-full lg:w-fit items-center text-[#1053F3] justify-center rounded-lg border border-[#6A65FF] px-6 py-2.5 font-semibold hover:shadow-lg hover:drop-shadow transition duration-200 bg-[#5138EE]/10 dark:text-white dark:bg-transparent dark:border-gray-500/50\"><span>Learn\n                    more\n                </span>\n            </a>\n        </div>\n    </div>\n    <div class=\"hero-image md:px-5 lg:px-0 w-full lg:w-1/2 rounded-3xl md:pt-2 lg:pt-0 relative isolate z-10\">\n        <img class=\"rounded-3xl w-full\"\n            src=\"https://images.unsplash.com/photo-1590650516494-0c8e4a4dd67e?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxMnx8c2VydmljZXxlbnwwfDB8fHwxNzEyMjIyNjQ3fDA&ixlib=rb-4.0.3&q=80&w=1080\"\n            alt=\"\">\n    </div>\n</div>"
