    "code": "/**\n * Component: Clean hero section\n * Author: @freja-jensen (https://tailwindflex.com/@freja-jensen)\n * Source: https://tailwindflex.com/@freja-jensen/clean-hero-section\n * Attribution: Créé par @freja-jensen sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function CleanHeroSection() {\n  return (\n    <div>\n    <div className=\"bg-gradient-to-r from-pink-500 to-purple-500\">\n      <div className=\"container mx-auto py-16 px-8\">\n        <h1 className=\"text-white text-5xl font-bold leading-tight mb-8\">Welcome to Tailwind World</h1>\n        <p className=\"text-white text-lg mb-12\">We're the leading experts in Tailwind CSS and we're here to help you create amazing designs with ease.</p>\n        <a href=\"#\" className=\"bg-white text-purple-500 hover hover500 py-4 px-8 font-medium rounded-full inline-block transition duration-200\">Learn More</a>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"bg-gradient-to-r from-pink-500 to-purple-500\">\n  <div class=\"container mx-auto py-16 px-8\">\n    <h1 class=\"text-white text-5xl font-bold leading-tight mb-8\">Welcome to Tailwind World</h1>\n    <p class=\"text-white text-lg mb-12\">We're the leading experts in Tailwind CSS and we're here to help you create amazing designs with ease.</p>\n    <a href=\"#\" class=\"bg-white text-purple-500 hover:text-white hover:bg-purple-500 py-4 px-8 font-medium rounded-full inline-block transition duration-200\">Learn More</a>\n  </div>\n</div>"
