    "code": "/**\n * Component: Hero Beer\n * Author: @sammytg7 (https://tailwindflex.com/@sammytg7)\n * Source: https://tailwindflex.com/@sammytg7/hero-section-for-beer-factory-website\n * Attribution: Créé par @sammytg7 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroSectionForBeerFactoryWebsite() {\n  return (\n    <div>\n    <div className=\"w-full h-screen bg-[url('https://images.unsplash.com/9/fields.jpg?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxMXx8bGVudGFscyUyMGZhcm18ZW58MHwwfHx8MTcxMjc0NjE1OXww&ixlib=rb-4.0.3&q=80&w=1080')] bg-center bg-cover bg-no-repeat\">\n        \n        <header className=\"md[80%] xs[90%] mx-auto rounded-xl border-b-4 border-black/20 px-4 flex flex-wrap items-center py-4 shadow-lg\">\n            <div className=\"flex-1 flex justify-between items-center\">\n                <h2 className=\"py-2 px-4 bg-sky-300/20 border-2 border-dashed rounded-full text-4xl font-serif font-semibold text-gray-100\">BEER</h2>\n            </div>\n            <label htmlFor=\"menu-toggle\" className=\"pointer-cursor md block\">\n                <svg className=\"fill-current text-gray-100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 20 20\">\n                <title>menu</title>\n                <path d=\"M0 3h20v2H0V3zm0 6h20v2H0V9zm0 6h20v2H0v-2z\"></path>\n                </svg>\n                </label>\n            <input className=\"hidden\" type=\"checkbox\" id=\"menu-toggle\" />\n    \n            <div className=\"hidden md md md w-full z-10\" id=\"menu\">\n                <nav>\n                    <ul className=\"md items-center justify-between text-base text-gray-800 pt-4 md0\">\n                        <li><a className=\"md4 py-3 px-0 block text-gray-100\" href=\"#\">Home</a></li>\n                        <li><a className=\"md4 py-3 px-0 block\" href=\"#\">Products</a></li>\n                        <li><a className=\"md4 py-3 px-0 block\" href=\"#\">Shop</a></li>\n                        <li><a className=\"md4 py-3 px-0 block\" href=\"#\">About</a></li>\n                        <li><a className=\"md4 py-3 px-0 block md0 mb-2\" href=\"#\">Contact</a></li>\n                    </ul>\n                </nav>\n            </div>\n        </header>\n        \n        <div\n            className=\"[&>*:last-child]:hover0 md:[&>*:last-child]:hover[15rem] lg:[&>*:last-child]:hover[18rem] md:[&>*:last-child]:hover[13rem] xs:[&>*:last-child]:hover[7rem] group absolute top-[30%] md[30%] sm[25%] xs[15%]\">\n            <div\n                className=\"[transition_400ms_ease] group-hover0 lg[18rem] lg[22rem] md[14rem] md[18rem] sm[12rem] sm[16rem] xs[10rem] xs[12rem] border-[0.4rem] border-transparent shadow-xl absolute -rotate-[10deg] origin-bottom-left\">\n                <img src=\"https://images.unsplash.com/photo-1436076863939-06870fe779c2?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwzfHxiZWVyfGVufDB8MHx8fDE3MTI3NDU4Njh8MA&ixlib=rb-4.0.3&q=80&w=1080\" className=\"w-full h-full rounded-sm\" alt=\"Frame Two\" />\n            </div>\n            <div\n                className=\"[transition_400ms_ease] absolute -rotate-[10deg] last[20deg] -top-[2rem] left-[2rem] group-hover0 lg[18rem] lg[22rem] md[14rem] md[18rem] sm[12rem] sm[16rem] xs[10rem] xs[12rem] border-[0.4rem] border-transparent shadow-xl origin-bottom-left\">\n                <img src=\"https://images.unsplash.com/photo-1608270586620-248524c67de9?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw0fHxiZWVyfGVufDB8MHx8fDE3MTI3NDU4Njh8MA&ixlib=rb-4.0.3&q=80&w=1080\" className=\"w-full h-full rounded-sm\" alt=\"Frame One\" />\n            </div>\n        </div>\n    \n        <div className=\"absolute bg-black/20 py-2 md[75%] sm[70%] xs[60%]\">\n            <h1 className=\"w-full md4 xs2 xl7xl lg5xl sm4xl xs3xl text-white text-center font-serif font-semibold\">Farm-Fresh Brews: From Field to Glass, an Unforgettable Beer Journey.</h1>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"w-full h-screen bg-[url('https://images.unsplash.com/9/fields.jpg?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxMXx8bGVudGFscyUyMGZhcm18ZW58MHwwfHx8MTcxMjc0NjE1OXww&ixlib=rb-4.0.3&q=80&w=1080')] bg-center bg-cover bg-no-repeat\">\n    <!-- Nav -->\n    <header class=\"md:w-[80%] xs:w-[90%] mx-auto rounded-xl border-b-4 border-black/20 px-4 flex flex-wrap items-center py-4 shadow-lg\">\n        <div class=\"flex-1 flex justify-between items-center\">\n            <h2 class=\"py-2 px-4 bg-sky-300/20 border-2 border-dashed rounded-full text-4xl font-serif font-semibold text-gray-100\">BEER</h2>\n        </div>\n        <label for=\"menu-toggle\" class=\"pointer-cursor md:hidden block\">\n            <svg class=\"fill-current text-gray-100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 20 20\">\n            <title>menu</title>\n            <path d=\"M0 3h20v2H0V3zm0 6h20v2H0V9zm0 6h20v2H0v-2z\"></path>\n            </svg>\n            </label>\n        <input class=\"hidden\" type=\"checkbox\" id=\"menu-toggle\" />\n\n        <div class=\"hidden md:flex md:items-center md:w-auto w-full z-10\" id=\"menu\">\n            <nav>\n                <ul class=\"md:flex items-center justify-between text-base text-gray-800 pt-4 md:pt-0\">\n                    <li><a class=\"md:p-4 py-3 px-0 block text-gray-100\" href=\"#\">Home</a></li>\n                    <li><a class=\"md:p-4 py-3 px-0 block\" href=\"#\">Products</a></li>\n                    <li><a class=\"md:p-4 py-3 px-0 block\" href=\"#\">Shop</a></li>\n                    <li><a class=\"md:p-4 py-3 px-0 block\" href=\"#\">About</a></li>\n                    <li><a class=\"md:p-4 py-3 px-0 block md:mb-0 mb-2\" href=\"#\">Contact</a></li>\n                </ul>\n            </nav>\n        </div>\n    </header>\n    <!-- End of Nav -->\n    <div\n        class=\"[&>*:last-child]:hover:top-0 md:[&>*:last-child]:hover:left-[15rem] lg:[&>*:last-child]:hover:left-[18rem] md:[&>*:last-child]:hover:left-[13rem] xs:[&>*:last-child]:hover:left-[7rem] group absolute top-[30%] md:left-[30%] sm:left-[25%] xs:left-[15%]\">\n        <div\n            class=\"[transition:all_400ms_ease] group-hover:rotate-0 lg:w-[18rem] lg:h-[22rem] md:w-[14rem] md:h-[18rem] sm:w-[12rem] sm:h-[16rem] xs:w-[10rem] xs:h-[12rem] border-[0.4rem] border-transparent shadow-xl absolute -rotate-[10deg] origin-bottom-left\">\n            <img src=\"https://images.unsplash.com/photo-1436076863939-06870fe779c2?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwzfHxiZWVyfGVufDB8MHx8fDE3MTI3NDU4Njh8MA&ixlib=rb-4.0.3&q=80&w=1080\" class=\"w-full h-full rounded-sm\" alt=\"Frame Two\">\n        </div>\n        <div\n            class=\"[transition:all_400ms_ease] absolute -rotate-[10deg] last:rotate-[20deg] -top-[2rem] left-[2rem] group-hover:rotate-0 lg:w-[18rem] lg:h-[22rem] md:w-[14rem] md:h-[18rem] sm:w-[12rem] sm:h-[16rem] xs:w-[10rem] xs:h-[12rem] border-[0.4rem] border-transparent shadow-xl origin-bottom-left\">\n            <img src=\"https://images.unsplash.com/photo-1608270586620-248524c67de9?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw0fHxiZWVyfGVufDB8MHx8fDE3MTI3NDU4Njh8MA&ixlib=rb-4.0.3&q=80&w=1080\" class=\"w-full h-full rounded-sm\" alt=\"Frame One\">\n        </div>\n    </div>\n\n    <div class=\"absolute bg-black/20 py-2 md:top-[75%] sm:top-[70%] xs:top-[60%]\">\n        <h1 class=\"w-full md:px-4 xs:px-2 xl:text-7xl lg:text-5xl sm:text-4xl xs:text-3xl text-white text-center font-serif font-semibold\">Farm-Fresh Brews: From Field to Glass, an Unforgettable Beer Journey.</h1>\n    </div>\n</div>"
