    "rawHtml": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Login Form</title>\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <!-- Optional: Include Tailwind forms plugin for better form styling -->\r\n    <script src=\"https://cdn.tailwindcss.com?plugins=forms\"></script>\r\n</head>\r\n<body class=\"bg-gray-100 min-h-screen flex items-center justify-center\">\r\n    <div class=\"bg-white p-8 rounded-lg shadow-md w-full max-w-md\">\r\n        <div class=\"text-center mb-8\">\r\n            <h1 class=\"text-2xl font-bold text-gray-800\">Welcome Back</h1>\r\n            <p class=\"text-gray-600\">Please enter your credentials to login</p>\r\n        </div>\r\n        \r\n        <form class=\"space-y-6\">\r\n            <div>\r\n                <label for=\"email\" class=\"block text-sm font-medium text-gray-700 mb-1\">Email Address</label>\r\n                <input \r\n                    type=\"email\" \r\n                    id=\"email\" \r\n                    name=\"email\" \r\n                    required \r\n                    class=\"w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent\"\r\n                    placeholder=\"your@email.com\">\r\n            </div>\r\n            \r\n            <div>\r\n                <label for=\"password\" class=\"block text-sm font-medium text-gray-700 mb-1\">Password</label>\r\n                <input \r\n                    type=\"password\" \r\n                    id=\"password\" \r\n                    name=\"password\" \r\n                    required \r\n                    class=\"w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent\"\r\n                    placeholder=\"••••••••\">\r\n            </div>\r\n            \r\n            <div class=\"flex items-center justify-between\">\r\n                <div class=\"flex items-center\">\r\n                    <input \r\n                        id=\"remember-me\" \r\n                        name=\"remember-me\" \r\n                        type=\"checkbox\" \r\n                        class=\"h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded\">\r\n                    <label for=\"remember-me\" class=\"ml-2 block text-sm text-gray-700\">Remember me</label>\r\n                </div>\r\n                \r\n                <div class=\"text-sm\">\r\n                    <a href=\"#\" class=\"font-medium text-blue-600 hover:text-blue-500\">Forgot password?</a>\r\n                </div>\r\n            </div>\r\n            \r\n            <div>\r\n                <button \r\n                    type=\"submit\" \r\n                    class=\"w-full py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition duration-150\">\r\n                    Sign in\r\n                </button>\r\n            </div>\r\n        </form>\r\n        \r\n        <div class=\"mt-6\">\r\n            <div class=\"relative\">\r\n                <div class=\"absolute inset-0 flex items-center\">\r\n                    <div class=\"w-full border-t border-gray-300\"></div>\r\n                </div>\r\n                <div class=\"relative flex justify-center text-sm\">\r\n                    <span class=\"px-2 bg-white text-gray-500\">Or continue with</span>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"mt-6 grid grid-cols-2 gap-3\">\r\n                <button type=\"button\" class=\"w-full inline-flex justify-center py-2 px-4 border border-gray-300 rounded-md shadow-sm bg-white text-sm font-medium text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500\">\r\n                    <svg class=\"w-5 h-5\" fill=\"currentColor\" viewBox=\"0 0 20 20\" aria-hidden=\"true\">\r\n                        <path fill-rule=\"evenodd\" d=\"M10 0C4.477 0 0 4.477 0 10c0 4.42 2.865 8.166 6.839 9.489.5.092.682-.217.682-.482 0-.237-.008-.866-.013-1.7-2.782.603-3.369-1.34-3.369-1.34-.454-1.156-1.11-1.462-1.11-1.462-.908-.62.069-.608.069-.608 1.003.07 1.531 1.03 1.531 1.03.892 1.529 2.341 1.087 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.11-4.555-4.943 0-1.091.39-1.984 1.029-2.683-.103-.253-.446-1.27.098-2.647 0 0 .84-.269 2.75 1.025A9.564 9.564 0 0110 4.844c.85.004 1.705.114 2.504.336 1.909-1.294 2.747-1.025 2.747-1.025.546 1.377.203 2.394.1 2.647.64.699 1.028 1.592 1.028 2.683 0 3.842-2.339 4.687-4.566 4.933.359.309.678.919.678 1.852 0 1.336-.012 2.415-.012 2.743 0 .267.18.578.688.48C17.14 18.163 20 14.418 20 10c0-5.523-4.477-10-10-10z\" clip-rule=\"evenodd\" />\r\n                    </svg>\r\n                </button>\r\n                \r\n                <button type=\"button\" class=\"w-full inline-flex justify-center py-2 px-4 border border-gray-300 rounded-md shadow-sm bg-white text-sm font-medium text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500\">\r\n                    <svg class=\"w-5 h-5\" fill=\"currentColor\" viewBox=\"0 0 20 20\" aria-hidden=\"true\">\r\n                        <path d=\"M6.29 18.251c7.547 0 11.675-6.253 11.675-11.675 0-.178 0-.355-.012-.53A8.348 8.348 0 0020 3.92a8.19 8.19 0 01-2.357.646 4.118 4.118 0 001.804-2.27 8.224 8.224 0 01-2.605.996 4.107 4.107 0 00-6.993 3.743 11.65 11.65 0 01-8.457-4.287 4.106 4.106 0 001.27 5.477A4.073 4.073 0 01.8 7.713v.052a4.105 4.105 0 003.292 4.022 4.095 4.095 0 01-1.853.07 4.108 4.108 0 003.834 2.85A8.233 8.233 0 010 16.407a11.616 11.616 0 006.29 1.84\" />\r\n                    </svg>\r\n                </button>\r\n            </div>\r\n            \r\n            <p class=\"mt-6 text-center text-sm text-gray-600\">\r\n                Don't have an account? \r\n                <a href=\"#\" class=\"font-medium text-blue-600 hover:text-blue-500\">Sign up</a>\r\n            </p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>"
