    "code": "/**\n * Component: Hero Section with Tailwind CSS With Buttons\n * Author: @abdul-baset-bappy (https://tailwindflex.com/@abdul-baset-bappy)\n * Source: https://tailwindflex.com/@abdul-baset-bappy/hero-section-with-tailwind-css-with-buttons\n * Attribution: Créé par @abdul-baset-bappy sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HeroSectionWithTailwindCssWithButtons() {\n  return (\n    <div>\n    <section className=\"bg-white lg lg lg dark900\">\n      <div\n        className=\"mx-auto w-screen max-w-screen-xl px-4 py-16 sm6 sm24 md md2 md md4 lg8 lg32\"\n      >\n        <div className=\"max-w-prose text-left\">\n          <h1 className=\"text-4xl font-bold text-gray-900 sm5xl dark\">\n            Understand user flow and\n            <strong className=\"text-indigo-600\"> increase </strong>\n            conversions\n          </h1>\n    \n          <p className=\"mt-4 text-base text-pretty text-gray-700 sm/relaxed dark200\">\n            Lorem ipsum dolor sit amet, consectetur adipisicing elit. Eaque, nisi. Natus, provident\n            accusamus impedit minima harum corporis iusto.\n          </p>\n    \n          <div className=\"mt-4 flex gap-4 sm6\">\n            <a\n              className=\"inline-block rounded border border-indigo-600 bg-indigo-600 px-5 py-3 font-medium text-white shadow-sm transition-colors hover700\"\n              href=\"#\"\n            >\n              Get Started\n            </a>\n    \n            <a\n              className=\"inline-block rounded border border-gray-200 px-5 py-3 font-medium text-gray-700 shadow-sm transition-colors hover50 hover900 dark700 dark200 dark800 dark\"\n              href=\"#\"\n            >\n              Learn More\n            </a>\n          </div>\n        </div>\n    \n       \n        <div className=\"mt-6 md0 sm10\">\n          <img \n            className=\"w-full h-auto max-w-full rounded-lg object-cover md[400px] lg[500px]\" \n            src=\"https://plus.unsplash.com/premium_photo-1689568126014-06fea9d5d341?fm=jpg&q=60&w=3000&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8MXx8cHJvZmlsZXxlbnwwfHwwfHx8MA%3D%3D\" \n            alt=\"Any Image Here\" \n          />\n        </div>\n      </div>\n    </section>\n    </div>\n  );\n}\n",
    "rawHtml": "<section class=\"bg-white lg:grid lg:min-h-screen lg:place-content-center dark:bg-gray-900\">\n  <div\n    class=\"mx-auto w-screen max-w-screen-xl px-4 py-16 sm:px-6 sm:py-24 md:grid md:grid-cols-2 md:items-center md:gap-4 lg:px-8 lg:py-32\"\n  >\n    <div class=\"max-w-prose text-left\">\n      <h1 class=\"text-4xl font-bold text-gray-900 sm:text-5xl dark:text-white\">\n        Understand user flow and\n        <strong class=\"text-indigo-600\"> increase </strong>\n        conversions\n      </h1>\n\n      <p class=\"mt-4 text-base text-pretty text-gray-700 sm:text-lg/relaxed dark:text-gray-200\">\n        Lorem ipsum dolor sit amet, consectetur adipisicing elit. Eaque, nisi. Natus, provident\n        accusamus impedit minima harum corporis iusto.\n      </p>\n\n      <div class=\"mt-4 flex gap-4 sm:mt-6\">\n        <a\n          class=\"inline-block rounded border border-indigo-600 bg-indigo-600 px-5 py-3 font-medium text-white shadow-sm transition-colors hover:bg-indigo-700\"\n          href=\"#\"\n        >\n          Get Started\n        </a>\n\n        <a\n          class=\"inline-block rounded border border-gray-200 px-5 py-3 font-medium text-gray-700 shadow-sm transition-colors hover:bg-gray-50 hover:text-gray-900 dark:border-gray-700 dark:text-gray-200 dark:hover:bg-gray-800 dark:hover:text-white\"\n          href=\"#\"\n        >\n          Learn More\n        </a>\n      </div>\n    </div>\n\n   <!-- Responsive Image -->\n    <div class=\"mt-6 md:mt-0 sm:p-10\">\n      <img \n        class=\"w-full h-auto max-w-full rounded-lg object-cover md:h-[400px] lg:h-[500px]\" \n        src=\"https://plus.unsplash.com/premium_photo-1689568126014-06fea9d5d341?fm=jpg&q=60&w=3000&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8MXx8cHJvZmlsZXxlbnwwfHwwfHx8MA%3D%3D\" \n        alt=\"Any Image Here\" \n      />\n    </div>\n  </div>\n</section>"
