    "rawHtml": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Login Form</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n</head>\n<body class=\"bg-gray-100 min-h-screen flex items-center justify-center\">\n    <div class=\"bg-white p-8 rounded-lg shadow-md w-full max-w-md\">\n        <div class=\"text-center mb-8\">\n            <h1 class=\"text-2xl font-bold text-gray-800\">Welcome Back</h1>\n            <p class=\"text-gray-600\">Please enter your credentials to login</p>\n        </div>\n        \n        <form class=\"space-y-6\">\n            <div>\n                <label for=\"email\" class=\"block text-sm font-medium text-gray-700 mb-1\">Email Address</label>\n                <input \n                    type=\"email\" \n                    id=\"email\" \n                    placeholder=\"your@email.com\" \n                    class=\"w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent\"\n                    required\n                >\n            </div>\n            \n            <div>\n                <label for=\"password\" class=\"block text-sm font-medium text-gray-700 mb-1\">Password</label>\n                <input \n                    type=\"password\" \n                    id=\"password\" \n                    placeholder=\"••••••••\" \n                    class=\"w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent\"\n                    required\n                >\n            </div>\n            \n            <div class=\"flex items-center justify-between\">\n                <div class=\"flex items-center\">\n                    <input \n                        type=\"checkbox\" \n                        id=\"remember-me\" \n                        class=\"h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded\"\n                    >\n                    <label for=\"remember-me\" class=\"ml-2 block text-sm text-gray-700\">Remember me</label>\n                </div>\n                \n                <div>\n                    <a href=\"#\" class=\"text-sm text-blue-600 hover:text-blue-500\">Forgot password?</a>\n                </div>\n            </div>\n            \n            <div>\n                <button \n                    type=\"submit\" \n                    class=\"w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 transition duration-150\"\n                >\n                    Sign In\n                </button>\n            </div>\n        </form>\n        \n        <div class=\"mt-6\">\n            <div class=\"relative\">\n                <div class=\"absolute inset-0 flex items-center\">\n                    <div class=\"w-full border-t border-gray-300\"></div>\n                </div>\n                <div class=\"relative flex justify-center text-sm\">\n                    <span class=\"px-2 bg-white text-gray-500\">Or continue with</span>\n                </div>\n            </div>\n            \n            <div class=\"mt-6 grid grid-cols-2 gap-3\">\n                <button \n                    type=\"button\" \n                    class=\"w-full inline-flex justify-center py-2 px-4 border border-gray-300 rounded-md shadow-sm bg-white text-sm font-medium text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500\"\n                >\n                    <svg class=\"w-5 h-5\" fill=\"currentColor\" viewBox=\"0 0 20 20\" aria-hidden=\"true\">\n                        <path fill-rule=\"evenodd\" d=\"M10 0C4.477 0 0 4.477 0 10c0 4.42 2.865 8.166 6.839 9.489.5.092.682-.217.682-.482 0-.237-.008-.866-.013-1.7-2.782.603-3.369-1.342-3.369-1.342-.454-1.155-1.11-1.462-1.11-1.462-.908-.62.069-.608.069-.608 1.003.07 1.531 1.03 1.531 1.03.892 1.529 2.341 1.087 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.11-4.555-4.943 0-1.091.39-1.984 1.029-2.683-.103-.253-.446-1.27.098-2.647 0 0 .84-.269 2.75 1.025A9.564 9.564 0 0110 4.844c.85.004 1.705.114 2.504.336 1.909-1.294 2.747-1.025 2.747-1.025.546 1.377.203 2.394.1 2.647.64.699 1.028 1.592 1.028 2.683 0 3.842-2.339 4.687-4.566 4.933.359.309.678.919.678 1.852 0 1.336-.012 2.415-.012 2.743 0 .267.18.578.688.48C17.14 18.163 20 14.418 20 10c0-5.523-4.477-10-10-10z\" clip-rule=\"evenodd\" />\n                    </svg>\n                </button>\n                \n                <button \n                    type=\"button\" \n                    class=\"w-full inline-flex justify-center py-2 px-4 border border-gray-300 rounded-md shadow-sm bg-white text-sm font-medium text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500\"\n                >\n                    <svg class=\"w-5 h-5\" fill=\"currentColor\" viewBox=\"0 0 20 20\" aria-hidden=\"true\">\n                        <path d=\"M6.29 18.251c7.547 0 11.675-6.253 11.675-11.675 0-.178 0-.355-.012-.53A8.348 8.348 0 0020 3.92a8.19 8.19 0 01-2.357.646 4.118 4.118 0 001.804-2.27 8.224 8.224 0 01-2.605.996 4.107 4.107 0 00-6.993 3.743 11.65 11.65 0 01-8.457-4.287 4.106 4.106 0 001.27 5.477A4.073 4.073 0 01.8 7.713v.052a4.105 4.105 0 003.292 4.022 4.095 4.095 0 01-1.853.07 4.108 4.108 0 003.834 2.85A8.233 8.233 0 010 16.407a11.616 11.616 0 006.29 1.84\" />\n                    </svg>\n                </button>\n            </div>\n            \n            <div class=\"mt-6 text-center\">\n                <p class=\"text-sm text-gray-600\">\n                    Don't have an account? \n                    <a href=\"#\" class=\"font-medium text-blue-600 hover:text-blue-500\">Sign up</a>\n                </p>\n            </div>\n        </div>\n    </div>\n</body>\n</html>"
