    "code": "/**\n * Component: composent section presentation société\n * Author: @omer-fils-elenga (https://tailwindflex.com/@omer-fils-elenga)\n * Source: https://tailwindflex.com/@omer-fils-elenga/composent-section-presentation-societe\n * Attribution: Créé par @omer-fils-elenga sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ComposentSectionPresentationSociete() {\n  return (\n    <div dangerouslySetInnerHTML={{ __html: \"<style>\\n  /* Custom styles */\\n  .gradient-bg {\\n    background: linear-gradient(45deg, Fuchsia, #8A2BE2);\\n  }\\n</style>\\n\\n\\n<!-- Présentation rapide Section -->\\n<section class=\\\"py-16 px-6 gradient-bg\\\">\\n  <div class=\\\"max-w-screen-xl mx-auto flex flex-col justify-center items-center\\\">\\n    <div class=\\\"grid grid-cols-1 gap-y-8 lg:grid-cols-2 lg:gap-x-16 items-center\\\">\\n      <!-- Description -->\\n      <div class=\\\"text-center lg:text-left\\\">\\n        <h2 class=\\\"text-4xl font-extrabold text-white mb-4\\\">\\n          Présentation de [Non societe]\\n        </h2>\\n        <p class=\\\"text-gray-200 mb-8\\\">\\n          Nous sommes [nom societe] , une startup innovante qui transforme la\\n          gestion scolaire avec des solutions logicielles sur mesure.\\n          Notre mission est de rendre la gestion éducative plus fluide et\\n          efficace, en offrant des outils puissants pour les\\n          établissements scolaires.\\n        </p>\\n        <div class=\\\"btn\\\">\\n          <!-- Contact Button -->\\n          <a class=\\\"group relative inline-flex items-center overflow-hidden bg-gradient-to-r from-fuchsia-600 to-violet-400 rounded-3xl border px-8 py-3 text-[#1c2e45] focus:outline-none focus:ring active:text-indigo-500 hover:text-white\\\"\\n            href=\\\"#contact\\\">\\n            <span class=\\\"absolute -end-full transition-all group-hover:end-4\\\">\\n                    <svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"24\\\" height=\\\"24\\\" viewBox=\\\"0 0 24 24\\\" style=\\\"\\n                        fill: rgba(255, 255, 255, 1);\\n                        transform: ;\\n                        msfilter: ;\\n                      \\\">\\n                      <path d=\\\"m11.293 17.293 1.414 1.414L19.414 12l-6.707-6.707-1.414 1.414L15.586 11H6v2h9.586z\\\"></path>\\n                    </svg>\\n                  </span>\\n            <span data-aos=\\\"zoom-out-left\\\" data-aos-easing=\\\"linear\\\" data-aos-duration=\\\"800\\\" class=\\\"text-sm font-medium text-slate-100 capitalize transition-all group-hover:me-4 aos-init aos-animate\\\">\\n                    Lire plus ...\\n                  </span>\\n          </a>\\n        </div>\\n      </div>\\n\\n      <div class=\\\"text-center lg:text-left \\\">\\n        <img src=\\\"data:image/png;base64,\\\" alt=\\\"GreatFy\\\" class=\\\"w-full\\\">\\n      </div>\\n      <!-- Mission et Valeurs -->\\n    </div>\\n  </div>\\n</section>\" }} />\n  );\n}\n",
    "rawHtml": "<style>\n  /* Custom styles */\n  .gradient-bg {\n    background: linear-gradient(45deg, Fuchsia, #8A2BE2);\n  }\n</style>\n\n\n<!-- Présentation rapide Section -->\n<section class=\"py-16 px-6 gradient-bg\">\n  <div class=\"max-w-screen-xl mx-auto flex flex-col justify-center items-center\">\n    <div class=\"grid grid-cols-1 gap-y-8 lg:grid-cols-2 lg:gap-x-16 items-center\">\n      <!-- Description -->\n      <div class=\"text-center lg:text-left\">\n        <h2 class=\"text-4xl font-extrabold text-white mb-4\">\n          Présentation de [Non societe]\n        </h2>\n        <p class=\"text-gray-200 mb-8\">\n          Nous sommes [nom societe] , une startup innovante qui transforme la\n          gestion scolaire avec des solutions logicielles sur mesure.\n          Notre mission est de rendre la gestion éducative plus fluide et\n          efficace, en offrant des outils puissants pour les\n          établissements scolaires.\n        </p>\n        <div class=\"btn\">\n          <!-- Contact Button -->\n          <a class=\"group relative inline-flex items-center overflow-hidden bg-gradient-to-r from-fuchsia-600 to-violet-400 rounded-3xl border px-8 py-3 text-[#1c2e45] focus:outline-none focus:ring active:text-indigo-500 hover:text-white\"\n            href=\"#contact\">\n            <span class=\"absolute -end-full transition-all group-hover:end-4\">\n                    <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" style=\"\n                        fill: rgba(255, 255, 255, 1);\n                        transform: ;\n                        msfilter: ;\n                      \">\n                      <path d=\"m11.293 17.293 1.414 1.414L19.414 12l-6.707-6.707-1.414 1.414L15.586 11H6v2h9.586z\"></path>\n                    </svg>\n                  </span>\n            <span data-aos=\"zoom-out-left\" data-aos-easing=\"linear\" data-aos-duration=\"800\" class=\"text-sm font-medium text-slate-100 capitalize transition-all group-hover:me-4 aos-init aos-animate\">\n                    Lire plus ...\n                  </span>\n          </a>\n        </div>\n      </div>\n\n      <div class=\"text-center lg:text-left \">\n        <img src=\"data:image/png;base64,\" alt=\"GreatFy\" class=\"w-full\">\n      </div>\n      <!-- Mission et Valeurs -->\n    </div>\n  </div>\n</section>"
