    "code": "/**\n * Component: Tailkits Hero Section\n * Author: @yucelfaruksahan (https://tailwindflex.com/@yucelfaruksahan)\n * Source: https://tailwindflex.com/@yucelfaruksahan/tailkits-hero-section\n * Attribution: Créé par @yucelfaruksahan sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function TailkitsHeroSection() {\n  return (\n    <div>\n    <div className=\"bg-white dark800 flex justify-center items-center w-screen h-screen p-5\">\n      <div className=\"border shadow-teal-300 shadow-md max-w-2xl p-6 rounded-lg dark700 dark300\">\n        <h1 className=\"text-4xl font-mono font-extrabold py-3\">Tailwind Playground</h1>\n        <ul className=\"list-disc text-lg px-6\">\n          <li>Everything here works just like it does when you're running Tailwind CSS locally.</li>\n          <li>The preview updates in real-time as you code.</li>\n          <li>Save and share your componentcvcvcvs with the community.</li>\n        </ul>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"bg-white dark:bg-gray-800 flex justify-center items-center w-screen h-screen p-5\">\n  <div class=\"border shadow-teal-300 shadow-md max-w-2xl p-6 rounded-lg dark:bg-gray-700 dark:text-gray-300\">\n    <h1 class=\"text-4xl font-mono font-extrabold py-3\">Tailwind Playground</h1>\n    <ul class=\"list-disc text-lg px-6\">\n      <li>Everything here works just like it does when you're running Tailwind CSS locally.</li>\n      <li>The preview updates in real-time as you code.</li>\n      <li>Save and share your componentcvcvcvs with the community.</li>\n    </ul>\n  </div>\n</div>"
