    "code": "/**\n * Component: App Hero Section\n * Author: @abdul-baset-bappy (https://tailwindflex.com/@abdul-baset-bappy)\n * Source: https://tailwindflex.com/@abdul-baset-bappy/app-hero-section\n * Attribution: Créé par @abdul-baset-bappy sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function AppHeroSection() {\n  return (\n    <div>\n    <div className=\"relative bg-gray-50\">\n        <div className=\"absolute bottom-0 right-0 overflow-hidden lg0\">\n            <img className=\"w-auto h-full\" src=\"https://d33wubrfki0l68.cloudfront.net/1e0fc04f38f5896d10ff66824a62e466839567f8/699b5/images/hero/3/background-pattern.png\" alt=\"\" />\n        </div>\n    \n        <header className=\"relative py-4 md6\">\n            <div className=\"px-4 mx-auto max-w-7xl sm6 lg8\">\n                <div className=\"flex items-center justify-between\">\n                    <div className=\"flex-shrink-0\">\n                        <a href=\"#\" title=\"\" className=\"flex text-2xl font-bold rounded outline-none focus1 focus900 focus2\">\n                          Logo\n                        </a>\n                    </div>\n    \n                    <div className=\"flex lg\">\n                        <button type=\"button\" className=\"text-gray-900\">\n                            <svg className=\"w-7 h-7\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\n                                <path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth=\"1.5\" d=\"M4 6h16M4 12h16M4 18h16\"></path>\n                            </svg>\n                        </button>\n                    </div>\n    \n                    <div className=\"hidden lg lg16 lg lg lg10\">\n                        <div className=\"flex items-center space-x-12\">\n                            <a href=\"#\" title=\"\" className=\"text-base font-medium text-gray-900 transition-all duration-200 rounded focus font-pj hover50 focus1 focus900 focus2\"> Features </a>\n    \n                            <a href=\"#\" title=\"\" className=\"text-base font-medium text-gray-900 transition-all duration-200 rounded focus font-pj hover50 focus1 focus900 focus2\"> Pricing </a>\n    \n                            <a href=\"#\" title=\"\" className=\"text-base font-medium text-gray-900 transition-all duration-200 rounded focus font-pj hover50 focus1 focus900 focus2\"> Automation </a>\n                        </div>\n    \n                        <div className=\"w-px h-5 bg-gray-300\"></div>\n    \n                        <a href=\"#\" title=\"\" className=\"text-base font-medium text-gray-900 transition-all duration-200 rounded focus font-pj hover50 focus1 focus900 focus2\"> Login </a>\n    \n                        <a\n                            href=\"#\"\n                            title=\"\"\n                            className=\"px-5 py-2 text-base font-semibold leading-7 text-gray-900 transition-all duration-200 bg-transparent border border-gray-900 rounded-xl font-pj focus focus2 focus2 focus900 hover900 hover focus900 focus\"\n                            role=\"button\"\n                        >\n                            Create free account\n                        </a>\n                    </div>\n                </div>\n            </div>\n        </header>\n    \n        <section className=\"relative py-12 sm16 lg20 lg36\">\n            <div className=\"px-4 mx-auto sm6 lg8 max-w-7xl\">\n                <div className=\"grid grid-cols-1 gap-y-8 lg lg2 sm20 xl5\">\n                    <div className=\"text-center xl2 lg md16 lg0\">\n                        <div className=\"max-w-sm mx-auto sm md\">\n                            <h1 className=\"text-4xl font-bold leading-tight text-gray-900 sm5xl sm lg6xl lg font-pj\">Get meaningful feedbacks on your code</h1>\n    \n                            <div className=\"mt-8 lg12 lg lg\">\n                                <div className=\"flex justify-center flex-shrink-0 -space-x-4 overflow-hidden lg\">\n                                    <img className=\"inline-block rounded-full w-14 h-14 ring-2 ring-white\" src=\"https://d33wubrfki0l68.cloudfront.net/3bfa6da479d6b9188c58f2d9a8d33350290ee2ef/301f1/images/hero/3/avatar-male.png\" alt=\"\" />\n                                    <img className=\"inline-block rounded-full w-14 h-14 ring-2 ring-white\" src=\"https://d33wubrfki0l68.cloudfront.net/b52fa09a115db3a80ceb2d52c275fadbf84cf8fc/7fd8a/images/hero/3/avatar-female-1.png\" alt=\"\" />\n                                    <img className=\"inline-block rounded-full w-14 h-14 ring-2 ring-white\" src=\"https://d33wubrfki0l68.cloudfront.net/8a2efb13f103a5ae2909e244380d73087a9c2fc4/31ed6/images/hero/3/avatar-female-2.png\" alt=\"\" />\n                                </div>\n    \n                                <p className=\"mt-4 text-lg text-gray-900 lg0 lg4 font-pj\">Join with <span className=\"font-bold\">4600+ Developers</span> and start getting feedbacks right now</p>\n                            </div>\n                        </div>\n    \n                        <div className=\"mt-8 sm sm sm lg sm5 lg12\">\n                            <a\n                                href=\"#\"\n                                title=\"\"\n                                className=\"inline-flex items-center px-8 py-4 text-lg font-bold text-white transition-all duration-200 bg-gray-900 border border-transparent rounded-xl focus focus2 focus2 focus900 font-pj justif-center hover600\"\n                                role=\"button\"\n                            >\n                                Get feedback\n                            </a>\n    \n                            <a\n                                href=\"#\"\n                                title=\"\"\n                                className=\"inline-flex items-center px-4 py-4 mt-4 text-lg font-bold transition-all duration-200 bg-transparent border border-transparent sm0 font-pj justif-center rounded-xl focus focus2 focus2 focus300 hover200 focus200\"\n                                role=\"button\"\n                            >\n                                <svg className=\"w-5 h-5 mr-2\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\n                                    <path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth=\"2.5\" d=\"M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4\"></path>\n                                </svg>\n                                Download iOS App\n                            </a>\n                        </div>\n                    </div>\n    \n                    <div className=\"xl3\">\n                        <img className=\"w-full mx-auto scale-110\" src=\"https://d33wubrfki0l68.cloudfront.net/29c501c64b21014b3f2e225abe02fe31fd8f3a5c/f866d/images/hero/3/illustration.png\" alt=\"\" />\n                    </div>\n                </div>\n            </div>\n        </section>\n    </div>\n    </div>\n  );\n}\n",
