    "code": "/**\n * Component: Glassmorphism form\n * Author: @geoffrey-callaghan (https://tailwindflex.com/@geoffrey-callaghan)\n * Source: https://tailwindflex.com/@geoffrey-callaghan/glassmorphism-form\n * Attribution: Créé par @geoffrey-callaghan sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function GlassmorphismForm() {\n  return (\n    <div dangerouslySetInnerHTML={{ __html: \"<div class=\\\"bg-gradient-to-r from-blue-300 to-purple-500 h-screen flex justify-center items-center\\\">\\n    <div class=\\\"py-8 px-6 max-w-md bg-white bg-opacity-30 rounded-lg shadow-lg backdrop-blur-xl backdrop-filter\\\">\\n        <h1 class=\\\"text-3xl font-extrabold text-center text-gray-800 mb-5\\\">Glassmorphism Design</h1>\\n        <p class=\\\"text-lg text-center text-gray-700 mb-8\\\">Using Tailwind CSS</p>\\n     \\n        <form class=\\\"flex flex-col\\\" action=\\\"https://fabform.io/f/{form-id}\\\" method=\\\"post\\\">\\n        <form class=\\\"flex flex-col\\\">\\n            <div class=\\\"mb-5\\\">\\n                <label class=\\\"text-gray-700 font-semibold mb-2\\\" for=\\\"name\\\">Name</label>\\n                <input class=\\\"bg-transparent border rounded-lg shadow border-gray-300 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 py-2 px-4 block w-full appearance-none leading-normal\\\" type=\\\"text\\\" id=\\\"name\\\" name=\\\"name\\\" required>\\n            </div>\\n            <div class=\\\"mb-5\\\">\\n                <label class=\\\"text-gray-700 font-semibold mb-2\\\" for=\\\"email\\\">Email</label>\\n                <input class=\\\"bg-transparent border rounded-lg shadow border-gray-300 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 py-2 px-4 block w-full appearance-none leading-normal\\\" type=\\\"email\\\" id=\\\"email\\\" name=\\\"email\\\" required>\\n            </div>\\n            <div class=\\\"mb-5\\\">\\n                <label class=\\\"text-gray-700 font-semibold mb-2\\\" for=\\\"message\\\">Message</label>\\n                <textarea class=\\\"bg-transparent border rounded-lg shadow border-gray-300 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 py-2 px-4 block w-full appearance-none leading-normal\\\" id=\\\"message\\\" name=\\\"message\\\" rows=\\\"5\\\" required></textarea>\\n            </div>\\n            <button class=\\\"bg-gradient-to-r from-purple-400 to-indigo-500 text-white font-semibold py-2 rounded-lg shadow-md hover:shadow-lg transition duration-300 ease-in-out mb-5\\\" type=\\\"submit\\\">Send Message</button>\\n        </form>\\n           <a href=\\\"https://veilmail.io/e/FkKh7o\\\" class=\\\"font-medium text-blue-600 hover:underline\\\">Or click here to reveal our protected email address</a>\\n    \\n    </div>\\n    \\n</div>\\n</form>\" }} />\n  );\n}\n",
    "rawHtml": "<div class=\"bg-gradient-to-r from-blue-300 to-purple-500 h-screen flex justify-center items-center\">\n    <div class=\"py-8 px-6 max-w-md bg-white bg-opacity-30 rounded-lg shadow-lg backdrop-blur-xl backdrop-filter\">\n        <h1 class=\"text-3xl font-extrabold text-center text-gray-800 mb-5\">Glassmorphism Design</h1>\n        <p class=\"text-lg text-center text-gray-700 mb-8\">Using Tailwind CSS</p>\n     \n        <form class=\"flex flex-col\" action=\"https://fabform.io/f/{form-id}\" method=\"post\">\n        <form class=\"flex flex-col\">\n            <div class=\"mb-5\">\n                <label class=\"text-gray-700 font-semibold mb-2\" for=\"name\">Name</label>\n                <input class=\"bg-transparent border rounded-lg shadow border-gray-300 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 py-2 px-4 block w-full appearance-none leading-normal\" type=\"text\" id=\"name\" name=\"name\" required>\n            </div>\n            <div class=\"mb-5\">\n                <label class=\"text-gray-700 font-semibold mb-2\" for=\"email\">Email</label>\n                <input class=\"bg-transparent border rounded-lg shadow border-gray-300 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 py-2 px-4 block w-full appearance-none leading-normal\" type=\"email\" id=\"email\" name=\"email\" required>\n            </div>\n            <div class=\"mb-5\">\n                <label class=\"text-gray-700 font-semibold mb-2\" for=\"message\">Message</label>\n                <textarea class=\"bg-transparent border rounded-lg shadow border-gray-300 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 py-2 px-4 block w-full appearance-none leading-normal\" id=\"message\" name=\"message\" rows=\"5\" required></textarea>\n            </div>\n            <button class=\"bg-gradient-to-r from-purple-400 to-indigo-500 text-white font-semibold py-2 rounded-lg shadow-md hover:shadow-lg transition duration-300 ease-in-out mb-5\" type=\"submit\">Send Message</button>\n        </form>\n           <a href=\"https://veilmail.io/e/FkKh7o\" class=\"font-medium text-blue-600 hover:underline\">Or click here to reveal our protected email address</a>\n    \n    </div>\n    \n</div>\n</form>"
