    "code": "/**\n * Component: Confirm OTP Form\n * Author: @santos78 (https://tailwindflex.com/@santos78)\n * Source: https://tailwindflex.com/@santos78/confirm-otp-form\n * Attribution: Créé par @santos78 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ConfirmOtpForm() {\n  return (\n    <div>\n    <div className=\"flex flex-1 flex-col  justify-center space-y-5 max-w-md mx-auto mt-24\">\r\n        <div className=\"flex flex-col space-y-2 text-center\">\r\n            <h2 className=\"text-3xl md4xl font-bold\">Confirm OTP</h2>\r\n            <p className=\"text-md md\">\r\n                Enter the OTP we just sent you.\r\n            </p>\r\n        </div>\r\n        <div className=\"flex flex-col max-w-md space-y-5\">\r\n            <input type=\"text\" placeholder=\"otp\"\r\n                  className=\"flex px-3 py-2 md4 md3 border-2 border-black rounded-lg font-medium placeholder\" />\r\n            <button className=\"flex items-center justify-center flex-none px-3 py-2 md4 md3 border-2 rounded-lg font-medium border-black bg-black text-white\">\r\n                Confirm\r\n            </button>\r\n        </div>\r\n    </div>\n    </div>\n  );\n}\n",
