    "code": "/**\n * Component: Sign up form\n * Author: @lukas-muller (https://tailwindflex.com/@lukas-muller)\n * Source: https://tailwindflex.com/@lukas-muller/sign-up-form\n * Attribution: Créé par @lukas-muller sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function SignUpForm() {\n  return (\n    <div>\n    <div className=\"bg-gray-100 flex h-screen items-center justify-center px-4 sm6 lg8\">\n        <div className=\"w-full max-w-md space-y-8\">\n            <div className=\"bg-white shadow-md rounded-md p-6\">\n    \n                <img className=\"mx-auto h-12 w-auto\" src=\"https://www.svgrepo.com/show/499664/user-happy.svg\" alt=\"\" />\n    \n                <h2 className=\"my-3 text-center text-3xl font-bold tracking-tight text-gray-900\">\n                    Sign up for an account\n                </h2>\n    \n    \n                <form className=\"space-y-6\" method=\"POST\">\n    \n                    <div>\n                        <label htmlFor=\"new-password\" className=\"block text-sm font-medium text-gray-700\">Username</label>\n                        <div className=\"mt-1\">\n                            <input name=\"username\" type=\"username\" required\n                                className=\"px-2 py-3 mt-1 block w-full rounded-md border border-gray-300 shadow-sm focus500 focus focus500 sm\" />\n                        </div>\n                    </div>\n    \n                    <div>\n                        <label htmlFor=\"password\" className=\"block text-sm font-medium text-gray-700\">Email</label>\n                        <div className=\"mt-1\">\n                            <input name=\"email\" type=\"email-address\" autoComplete=\"email-address\" required\n                                className=\"px-2 py-3 mt-1 block w-full rounded-md border border-gray-300 shadow-sm focus500 focus focus500 sm\" />\n                        </div>\n                    </div>\n    \n                    <div>\n                        <label htmlFor=\"password\" className=\"block text-sm font-medium text-gray-700\">Password</label>\n                        <div className=\"mt-1\">\n                            <input name=\"password\" type=\"password\" autoComplete=\"password\" required\n                                className=\"px-2 py-3 mt-1 block w-full rounded-md border border-gray-300 shadow-sm focus500 focus focus500 sm\" />\n                        </div>\n                    </div>\n    \n                    <div>\n                        <label htmlFor=\"password\" className=\"block text-sm font-medium text-gray-700\">Confirm Password</label>\n                        <div className=\"mt-1\">\n                            <input name=\"confirm_password\" type=\"password\" autoComplete=\"confirm-password\" required\n                                className=\"px-2 py-3 mt-1 block w-full rounded-md border border-gray-300 shadow-sm focus500 focus focus500 sm\" />\n                        </div>\n                    </div>\n    \n                    <div>\n                        <button type=\"submit\"\n                            className=\"flex w-full justify-center rounded-md border border-transparent bg-sky-400 py-2 px-4 text-sm font-medium text-white shadow-sm hover75 focus focus2 focus400 focus2\">Register\n                            Account\n                            </button>\n                    </div>\n                </form>\n            </div>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"bg-gray-100 flex h-screen items-center justify-center px-4 sm:px-6 lg:px-8\">\n    <div class=\"w-full max-w-md space-y-8\">\n        <div class=\"bg-white shadow-md rounded-md p-6\">\n\n            <img class=\"mx-auto h-12 w-auto\" src=\"https://www.svgrepo.com/show/499664/user-happy.svg\" alt=\"\" />\n\n            <h2 class=\"my-3 text-center text-3xl font-bold tracking-tight text-gray-900\">\n                Sign up for an account\n            </h2>\n\n\n            <form class=\"space-y-6\" method=\"POST\">\n\n                <div>\n                    <label for=\"new-password\" class=\"block text-sm font-medium text-gray-700\">Username</label>\n                    <div class=\"mt-1\">\n                        <input name=\"username\" type=\"username\" required\n                            class=\"px-2 py-3 mt-1 block w-full rounded-md border border-gray-300 shadow-sm focus:border-sky-500 focus:outline-none focus:ring-sky-500 sm:text-sm\" />\n                    </div>\n                </div>\n\n                <div>\n                    <label for=\"password\" class=\"block text-sm font-medium text-gray-700\">Email</label>\n                    <div class=\"mt-1\">\n                        <input name=\"email\" type=\"email-address\" autocomplete=\"email-address\" required\n                            class=\"px-2 py-3 mt-1 block w-full rounded-md border border-gray-300 shadow-sm focus:border-sky-500 focus:outline-none focus:ring-sky-500 sm:text-sm\" />\n                    </div>\n                </div>\n\n                <div>\n                    <label for=\"password\" class=\"block text-sm font-medium text-gray-700\">Password</label>\n                    <div class=\"mt-1\">\n                        <input name=\"password\" type=\"password\" autocomplete=\"password\" required\n                            class=\"px-2 py-3 mt-1 block w-full rounded-md border border-gray-300 shadow-sm focus:border-sky-500 focus:outline-none focus:ring-sky-500 sm:text-sm\" />\n                    </div>\n                </div>\n\n                <div>\n                    <label for=\"password\" class=\"block text-sm font-medium text-gray-700\">Confirm Password</label>\n                    <div class=\"mt-1\">\n                        <input name=\"confirm_password\" type=\"password\" autocomplete=\"confirm-password\" required\n                            class=\"px-2 py-3 mt-1 block w-full rounded-md border border-gray-300 shadow-sm focus:border-sky-500 focus:outline-none focus:ring-sky-500 sm:text-sm\" />\n                    </div>\n                </div>\n\n                <div>\n                    <button type=\"submit\"\n                        class=\"flex w-full justify-center rounded-md border border-transparent bg-sky-400 py-2 px-4 text-sm font-medium text-white shadow-sm hover:bg-opacity-75 focus:outline-none focus:ring-2 focus:ring-sky-400 focus:ring-offset-2\">Register\n                        Account\n                        </button>\n                </div>\n            </form>\n        </div>\n    </div>\n</div>"
