    "code": "/**\n * Component: simple form\n * Author: @Aman300 (https://tailwindflex.com/@Aman300)\n * Source: https://tailwindflex.com/@Aman300/simple-form-4\n * Attribution: Créé par @Aman300 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function SimpleForm4() {\n  return (\n    <div>\n    <div className=\"flex justify-center items-center h-screen bg-gray-800\">\n      <div className=\"bg-white w-72 h-80 rounded-3xl shadow-lg\">\n    \n        <form action=\"\">\n    \n          <div className=\"flex justify-center mb-3 mt-10\">\n            <input type=\"text\" name=\"\" id=\"\" className=\"bg-gray-200 px-5 py-3 rounded-xl\" placeholder=\"Name\" />\n          </div>\n          <div className=\"flex justify-center mb-3\">\n            <input type=\"email\" name=\"\" id=\"\" className=\"bg-gray-200 px-5 py-3 rounded-xl\" placeholder=\"Email\" />\n          </div>\n          <div className=\"flex justify-center mb-3\">\n            <input type=\"password\" name=\"\" id=\"\" className=\"bg-gray-200 px-5 py-3 rounded-xl\" placeholder=\"password\" />\n          </div>\n          <div className=\"flex justify-center\">\n           <button className=\"bg-blue-600 rounded-xl w-40 py-2 text-white hover700\">Submit</button>\n          </div>\n        </form>\n        \n      </div>\n    </div>\n    </div>\n  );\n}\n",
