    "license": "MIT",
    "author": "@anonymous",
    "authorUrl": "https://tailwindflex.com/@anonymous",
    "sourceUrl": "https://tailwindflex.com/@anonymous/incentives",
    "mention": "Créé par @anonymous sur TailwindFlex",
    "registryDependencies": [],
    "dependencies": [],
    "code": "/**\n * Component: Incentives\n * Author: @anonymous (https://tailwindflex.com/@anonymous)\n * Source: https://tailwindflex.com/@anonymous/incentives\n * Attribution: Créé par @anonymous sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function Incentives() {\n  return (\n    <div>\n    \n    <div className=\"bg-gray-50\">\n      <div className=\"max-w-7xl mx-auto py-24 sm2 sm32 lg4\">\n        <div className=\"max-w-2xl mx-auto px-4 grid grid-cols-1 gap-y-10 gap-x-8 lg lg3\">\n          <div className=\"text-center sm sm lg lg\">\n            <div className=\"sm0\">\n              <div className=\"flow-root\">\n                <img className=\"w-28 h-24 mx-auto\" src=\"https://tailwindui.com/img/ecommerce/icons/icon-delivery-light.svg\" alt=\"\" />\n              </div>\n            </div>\n            <div className=\"mt-3 sm0 sm3 lg3 lg0\">\n              <h3 className=\"text-sm font-medium text-gray-900\">Free Shipping</h3>\n              <p className=\"mt-2 text-sm text-gray-500\">It&#039;s not actually free we just price it into the products. Someone&#039;s paying for it, and it&#039;s not us.</p>\n            </div>\n          </div>\n    \n          <div className=\"text-center sm sm lg lg\">\n            <div className=\"sm0\">\n              <div className=\"flow-root\">\n                <img className=\"w-28 h-24 mx-auto\" src=\"https://tailwindui.com/img/ecommerce/icons/icon-chat-light.svg\" alt=\"\" />\n              </div>\n            </div>\n            <div className=\"mt-3 sm0 sm3 lg3 lg0\">\n              <h3 className=\"text-sm font-medium text-gray-900\">24/7 Customer Support</h3>\n              <p className=\"mt-2 text-sm text-gray-500\">Our AI chat widget is powered by a naive series of if/else statements. Guaranteed to irritate.</p>\n            </div>\n          </div>\n    \n          <div className=\"text-center sm sm lg lg\">\n            <div className=\"sm0\">\n              <div className=\"flow-root\">\n                <img className=\"w-28 h-24 mx-auto\" src=\"https://tailwindui.com/img/ecommerce/icons/icon-fast-checkout-light.svg\" alt=\"\" />\n              </div>\n            </div>\n            <div className=\"mt-3 sm0 sm3 lg3 lg0\">\n              <h3 className=\"text-sm font-medium text-gray-900\">Fast Shopping Cart</h3>\n              <p className=\"mt-2 text-sm text-gray-500\">Look how fast that cart is going. What does this mean for the actual experience? I don&#039;t know.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<!-- This example requires Tailwind CSS v2.0+ -->\n<div class=\"bg-gray-50\">\n  <div class=\"max-w-7xl mx-auto py-24 sm:px-2 sm:py-32 lg:px-4\">\n    <div class=\"max-w-2xl mx-auto px-4 grid grid-cols-1 gap-y-10 gap-x-8 lg:max-w-none lg:grid-cols-3\">\n      <div class=\"text-center sm:flex sm:text-left lg:block lg:text-center\">\n        <div class=\"sm:flex-shrink-0\">\n          <div class=\"flow-root\">\n            <img class=\"w-28 h-24 mx-auto\" src=\"https://tailwindui.com/img/ecommerce/icons/icon-delivery-light.svg\" alt=\"\">\n          </div>\n        </div>\n        <div class=\"mt-3 sm:mt-0 sm:ml-3 lg:mt-3 lg:ml-0\">\n          <h3 class=\"text-sm font-medium text-gray-900\">Free Shipping</h3>\n          <p class=\"mt-2 text-sm text-gray-500\">It&#039;s not actually free we just price it into the products. Someone&#039;s paying for it, and it&#039;s not us.</p>\n        </div>\n      </div>\n\n      <div class=\"text-center sm:flex sm:text-left lg:block lg:text-center\">\n        <div class=\"sm:flex-shrink-0\">\n          <div class=\"flow-root\">\n            <img class=\"w-28 h-24 mx-auto\" src=\"https://tailwindui.com/img/ecommerce/icons/icon-chat-light.svg\" alt=\"\">\n          </div>\n        </div>\n        <div class=\"mt-3 sm:mt-0 sm:ml-3 lg:mt-3 lg:ml-0\">\n          <h3 class=\"text-sm font-medium text-gray-900\">24/7 Customer Support</h3>\n          <p class=\"mt-2 text-sm text-gray-500\">Our AI chat widget is powered by a naive series of if/else statements. Guaranteed to irritate.</p>\n        </div>\n      </div>\n\n      <div class=\"text-center sm:flex sm:text-left lg:block lg:text-center\">\n        <div class=\"sm:flex-shrink-0\">\n          <div class=\"flow-root\">\n            <img class=\"w-28 h-24 mx-auto\" src=\"https://tailwindui.com/img/ecommerce/icons/icon-fast-checkout-light.svg\" alt=\"\">\n          </div>\n        </div>\n        <div class=\"mt-3 sm:mt-0 sm:ml-3 lg:mt-3 lg:ml-0\">\n          <h3 class=\"text-sm font-medium text-gray-900\">Fast Shopping Cart</h3>\n          <p class=\"mt-2 text-sm text-gray-500\">Look how fast that cart is going. What does this mean for the actual experience? I don&#039;t know.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>"
