    "code": "/**\n * Component: progress-bar with Tailwind CSS and Alpinejs\n * Author: @michael-andreuzza (https://tailwindflex.com/@michael-andreuzza)\n * Source: https://tailwindflex.com/@michael-andreuzza/progress-bar-with-tailwind-css-and-alpinejs\n * Attribution: Créé par @michael-andreuzza sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ProgressBarWithTailwindCssAndAlpinejs() {\n  return (\n    <div dangerouslySetInnerHTML={{ __html: \"\\n<section class=\\\"bg-white\\\"> <div class=\\\"w-full mx-auto max-w-xl flex flex-col lg:h-svh justify-center py-24 lg:py-96 relative p-8\\\"> <div class=\\\"prose text-gray-500 prose-sm prose-headings:font-normal prose-headings:text-xl\\\"> <div> <h1>Progress bar</h1> <p class=\\\"text-balance\\\">A progress that loads when the page loads.</p> </div> </div> <div class=\\\"mt-6 border-t pt-12\\\"> <!-- Starts component --> <div x-data=\\\"{ progress: 0, interval: null }\\\" x-init=\\\"() => { interval = setInterval(() => { progress < 100 ? progress += 5 : clearInterval(interval); }, 100); }\\\" class=\\\"w-full\\\"> <div class=\\\"text-sm text-gray-500\\\" x-text=\\\"progress + '%'\\\">100%</div> <div class=\\\"relative h-1 mt-2 bg-gray-200 rounded-full\\\"> <div x-bind:style=\\\"'width: ' + progress + '%;'\\\" class=\\\"absolute top-0 left-0 h-full bg-orange-500 rounded-full\\\" style=\\\"width: 100%;\\\"></div> </div> </div> <!-- Ends component --> </div> </div> <!-- Starts links to tutorial --> <div class=\\\"pointer-events-none fixed inset-x-0 bottom-0 sm:flex sm:justify-center p-2 \\\"> <div class=\\\"pointer-events-auto flex w-full max-w-md divide-x divide-neutral-200 rounded-lg bg-white shadow-xl border\\\"> <div class=\\\"flex w-0 flex-1 items-center p-4\\\"> <div class=\\\"w-full\\\"> <p class=\\\"text-sm font-medium text-neutral-900\\\">Tutorial</p> <p class=\\\"mt-1 text-sm text-neutral-500\\\">\\nHow to create a progress-bar with Tailwind CSS and Alpinejs\\n</p> <p class=\\\"mt-2 text-xs text-orange-500 underline\\\"> <a href=\\\"https://lexingtonthemes.com\\\"> by © Lexington Themes</a> </p> </div> </div> <div class=\\\"flex\\\"> <div class=\\\"flex flex-col divide-y divide-neutral-200\\\"> <div class=\\\"flex h-0 flex-1\\\"> <a href=\\\"https://lexingtonthemes.com/tutorials/how-to-create-a-progress-bar-with-tailwind-css-and-alpine-js/\\\" type=\\\"button\\\" class=\\\"flex w-full items-center justify-center rounded-none rounded-tr-lg border border-transparent px-4 py-3 text-sm font-medium text-orange-600 hover:text-orange-500 focus:z-10 focus:outline-none focus:ring-2 focus:ring-orange-500\\\">Tutorial</a> </div> <div class=\\\"flex h-0 flex-1\\\"> <a href=\\\"https://github.com/Lexington-Themes/lexington-tutorials/blob/main/src/pages/progress-bar/index.astro\\\" class=\\\"flex w-full items-center justify-center rounded-none rounded-br-lg border border-transparent px-4 py-3 text-sm font-medium text-neutral-700 hover:text-neutral-500 focus:outline-none focus:ring-2 focus:ring-orange-500\\\">Get the code</a> </div> </div> </div> </div> </div> <!-- Ends links to tutorial --> </section>\" }} />\n  );\n}\n",
    "rawHtml": "<script defer src=\"https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js\"></script>\n<section class=\"bg-white\"> <div class=\"w-full mx-auto max-w-xl flex flex-col lg:h-svh justify-center py-24 lg:py-96 relative p-8\"> <div class=\"prose text-gray-500 prose-sm prose-headings:font-normal prose-headings:text-xl\"> <div> <h1>Progress bar</h1> <p class=\"text-balance\">A progress that loads when the page loads.</p> </div> </div> <div class=\"mt-6 border-t pt-12\"> <!-- Starts component --> <div x-data=\"{ progress: 0, interval: null }\" x-init=\"() => { interval = setInterval(() => { progress < 100 ? progress += 5 : clearInterval(interval); }, 100); }\" class=\"w-full\"> <div class=\"text-sm text-gray-500\" x-text=\"progress + '%'\">100%</div> <div class=\"relative h-1 mt-2 bg-gray-200 rounded-full\"> <div x-bind:style=\"'width: ' + progress + '%;'\" class=\"absolute top-0 left-0 h-full bg-orange-500 rounded-full\" style=\"width: 100%;\"></div> </div> </div> <!-- Ends component --> </div> </div> <!-- Starts links to tutorial --> <div class=\"pointer-events-none fixed inset-x-0 bottom-0 sm:flex sm:justify-center p-2 \"> <div class=\"pointer-events-auto flex w-full max-w-md divide-x divide-neutral-200 rounded-lg bg-white shadow-xl border\"> <div class=\"flex w-0 flex-1 items-center p-4\"> <div class=\"w-full\"> <p class=\"text-sm font-medium text-neutral-900\">Tutorial</p> <p class=\"mt-1 text-sm text-neutral-500\">\nHow to create a progress-bar with Tailwind CSS and Alpinejs\n</p> <p class=\"mt-2 text-xs text-orange-500 underline\"> <a href=\"https://lexingtonthemes.com\"> by © Lexington Themes</a> </p> </div> </div> <div class=\"flex\"> <div class=\"flex flex-col divide-y divide-neutral-200\"> <div class=\"flex h-0 flex-1\"> <a href=\"https://lexingtonthemes.com/tutorials/how-to-create-a-progress-bar-with-tailwind-css-and-alpine-js/\" type=\"button\" class=\"flex w-full items-center justify-center rounded-none rounded-tr-lg border border-transparent px-4 py-3 text-sm font-medium text-orange-600 hover:text-orange-500 focus:z-10 focus:outline-none focus:ring-2 focus:ring-orange-500\">Tutorial</a> </div> <div class=\"flex h-0 flex-1\"> <a href=\"https://github.com/Lexington-Themes/lexington-tutorials/blob/main/src/pages/progress-bar/index.astro\" class=\"flex w-full items-center justify-center rounded-none rounded-br-lg border border-transparent px-4 py-3 text-sm font-medium text-neutral-700 hover:text-neutral-500 focus:outline-none focus:ring-2 focus:ring-orange-500\">Get the code</a> </div> </div> </div> </div> </div> <!-- Ends links to tutorial --> </section>"
