    "code": "/**\n * Component: login\n * Author: @mostafa-mohamed-elgdawy (https://tailwindflex.com/@mostafa-mohamed-elgdawy)\n * Source: https://tailwindflex.com/@mostafa-mohamed-elgdawy/login-7\n * Attribution: Créé par @mostafa-mohamed-elgdawy sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function Login7() {\n  return (\n    <div dangerouslySetInnerHTML={{ __html: \"<!DOCTYPE html>\\r\\n<html lang=\\\"en\\\">\\r\\n<head>\\r\\n    <meta charset=\\\"UTF-8\\\">\\r\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\r\\n    <title>Minimalist Login Form</title>\\r\\n    <!-- <link rel=\\\"stylesheet\\\" href=\\\"style.css\\\"> -->\\r\\n     <style>\\r\\n        body {\\r\\n    display: flex;\\r\\n    justify-content: center;\\r\\n    align-items: center;\\r\\n    height: 100vh;\\r\\n    background: #e7edf5;\\r\\n    font-family: Arial, sans-serif;\\r\\n    margin: 0;\\r\\n}\\r\\n.container {\\r\\n    width: 350px;\\r\\n    height: 70vh;\\r\\n    background: white;\\r\\n    border-radius: 15px;\\r\\n    padding: 20px;\\r\\n    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);\\r\\n    text-align: center;\\r\\n}\\r\\n.logo {\\r\\n    width: 80px;\\r\\n    height: 80px;\\r\\n    background: #2c3e73;\\r\\n    border-radius: 50%;\\r\\n    margin: 0 auto 20px;\\r\\n    display: flex;\\r\\n    justify-content: center;\\r\\n    align-items: center;\\r\\n}\\r\\n.input-group {\\r\\n    margin-bottom: 15px;\\r\\n    text-align: left;\\r\\n}\\r\\n.input-group label {\\r\\n    display: block;\\r\\n    font-size: 14px;\\r\\n    color: #333;\\r\\n}\\r\\n.input-group input {\\r\\n    width: 95%;\\r\\n    padding: 10px;\\r\\n    border: 1px solid #ccc;\\r\\n    border-radius: 10px;\\r\\n    outline: none;\\r\\n    font-size: 14px;\\r\\n}\\r\\n.login-btn {\\r\\n    display: block;\\r\\n    width: 95%;\\r\\n    padding: 10px;\\r\\n    background: #2c3e73;\\r\\n    color: white;\\r\\n    text-align: center;\\r\\n    border-radius: 25px;\\r\\n    text-decoration: none;\\r\\n    font-weight: bold;\\r\\n    margin-top: 10px;\\r\\n}\\r\\n.login-btn:hover {\\r\\n    background: #1f2d52;\\r\\n}\\r\\n.footer {\\r\\n    margin-top: 10px;\\r\\n    font-size: 14px;\\r\\n    display: flex;\\r\\n    justify-content: space-between;\\r\\n}\\r\\n.footer a {\\r\\n    text-decoration: none;\\r\\n    color: #2c3e73;\\r\\n}\\r\\n     </style>\\r\\n</head>\\r\\n<body>\\r\\n    <div class=\\\"container\\\">\\r\\n        <div class=\\\"logo\\\">\\r\\n            <span style=\\\"font-size: 40px; color: white;\\\">&#9679;&#9679;&#9679;</span>\\r\\n        </div>\\r\\n        <div class=\\\"input-group\\\">\\r\\n            <label>Email Address</label>\\r\\n            <input type=\\\"email\\\" placeholder=\\\"Username@gmail.com\\\">\\r\\n        </div>\\r\\n        <div class=\\\"input-group\\\">\\r\\n            <label>Password</label>\\r\\n            <input type=\\\"password\\\" placeholder=\\\"●●●●●●●●●●●●●●●●●●●●●●●●●●\\\">\\r\\n        </div>\\r\\n        <a href=\\\"#\\\" class=\\\"login-btn\\\">Login</a>\\r\\n        <div class=\\\"footer\\\">\\r\\n            <a href=\\\"#\\\">Signup</a>\\r\\n            <a href=\\\"#\\\">Forgot Password?</a>\\r\\n        </div>\\r\\n    </div>\\r\\n</body>\\r\\n</html>\" }} />\n  );\n}\n",
    "rawHtml": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Minimalist Login Form</title>\r\n    <!-- <link rel=\"stylesheet\" href=\"style.css\"> -->\r\n     <style>\r\n        body {\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    height: 100vh;\r\n    background: #e7edf5;\r\n    font-family: Arial, sans-serif;\r\n    margin: 0;\r\n}\r\n.container {\r\n    width: 350px;\r\n    height: 70vh;\r\n    background: white;\r\n    border-radius: 15px;\r\n    padding: 20px;\r\n    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);\r\n    text-align: center;\r\n}\r\n.logo {\r\n    width: 80px;\r\n    height: 80px;\r\n    background: #2c3e73;\r\n    border-radius: 50%;\r\n    margin: 0 auto 20px;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n}\r\n.input-group {\r\n    margin-bottom: 15px;\r\n    text-align: left;\r\n}\r\n.input-group label {\r\n    display: block;\r\n    font-size: 14px;\r\n    color: #333;\r\n}\r\n.input-group input {\r\n    width: 95%;\r\n    padding: 10px;\r\n    border: 1px solid #ccc;\r\n    border-radius: 10px;\r\n    outline: none;\r\n    font-size: 14px;\r\n}\r\n.login-btn {\r\n    display: block;\r\n    width: 95%;\r\n    padding: 10px;\r\n    background: #2c3e73;\r\n    color: white;\r\n    text-align: center;\r\n    border-radius: 25px;\r\n    text-decoration: none;\r\n    font-weight: bold;\r\n    margin-top: 10px;\r\n}\r\n.login-btn:hover {\r\n    background: #1f2d52;\r\n}\r\n.footer {\r\n    margin-top: 10px;\r\n    font-size: 14px;\r\n    display: flex;\r\n    justify-content: space-between;\r\n}\r\n.footer a {\r\n    text-decoration: none;\r\n    color: #2c3e73;\r\n}\r\n     </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"logo\">\r\n            <span style=\"font-size: 40px; color: white;\">&#9679;&#9679;&#9679;</span>\r\n        </div>\r\n        <div class=\"input-group\">\r\n            <label>Email Address</label>\r\n            <input type=\"email\" placeholder=\"Username@gmail.com\">\r\n        </div>\r\n        <div class=\"input-group\">\r\n            <label>Password</label>\r\n            <input type=\"password\" placeholder=\"●●●●●●●●●●●●●●●●●●●●●●●●●●\">\r\n        </div>\r\n        <a href=\"#\" class=\"login-btn\">Login</a>\r\n        <div class=\"footer\">\r\n            <a href=\"#\">Signup</a>\r\n            <a href=\"#\">Forgot Password?</a>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>"
