    "code": "/**\n * Component: Button with a gradient border using Tailwind CSS\n * Author: @dipti (https://tailwindflex.com/@dipti)\n * Source: https://tailwindflex.com/@dipti/button-with-a-gradient-border-using-tailwind-css\n * Attribution: Créé par @dipti sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ButtonWithAGradientBorderUsingTailwindCss() {\n  return (\n    <div>\n    <div style=\"max-width: 240px;\"\n        className=\"flex rounded-full mx-auto bg-gradient-to-tr from-red-400 via-orange-400 to-rose-400 p-1 shadow-lg\">\n        <button className=\"flex-1 font-bold text-xl bg-white px-6 py-1 rounded-full\">\n            Welcome\n        </button>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div style=\"max-width: 240px;\"\n    class=\"flex rounded-full mx-auto bg-gradient-to-tr from-red-400 via-orange-400 to-rose-400 p-1 shadow-lg\">\n    <button class=\"flex-1 font-bold text-xl bg-white px-6 py-1 rounded-full\">\n        Welcome\n    </button>\n</div>"
