    "code": "/**\n * Component: Glowing gradient button\n * Author: @entrptaher (https://tailwindflex.com/@entrptaher)\n * Source: https://tailwindflex.com/@entrptaher/glowing-gradient-button\n * Attribution: Créé par @entrptaher sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function GlowingGradientButton() {\n  return (\n    <div>\n    <div className=\"container max-w-full\">\r\n        <div className=\"h-screen bg-black flex flex-wrap content-center justify-evenly\">\r\n            <div className=\"relative inline-flex group\">\r\n                <div\r\n                    className=\"absolute transitiona-all duration-1000 opacity-70 -inset-px bg-gradient-to-r from-[#44BCFF] via-[#FF44EC] to-[#FF675E] blur-lg group-hover100 group-hover1 group-hover200 animate-tilt\">\r\n                </div>\r\n                <a href=\"#\" title=\"Get quote now\"\r\n                    className=\"relative inline-flex items-center justify-center px-8 py-4 text-lg font-bold text-white transition-all duration-200 bg-purple-900 font-pj focus focus2 focus2 focus900\"\r\n                    role=\"button\"> Code Eating Ants\r\n                </a>\r\n            </div>\r\n        </div>\r\n    </div>\n    </div>\n  );\n}\n",
