    "code": "/**\n * Component: Background Gradient Button with Hover Effects\n * Author: @kavita-joshi (https://tailwindflex.com/@kavita-joshi)\n * Source: https://tailwindflex.com/@kavita-joshi/background-gradient-button-with-hover-effects\n * Attribution: Créé par @kavita-joshi sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function BackgroundGradientButtonWithHoverEffects() {\n  return (\n    <div>\n    <div className=\"relative inline-flex group\">\n      <div\n        className=\"absolute transitiona-all duration-1000 opacity-70 -inset-px bg-gradient-to-r from-[#44BCFF] via-[#FF44EC] to-[#FF675E] rounded-xl blur-lg filter group-hover100 group-hover1 group-hover200\">\n      </div>\n      <a href=\"\" target=\"_blank\" title=\"\" role=\"button\"\n        className=\"relative inline-flex items-center justify-center px-5 py-2 text-base font-bold text-white transition-all duration-200 bg-gray-900 border-2 border-transparent focus focus2 focus2 focus900 hover600 rounded\">\n        Learn more\n      </a>\n    </div>\n    </div>\n  );\n}\n",
