    "dependencies": [],
    "code": "/**\n * Component: Animated button with rotating light beam\n * Author: @anonymous (https://tailwindflex.com/@anonymous)\n * Source: https://tailwindflex.com/@anonymous/animated-button-with-rotating-light-beam\n * Attribution: Créé par @anonymous sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function AnimatedButtonWithRotatingLightBeam() {\n  return (\n    <div>\n    <button className=\"group relative cursor-pointer overflow-hidden whitespace-nowrap px-6 py-4 text-white [background(--bg)] [border-radius(--radius)]  transition-all duration-300 hover105 hover[0_0_40px_8px_rgba(62,61,117,0.7)] flex justify-center\" style=\"--spread: 90deg; --shimmer-color: #ffffff; --radius: 100px; --speed: 1.5s; --cut: 0.1em; --bg: radial-gradient(ellipse 80% 50% at 50% 120%,rgba(62, 61, 117),rgba(18, 18, 38));\">\n                <div className=\"absolute inset-0 overflow-hidden\">\n                    <div className=\"absolute inset-[-100%] rotate-gradient\">\n                        <div className=\"absolute inset-0 [background(from_calc(270deg-(var(--spread)*0.5)),transparent_0,hsl(0_0%_100%/1)_var(--spread),transparent_var(--spread))]\"></div>\n                    </div>\n                </div>\n                <div className=\"absolute [background(--bg)] [border-radius(--radius)] [inset(--cut)]\"></div>\n                <span className=\"z-10 w-48 whitespace-pre bg-gradient-to-b from-black from-30% to-gray-300/80 bg-clip-text text-center text-sm font-semibold leading-none tracking-tight text-white\">Try it Out</span>\n    </button>\n    </div>\n  );\n}\n",
    "rawHtml": "<button class=\"group relative cursor-pointer overflow-hidden whitespace-nowrap px-6 py-4 text-white [background:var(--bg)] [border-radius:var(--radius)]  transition-all duration-300 hover:scale-105 hover:shadow-[0_0_40px_8px_rgba(62,61,117,0.7)] flex justify-center\" style=\"--spread: 90deg; --shimmer-color: #ffffff; --radius: 100px; --speed: 1.5s; --cut: 0.1em; --bg: radial-gradient(ellipse 80% 50% at 50% 120%,rgba(62, 61, 117),rgba(18, 18, 38));\">\n            <div class=\"absolute inset-0 overflow-hidden\">\n                <div class=\"absolute inset-[-100%] rotate-gradient\">\n                    <div class=\"absolute inset-0 [background:conic-gradient(from_calc(270deg-(var(--spread)*0.5)),transparent_0,hsl(0_0%_100%/1)_var(--spread),transparent_var(--spread))]\"></div>\n                </div>\n            </div>\n            <div class=\"absolute [background:var(--bg)] [border-radius:var(--radius)] [inset:var(--cut)]\"></div>\n            <span class=\"z-10 w-48 whitespace-pre bg-gradient-to-b from-black from-30% to-gray-300/80 bg-clip-text text-center text-sm font-semibold leading-none tracking-tight text-white\">Try it Out</span>\n</button>"
