    "registryDependencies": [],
    "dependencies": [],
    "code": "/**\n * Component: Dark mode toggle button\n * Author: @nishant-trivedi (https://tailwindflex.com/@nishant-trivedi)\n * Source: https://tailwindflex.com/@nishant-trivedi/dark-mode-toggle-button\n * Attribution: Créé par @nishant-trivedi sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function DarkModeToggleButton() {\n  return (\n    <div>\n    <div className=\"h-screen w-screen flex justify-center items-center dark800\">\n      <button\n            className=\"h-12 w-12 rounded-lg p-2 hover100 dark700\">\n            <svg className=\"fill-violet-700 block dark\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n                <path d=\"M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z\"></path>\n            </svg>\n            <svg className=\"fill-yellow-500 hidden dark\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n                <path\n                    d=\"M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z\"\n                    fillRule=\"evenodd\" clipRule=\"evenodd\"></path>\n            </svg>\n        </button>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"h-screen w-screen flex justify-center items-center dark:bg-gray-800\">\n  <button onclick=\"(() => document.body.classList.toggle('dark'))()\"\n        class=\"h-12 w-12 rounded-lg p-2 hover:bg-gray-100 dark:hover:bg-gray-700\">\n        <svg class=\"fill-violet-700 block dark:hidden\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n            <path d=\"M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z\"></path>\n        </svg>\n        <svg class=\"fill-yellow-500 hidden dark:block\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n            <path\n                d=\"M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z\"\n                fill-rule=\"evenodd\" clip-rule=\"evenodd\"></path>\n        </svg>\n    </button>\n</div>"
