    "code": "/**\n * Component: Button with hover to button shadow\n * Author: @zayedhossain120 (https://tailwindflex.com/@zayedhossain120)\n * Source: https://tailwindflex.com/@zayedhossain120/button-with-hover-to-button-shadow\n * Attribution: Créé par @zayedhossain120 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ButtonWithHoverToButtonShadow() {\n  return (\n    <div>\n    <div className=\"h-screen w-full bg-[#262626] flex items-center justify-center\">\n      <button className=\"h-fit cursor-pointer py-2.5 px-4 rounded-full text-orange-500 border border-orange-500 hover\">\n        Zayed Hossain\n      </button>\n    </div>\n    </div>\n  );\n}\n",
