    "code": "/**\n * Component: Disabled Button &amp; Active Button\n * Author: @dipti (https://tailwindflex.com/@dipti)\n * Source: https://tailwindflex.com/@dipti/disabled-button-active-button\n * Attribution: Créé par @dipti sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function DisabledButtonActiveButton() {\n  return (\n    <div>\n    <div className=\"flex gap-2\">\n      \n      <button className=\"bg-gray-300 px-4 py-2 rounded-md cursor-not-allowed opacity-50\" disabled>\n        Disabled Button\n      </button>\n    \n      \n      <button className=\"bg-green-500 hover700 active800 px-4 py-2 rounded-md text-white\">\n        Active Button\n      </button>\n    \n    </div>\n    </div>\n  );\n}\n",
