    "code": "/**\n * Component: Linkedin login/signup button\n * Author: @shakti (https://tailwindflex.com/@shakti)\n * Source: https://tailwindflex.com/@shakti/linkedin-login-signup-button\n * Attribution: Créé par @shakti sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function LinkedinLoginSignupButton() {\n  return (\n    <div>\n    <button\r\n        className=\"px-4 py-2 border flex gap-2 border-slate-200 rounded-lg text-slate-700 hover400 hover900 hover transition duration-150\">\r\n        <img className=\"w-6 h-6\" src=\"https://www.svgrepo.com/show/475661/linkedin-color.svg\" loading=\"lazy\" alt=\"google logo\" />\r\n        <span className=\"pt-0.5\">Login with Linkedin</span>\r\n    </button>\n    </div>\n  );\n}\n",
    "rawHtml": "<button\r\n    class=\"px-4 py-2 border flex gap-2 border-slate-200 rounded-lg text-slate-700 hover:border-slate-400 hover:text-slate-900 hover:shadow transition duration-150\">\r\n    <img class=\"w-6 h-6\" src=\"https://www.svgrepo.com/show/475661/linkedin-color.svg\" loading=\"lazy\" alt=\"google logo\">\r\n    <span class=\"pt-0.5\">Login with Linkedin</span>\r\n</button>"
