    "code": "/**\n * Component: Hover Button\n * Author: @tofayel-islam (https://tailwindflex.com/@tofayel-islam)\n * Source: https://tailwindflex.com/@tofayel-islam/hover-button\n * Attribution: Créé par @tofayel-islam sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function HoverButton() {\n  return (\n    <div>\n    <a href=\"#_\" className=\"relative inline-flex items-center justify-start py-3 pl-4 pr-12 overflow-hidden font-semibold text-indigo-600 transition-all duration-150 ease-in-out rounded hover10 hover6 bg-gray-50 group\">\n          <span className=\"absolute bottom-0 left-0 w-full h-1 transition-all duration-150 ease-in-out bg-indigo-600 group-hover\"></span>\n          <span className=\"absolute right-0 pr-4 duration-200 ease-out group-hover12\">\n            <svg className=\"w-5 h-5 text-green-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"></path></svg>\n          </span>\n          <span className=\"absolute left-0 pl-2.5 -translate-x-12 group-hover0 ease-out duration-200\">\n            <svg className=\"w-5 h-5 text-green-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"></path></svg>\n          </span>\n          <span className=\"relative w-full text-left transition-colors duration-200 ease-in-out group-hover\">Button Text</span>\n        </a>\n    </div>\n  );\n}\n",
    "rawHtml": "<a href=\"#_\" class=\"relative inline-flex items-center justify-start py-3 pl-4 pr-12 overflow-hidden font-semibold text-indigo-600 transition-all duration-150 ease-in-out rounded hover:pl-10 hover:pr-6 bg-gray-50 group\">\n      <span class=\"absolute bottom-0 left-0 w-full h-1 transition-all duration-150 ease-in-out bg-indigo-600 group-hover:h-full\"></span>\n      <span class=\"absolute right-0 pr-4 duration-200 ease-out group-hover:translate-x-12\">\n        <svg class=\"w-5 h-5 text-green-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"></path></svg>\n      </span>\n      <span class=\"absolute left-0 pl-2.5 -translate-x-12 group-hover:translate-x-0 ease-out duration-200\">\n        <svg class=\"w-5 h-5 text-green-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"></path></svg>\n      </span>\n      <span class=\"relative w-full text-left transition-colors duration-200 ease-in-out group-hover:text-white\">Button Text</span>\n    </a>"
