    "code": "/**\n * Component: Simple Btn\n * Author: @abidullah-786 (https://tailwindflex.com/@abidullah-786)\n * Source: https://tailwindflex.com/@abidullah-786/simple-btn\n * Attribution: Créé par @abidullah-786 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function SimpleBtn() {\n  return (\n    <div>\n    <button type=\"button\" className=\"text-nowrap inline-flex items-center justify-center rounded-md border-2 border-transparent bg-gray-900 bg-none px-12 py-3 text-center text-base font-bold text-white transition-all duration-200 ease-in-out focus hover800\">\n                                        Submit\n                                    </button>\n    </div>\n  );\n}\n",
