    "code": "/**\n * Component: Disabled Button &amp; Active Button\n * Author: @anonymous (https://tailwindflex.com/@anonymous)\n * Source: https://tailwindflex.com/@anonymous/disabled-button-active-button-2\n * Attribution: Créé par @anonymous sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function DisabledButtonActiveButton2() {\n  return (\n    <div>\n    <div className=\"flex gap-2\">\n      \n      <button className=\"bg-gray-300 px-4 py-2 rounded-md opacity-50\" >\n        Disabled Button\n      </button>\n    \n      \n      <button className=\"bg-green-500 hover700 active800 px-4 py-2 rounded-md text-white\">\n        Active Button\n      </button>\n    \n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"flex gap-2\">\n  <!-- HTML -->\n  <button class=\"bg-gray-300 px-4 py-2 rounded-md opacity-50\" >\n    Disabled Button\n  </button>\n\n  <!-- HTML -->\n  <button class=\"bg-green-500 hover:bg-green-700 active:bg-green-800 px-4 py-2 rounded-md text-white\">\n    Active Button\n  </button>\n\n</div>"
