    "code": "/**\n * Component: Button with hover animation\n * Author: @losiol (https://tailwindflex.com/@losiol)\n * Source: https://tailwindflex.com/@losiol/button-with-hover-animation\n * Attribution: Créé par @losiol sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ButtonWithHoverAnimation() {\n  return (\n    <div>\n    <button className=\"inline-block px-7 py-1.5 overflow-hidden text-sm font-semibold transition-transform rounded-full group text text-green-700/70 bg-green-300/30 hover500/70 hover\">\n      <span before=\"Send message\" className=\"relative py-1.5 transition-transform inline-block before[attr(before)] before1.5 before before group-hover\">Send message</span>\n    </button>\n    </div>\n  );\n}\n",
