    "code": "/**\n * Component: 🔥 Sleek &amp; Modern Button with Hover Effect – Tailwind CSS\n * Author: @ahitabisma (https://tailwindflex.com/@ahitabisma)\n * Source: https://tailwindflex.com/@ahitabisma/sleek-modern-button-with-hover-effect-tailwind-css\n * Attribution: Créé par @ahitabisma sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function SleekModernButtonWithHoverEffectTailwindCss() {\n  return (\n    <div>\n    <div className=\"w-svw h-svh flex justify-center items-center\">\n      <button className=\"inline-flex items-center gap-2 transition duration-300 ease-linear \n        bg-[#5751E1] text-white text-lg font-semibold font-['Poppins',sans-serif] leading-[1.12] \n        px-8 py-4 text-center capitalize select-none rounded-full shadow-[4px_6px_0px_0px_#050071] \n        whitespace-nowrap hover[#ffc224] hover\">\n        Button\n    </button>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"w-svw h-svh flex justify-center items-center\">\n  <button class=\"inline-flex items-center gap-2 transition duration-300 ease-linear \n    bg-[#5751E1] text-white text-lg font-semibold font-['Poppins',sans-serif] leading-[1.12] \n    px-8 py-4 text-center capitalize select-none rounded-full shadow-[4px_6px_0px_0px_#050071] \n    whitespace-nowrap hover:bg-[#ffc224] hover:shadow-none\">\n    Button\n</button>\n</div>"
