    "code": "/**\n * Component: Buttons - Htmlwind\n * Author: @htmlwind (https://tailwindflex.com/@htmlwind)\n * Source: https://tailwindflex.com/@htmlwind/buttons-htmlwind\n * Attribution: Créé par @htmlwind sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ButtonsHtmlwind() {\n  return (\n    <div>\n    <div className=\"bg-white py-8\">\n      <div className=\"mx-auto max-w-3xl px-4 flex flex-col items-center gap-y-4 sm sm sm\">\n        \n        <button type=\"button\" className=\"rounded-md bg-pink-500 px-4 py-3 text-base font-semibold text-white shadow-sm hover400 focus-visible focus-visible2 focus-visible2 focus-visible500\">Button text</button>\n        \n        <button type=\"button\" className=\"rounded-md bg-pink-500 px-3.5 py-2.5 text-sm font-semibold text-white shadow-sm hover400 focus-visible focus-visible2 focus-visible2 focus-visible500\">Button text</button>\n        \n        <button type=\"button\" className=\"rounded-md bg-pink-500 px-3 py-2 text-sm font-semibold text-white shadow-sm hover400 focus-visible focus-visible2 focus-visible2 focus-visible500\">Button text</button>\n        \n        <button type=\"button\" className=\"rounded-md bg-pink-500 px-2.5 py-1.5 text-xs font-semibold text-white shadow-sm hover400 focus-visible focus-visible2 focus-visible2 focus-visible500\">Button text</button>\n        \n        <button type=\"button\" className=\"rounded-md bg-pink-500 px-2 py-1 text-xs font-semibold text-white shadow-sm hover400 focus-visible focus-visible2 focus-visible2 focus-visible500\">Button text</button>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"bg-white py-8\">\n  <div class=\"mx-auto max-w-3xl px-4 flex flex-col items-center gap-y-4 sm:flex-row sm:items-center sm:justify-around\">\n    <!-- button-xl -->\n    <button type=\"button\" class=\"rounded-md bg-pink-500 px-4 py-3 text-base font-semibold text-white shadow-sm hover:bg-pink-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink-500\">Button text</button>\n    <!-- button-lg -->\n    <button type=\"button\" class=\"rounded-md bg-pink-500 px-3.5 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-pink-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink-500\">Button text</button>\n    <!-- button-base -->\n    <button type=\"button\" class=\"rounded-md bg-pink-500 px-3 py-2 text-sm font-semibold text-white shadow-sm hover:bg-pink-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink-500\">Button text</button>\n    <!-- button-sm -->\n    <button type=\"button\" class=\"rounded-md bg-pink-500 px-2.5 py-1.5 text-xs font-semibold text-white shadow-sm hover:bg-pink-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink-500\">Button text</button>\n    <!-- button-xs -->\n    <button type=\"button\" class=\"rounded-md bg-pink-500 px-2 py-1 text-xs font-semibold text-white shadow-sm hover:bg-pink-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink-500\">Button text</button>\n  </div>\n</div>"
