    "code": "/**\n * Component: Animated Search bar\n * Author: @muhamad-rufaid-kv (https://tailwindflex.com/@muhamad-rufaid-kv)\n * Source: https://tailwindflex.com/@muhamad-rufaid-kv/animated-search-bar\n * Attribution: Créé par @muhamad-rufaid-kv sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function AnimatedSearchBar() {\n  return (\n    <div>\n    <div className=\"flex items-center flex-col gap-4 justify-center h-screen bg-gray-300\">\r\n      <h1 className=\"font-semibold \">Animated Search Bar</h1>\r\n    \r\n      <div className=\"flex items-center space-x-2 bg-white border border-gray-300 rounded-full px-4 py-2 transition-all duration-300 focus-within2 focus-within400 shadow-md w-72 focus-within96\">\r\n        <input \r\n          type=\"text\" \r\n          placeholder=\"Search...\" \r\n          className=\"flex-grow bg-transparent outline-none text-gray-700 placeholder-gray-400 transition-all duration-300\"\r\n        />\r\n        <button className=\"text-white bg-blue-500 hover600 transition px-2 py-1 rounded-full focus400\">\r\n          🔍\r\n        </button>\r\n      </div>\r\n    \r\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"flex items-center flex-col gap-4 justify-center h-screen bg-gray-300\">\r\n  <h1 class=\"font-semibold \">Animated Search Bar</h1>\r\n\r\n  <div class=\"flex items-center space-x-2 bg-white border border-gray-300 rounded-full px-4 py-2 transition-all duration-300 focus-within:ring-2 focus-within:ring-blue-400 shadow-md w-72 focus-within:w-96\">\r\n    <input \r\n      type=\"text\" \r\n      placeholder=\"Search...\" \r\n      class=\"flex-grow bg-transparent outline-none text-gray-700 placeholder-gray-400 transition-all duration-300\"\r\n    />\r\n    <button class=\"text-white bg-blue-500 hover:bg-blue-600 transition px-2 py-1 rounded-full focus:bg-gray-400\">\r\n      🔍\r\n    </button>\r\n  </div>\r\n\r\n</div>"
