    "code": "/**\n * Component: button-neon-purple-super\n * Author: @mohammad-rashel (https://tailwindflex.com/@mohammad-rashel)\n * Source: https://tailwindflex.com/@mohammad-rashel/button-neon-purple-super\n * Attribution: Créé par @mohammad-rashel sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ButtonNeonPurpleSuper() {\n  return (\n    <div>\n    <button>\n      I love Islam\n    </button>\n    </div>\n  );\n}\n",
