    "code": "/**\n * Component: Card grid\n * Author: @leon-bachmann (https://tailwindflex.com/@leon-bachmann)\n * Source: https://tailwindflex.com/@leon-bachmann/card-grid\n * Attribution: Créé par @leon-bachmann sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function CardGrid() {\n  return (\n    <div>\n    <div className=\"p-5 pt-8 border ignore border-gray-200 not-prose dark800 relative bg-gray-50 dark800\">\n        <div\n            className=\"absolute w-auto rounded-b-lg border-b uppercase -translate-y-px tracking-wide leading-none border-l border-r border-gray-200 dark800 shadow-sm top-0 left-1/2 -translate-x-1/2 px-3 pt-1 pb-2 bg-white dark text-gray-400 text-[0.65rem]\">\n            🤩 Our Amazing Sponsors 👇</div>\n        <div className=\"max-w-5xl mx-auto\">\n            <div className=\"max-w-7xl mx-auto grid grid-cols-1 sm2 lg3  gap-3 sm5 not-prose\">\n                <a href=\"#\" target=\"_blank\"\n                    className=\"relative flex flex-col items-start justify-between p-6 overflow-hidden rounded-xl border border-gray-200 dark800 dark bg-white group\">\n                    <span className=\"absolute w-full h-full bg-white dark inset-0 dark900 group-hover50 group-hover30\"></span>\n                    <div className=\"flex items-center justify-between w-full mb-4 \">\n                        <img src=\"https://cdn.devdojo.com/sponsors/digital-ocean.svg\" alt=\"DigitalOcean\" className=\"relative h-5 md6\" />\n                        <span className=\"opacity-0 -translate-x-2 flex-shrink-0 group-hover0 py-1 px-2.5 text-[0.6rem] group-hover100 transition-all ease-out duration-200 rounded-full bg-blue-50 dark500 dark text-blue-500 flex items-center justify-center\">\n                            <span>View Website</span>\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\" fill=\"currentColor\"\n                            className=\"w-3 translate-x-0.5 h-3\">\n                            <path fillRule=\"evenodd\"\n                                d=\"M7.21 14.77a.75.75 0 01.02-1.06L11.168 10 7.23 6.29a.75.75 0 111.04-1.08l4.5 4.25a.75.75 0 010 1.08l-4.5 4.25a.75.75 0 01-1.06-.02z\"\n                                clipRule=\"evenodd\"></path>\n                        </svg>\n                        </span>\n                    </div>\n                    <span className=\"relative text-xs md text-gray-600 dark400\">DigitalOcean offers a simple and reliable cloud hosting solution that enables developers to get their website or application up and running quickly.</span>\n                </a>\n                <a href=\"#\" target=\"_blank\"\n                    className=\"relative flex flex-col items-start justify-between p-6 overflow-hidden rounded-xl border border-gray-200 dark800 dark bg-white group\">\n                    <span className=\"absolute w-full h-full bg-white dark inset-0 dark900 group-hover50 group-hover30\"></span>\n                    <div className=\"flex items-center justify-between w-full mb-4 \">\n                        <img src=\"https://cdn.devdojo.com/sponsors/larajobs.svg\" alt=\"Larajobs\" className=\"relative h-5 md6\" />\n                        <span className=\"opacity-0 -translate-x-2 flex-shrink-0 group-hover0 py-1 px-2.5 text-[0.6rem] group-hover100 transition-all ease-out duration-200 rounded-full bg-blue-50 dark500 dark text-blue-500 flex items-center justify-center\">\n                            <span>View Website</span>\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\" fill=\"currentColor\"\n                            className=\"w-3 translate-x-0.5 h-3\">\n                            <path fillRule=\"evenodd\"\n                                d=\"M7.21 14.77a.75.75 0 01.02-1.06L11.168 10 7.23 6.29a.75.75 0 111.04-1.08l4.5 4.25a.75.75 0 010 1.08l-4.5 4.25a.75.75 0 01-1.06-.02z\"\n                                clipRule=\"evenodd\"></path>\n                        </svg>\n                        </span>\n                    </div>\n                    <span className=\"relative text-xs md text-gray-600 dark400\">The official Laravel job board. Find the best and most talented Laravel developers by posting your job on the official Laravel job board.</span>\n                </a>\n                <a href=\"#\" target=\"_blank\"\n                    className=\"relative flex flex-col items-start justify-between p-6 overflow-hidden rounded-xl border border-gray-200 dark800 dark bg-white group\">\n                    <span className=\"absolute w-full h-full bg-white dark inset-0 dark900 group-hover50 group-hover30\"></span>\n                    <div className=\"flex items-center justify-between w-full mb-4 \">\n                        <img src=\"https://cdn.devdojo.com/sponsors/coin-camp.svg\" alt=\"CoinCamp\" className=\"relative h-5 md6\" />\n                        <span className=\"opacity-0 -translate-x-2 flex-shrink-0 group-hover0 py-1 px-2.5 text-[0.6rem] group-hover100 transition-all ease-out duration-200 rounded-full bg-blue-50 dark500 dark text-blue-500 flex items-center justify-center\">\n                            <span>View Website</span>\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 20 20\" fill=\"currentColor\"\n                            className=\"w-3 translate-x-0.5 h-3\">\n                            <path fillRule=\"evenodd\"\n                                d=\"M7.21 14.77a.75.75 0 01.02-1.06L11.168 10 7.23 6.29a.75.75 0 111.04-1.08l4.5 4.25a.75.75 0 010 1.08l-4.5 4.25a.75.75 0 01-1.06-.02z\"\n                                clipRule=\"evenodd\"></path>\n                        </svg>\n                        </span>\n                    </div>\n                    <span className=\"relative text-xs md text-gray-600 dark400\">Learn how to code your own blockchain and create your own crypto-currency with the CoinCamp interactive and fun online training platform.</span>\n                </a>\n            </div>\n        </div>\n    </div>\n    </div>\n  );\n}\n",
