    "license": "MIT",
    "author": "@bonheur-developer1",
    "authorUrl": "https://tailwindflex.com/@bonheur-developer1",
    "sourceUrl": "https://tailwindflex.com/@bonheur-developer1/an-off-line-game-of-catching-afox",
    "mention": "Créé par @bonheur-developer1 sur TailwindFlex",
    "registryDependencies": [],
