    "code": "/**\n * Component: Call to action (CTA) section\n * Author: @bunny (https://tailwindflex.com/@bunny)\n * Source: https://tailwindflex.com/@bunny/call-to-action-cta-section\n * Attribution: Créé par @bunny sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function CallToActionCtaSection() {\n  return (\n    <div>\n    <section className=\"bg-blue-600 py-16 text-white\">\n            <div className=\"container mx-auto px-4 text-center\">\n                <h2 className=\"text-3xl md4xl font-bold mb-6\">Ready to Get Started?</h2>\n                <p className=\"text-lg md mb-8\">Sign up now and start using our awesome product.</p>\n                <a href=\"#\" className=\"px-6 py-3 bg-white text-blue-600 rounded-lg font-bold shadow-md hover50\">Sign Up\n                    Now</a>\n            </div>\n        </section>\n    </div>\n  );\n}\n",
