    "code": "/**\n * Component: CTA banner\n * Author: @anonymous (https://tailwindflex.com/@anonymous)\n * Source: https://tailwindflex.com/@anonymous/cta-banner\n * Attribution: Créé par @anonymous sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function CtaBanner() {\n  return (\n    <div>\n    <section className=\"bg-black overflow-visible my-0 py-24 mt-24\">\n      <div className=\"text-white items-center text-center flex flex-col\">\n        <h2 className=\"font-bold text-2xl lg4xl\">Embark on an Adventure</h2>\n        <p className=\"mx-auto mt-6 max-w-xl text-lg md leading-8 text-slate-400\">\n          Take a thrilling journey through our product's features. Book an adventurous demo and discover endless\n          possibilities.\n        </p>\n        <a className=\"mt-8 rounded-md bg-white px-5 py-2.5 text-base font-semibold leading-7 text-black hover200 transition focus focus focus300\"\n          href=\"#\">Claim Your 15% off Adventure! Start Now</a>\n      </div>\n    </section>\n    </div>\n  );\n}\n",
    "rawHtml": "<section class=\"bg-black overflow-visible my-0 py-24 mt-24\">\n  <div class=\"text-white items-center text-center flex flex-col\">\n    <h2 class=\"font-bold text-2xl lg:text-4xl\">Embark on an Adventure</h2>\n    <p class=\"mx-auto mt-6 max-w-xl text-lg md:text-xl leading-8 text-slate-400\">\n      Take a thrilling journey through our product's features. Book an adventurous demo and discover endless\n      possibilities.\n    </p>\n    <a class=\"mt-8 rounded-md bg-white px-5 py-2.5 text-base font-semibold leading-7 text-black hover:bg-gray-200 transition focus:outline-none focus:ring focus:border-blue-300\"\n      href=\"#\">Claim Your 15% off Adventure! Start Now</a>\n  </div>\n</section>"
