    "code": "/**\n * Component: Responsive CTA\n * Author: @dika99 (https://tailwindflex.com/@dika99)\n * Source: https://tailwindflex.com/@dika99/responsive-cta-2\n * Attribution: Créé par @dika99 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ResponsiveCta2() {\n  return (\n    <div>\n    <section className=\"w-full max-w-5xl bg-[#1A202C]/70 lg mx-auto py-14 lg20 px-5 lg0\">\n      <div className=\"rounded-2xl mx-auto flex flex-col gap-y-5 justify-center items-center\">\n        <h3 className=\"text-3xl md4xl lg5xl max-w-xl lg3xl mx-auto font-bold text-white text-center\">Harnessing Solar Energy for a Sustainable Future</h3>\n        <p className=\"text-sm text-white max-w-lg mx-auto text-center\">Join us in our mission to harness the boundless power of the sun. Our state-of-the-art solar plant is revolutionizing energy production, providing clean and renewable electricity to power communities.</p>\n        <button className=\"bg-[#45B3BA] dark[#1A202C] w-1/2 md1/3 hover border border-transparent hover transition duration-200 lg1/3 text-white font-semibold text-sm lg rounded px-4 py-2\">Register for free</button>\n      </div>\n    </section>\n    </div>\n  );\n}\n",
    "rawHtml": "<section class=\"w-full max-w-5xl bg-[#1A202C]/70 lg:rounded-lg mx-auto py-14 lg:pb-20 px-5 lg:px-0\">\n  <div class=\"rounded-2xl mx-auto flex flex-col gap-y-5 justify-center items-center\">\n    <h3 class=\"text-3xl md:text-4xl lg:text-5xl max-w-xl lg:max-w-3xl mx-auto font-bold text-white text-center\">Harnessing Solar Energy for a Sustainable Future</h3>\n    <p class=\"text-sm text-white max-w-lg mx-auto text-center\">Join us in our mission to harness the boundless power of the sun. Our state-of-the-art solar plant is revolutionizing energy production, providing clean and renewable electricity to power communities.</p>\n    <button class=\"bg-[#45B3BA] dark:bg-[#1A202C] w-1/2 md:w-1/3 hover:shadow-lg border border-transparent hover:drop-shadow transition duration-200 lg:w-1/3 text-white font-semibold text-sm lg:text-base rounded px-4 py-2\">Register for free</button>\n  </div>\n</section>"
