    "code": "/**\n * Component: Call to Action (CTA with Background Image)\n * Author: @eliyantosarage (https://tailwindflex.com/@eliyantosarage)\n * Source: https://tailwindflex.com/@eliyantosarage/call-to-action-cta-with-background-image\n * Attribution: Créé par @eliyantosarage sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function CallToActionCtaWithBackgroundImage() {\n  return (\n    <div>\n    <body className=\"flex items-center justify-center min-h-screen bg-gray-900\">\n        <div className=\"relative w-full h-full bg-cover bg-center flex items-center justify-center bg-cover bg-center p-8 my-8 dui-bg-fixed\"\n            style=\"background-image: url('https://images.unsplash.com/photo-1477346611705-65d1883cee1e?ixlib=rb-4.0.3&q=85&fm=jpg&crop=entropy&cs=srgb&w=2400');\">\n            <div\n                className=\"p-8 bg-gray-900 bg-opacity-50 text-white/75 rounded-xl shadow-lg text-center w-full max-w-full mx-2\">\n                <h1 className=\"text-4xl font-bold mb-4\">Call to Action (CTA)</h1>\n                <p className=\"text-lg mb-8\">Jadilah bagian dari komunitas kami dan nikmati manfaat eksklusif.</p>\n                <a href=\"https://github.com/idugeni\" target=\"_blank\" rel=\"noopener noreferrer\"\n                    className=\"btn btn-neutral btn-wide\">Daftar Sekarang</a>\n            </div>\n        </div>\n    </body>\n    </div>\n  );\n}\n",
    "rawHtml": "<body class=\"flex items-center justify-center min-h-screen bg-gray-900\">\n    <div class=\"relative w-full h-full bg-cover bg-center flex items-center justify-center bg-cover bg-center p-8 my-8 dui-bg-fixed\"\n        style=\"background-image: url('https://images.unsplash.com/photo-1477346611705-65d1883cee1e?ixlib=rb-4.0.3&q=85&fm=jpg&crop=entropy&cs=srgb&w=2400');\">\n        <div\n            class=\"p-8 bg-gray-900 bg-opacity-50 text-white/75 rounded-xl shadow-lg text-center w-full max-w-full mx-2\">\n            <h1 class=\"text-4xl font-bold mb-4\">Call to Action (CTA)</h1>\n            <p class=\"text-lg mb-8\">Jadilah bagian dari komunitas kami dan nikmati manfaat eksklusif.</p>\n            <a href=\"https://github.com/idugeni\" target=\"_blank\" rel=\"noopener noreferrer\"\n                class=\"btn btn-neutral btn-wide\">Daftar Sekarang</a>\n        </div>\n    </div>\n</body>"
