    "code": "/**\n * Component: Boost Your Business with a Stunning Website!\n * Author: @vikas-kushwah (https://tailwindflex.com/@vikas-kushwah)\n * Source: https://tailwindflex.com/@vikas-kushwah/boost-your-business-with-a-stunning-website\n * Attribution: Créé par @vikas-kushwah sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function BoostYourBusinessWithAStunningWebsite() {\n  return (\n    <div>\n    <main className=\"h-screen my-10\">\n          <section className=\"bg-gradient-to-r from-[#75723E] to-[#A06C5D]  text-white  flex justify-center items-center px-6 text-center py-20\">\n            <div className=\" max-w-3xl mx-auto\">\n              <h2 className=\"text-3xl md4xl font-bold mb-4\">\n                Transform Your Online Presence Today!\n              </h2>\n              <p className=\"text-lg md md20 pb-10\">\n                Get a high-performing, visually stunning website tailored for your business needs.\n              </p>\n              <a\n                href=\"/contact\"\n                className=\"bg-white  text-[#75723E] hover200 text-lg font-semibold py-3 px-6 rounded-full shadow-lg transition-all duration-300\"\n              >\n                Get a Free Consultation\n              </a>\n            </div>\n          </section>\n    </main>\n    </div>\n  );\n}\n",
