    "code": "/**\n * Component: Call to Action (CTA) Section\n * Author: @ariaw (https://tailwindflex.com/@ariaw)\n * Source: https://tailwindflex.com/@ariaw/call-to-action-cta-section-2\n * Attribution: Créé par @ariaw sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function CallToActionCtaSection2() {\n  return (\n    <div>\n    <section className=\"bg-gradient-to-r from-blue-600 to-blue-800 text-white py-16 px-4\">\n      <div className=\"container mx-auto max-w-4xl text-center\">\n        <h2 className=\"text-3xl md4xl font-bold mb-6\">Ready to transform your business?</h2>\n        <p className=\"text-xl md2xl text-blue-100 mb-10 max-w-3xl mx-auto\">\n          Join thousands of satisfied customers who trust our solutions every day.\n        </p>\n        \n        <div className=\"flex flex-col sm justify-center gap-4\">\n          <a href=\"#\" className=\"bg-white text-blue-700 hover50 px-8 py-4 rounded-lg font-semibold text-lg transition duration-300 transform hover105 shadow-lg\">\n            Get Started Now\n          </a>\n          <a href=\"#\" className=\"border-2 border-white text-white hover hover700 px-8 py-4 rounded-lg font-semibold text-lg transition duration-300 transform hover105\">\n            Schedule a Demo\n          </a>\n        </div>\n        \n    <div className=\"mt-12 flex flex-col sm items-center justify-center sm4 space-y-4 sm0\">\n      <div className=\"flex -space-x-2\">\n        <img className=\"h-10 w-10 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/women/12.jpg\" alt=\"Customer\" />\n        <img className=\"h-10 w-10 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/men/43.jpg\" alt=\"Customer\" />\n        <img className=\"h-10 w-10 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/women/34.jpg\" alt=\"Customer\" />\n      </div>\n      <div className=\"text-center sm\">\n        <p className=\"text-sm text-blue-200\">Trusted by 10,000+ businesses</p>\n        <div className=\"flex items-center justify-center sm\">\n          <svg className=\"h-5 w-5 text-yellow-400\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n            <path d=\"M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z\" />\n          </svg>\n          <span className=\"ml-2 text-white font-medium\">4.9/5 from 500+ reviews</span>\n        </div>\n      </div>\n    </div>\n      </div>\n    </section>\n    </div>\n  );\n}\n",
    "rawHtml": "<section class=\"bg-gradient-to-r from-blue-600 to-blue-800 text-white py-16 px-4\">\n  <div class=\"container mx-auto max-w-4xl text-center\">\n    <h2 class=\"text-3xl md:text-4xl font-bold mb-6\">Ready to transform your business?</h2>\n    <p class=\"text-xl md:text-2xl text-blue-100 mb-10 max-w-3xl mx-auto\">\n      Join thousands of satisfied customers who trust our solutions every day.\n    </p>\n    \n    <div class=\"flex flex-col sm:flex-row justify-center gap-4\">\n      <a href=\"#\" class=\"bg-white text-blue-700 hover:bg-blue-50 px-8 py-4 rounded-lg font-semibold text-lg transition duration-300 transform hover:scale-105 shadow-lg\">\n        Get Started Now\n      </a>\n      <a href=\"#\" class=\"border-2 border-white text-white hover:bg-white hover:text-blue-700 px-8 py-4 rounded-lg font-semibold text-lg transition duration-300 transform hover:scale-105\">\n        Schedule a Demo\n      </a>\n    </div>\n    \n<div class=\"mt-12 flex flex-col sm:flex-row items-center justify-center sm:space-x-4 space-y-4 sm:space-y-0\">\n  <div class=\"flex -space-x-2\">\n    <img class=\"h-10 w-10 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/women/12.jpg\" alt=\"Customer\">\n    <img class=\"h-10 w-10 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/men/43.jpg\" alt=\"Customer\">\n    <img class=\"h-10 w-10 rounded-full border-2 border-white\" src=\"https://randomuser.me/api/portraits/women/34.jpg\" alt=\"Customer\">\n  </div>\n  <div class=\"text-center sm:text-left\">\n    <p class=\"text-sm text-blue-200\">Trusted by 10,000+ businesses</p>\n    <div class=\"flex items-center justify-center sm:justify-start\">\n      <svg class=\"h-5 w-5 text-yellow-400\" fill=\"currentColor\" viewBox=\"0 0 20 20\">\n        <path d=\"M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z\" />\n      </svg>\n      <span class=\"ml-2 text-white font-medium\">4.9/5 from 500+ reviews</span>\n    </div>\n  </div>\n</div>\n  </div>\n</section>"
