    "code": "/**\n * Component: Call to Action\n * Author: @abdul-baset-bappy (https://tailwindflex.com/@abdul-baset-bappy)\n * Source: https://tailwindflex.com/@abdul-baset-bappy/call-to-action-12\n * Attribution: Créé par @abdul-baset-bappy sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function CallToAction12() {\n  return (\n    <div>\n    <section className=\"py-10 bg-gray-100 sm16 lg24\">\n        <div className=\"px-4 mx-auto sm6 lg8 max-w-7xl\">\n            <div className=\"text-center\">\n                <h2 className=\"text-3xl font-bold leading-tight text-black sm4xl lg5xl\">Get full access to Celebration</h2>\n                <p className=\"mt-4 text-2xl font-medium\">130+ Hand Crafted Coded Blocks</p>\n    \n                <div className=\"flex flex-col items-center justify-center px-16 mt-8 space-y-4 sm0 sm4 sm lg12 sm0\">\n                    <a href=\"#\" title=\"\" className=\"inline-flex items-center justify-center w-full px-8 py-4 text-base font-semibold text-white transition-all duration-200 bg-blue-600 border border-transparent rounded-md sm hover700 focus700\" role=\"button\"> Try For Free </a>\n    \n                    <a href=\"#\" title=\"\" className=\"inline-flex items-center justify-center w-full px-8 py-4 text-base font-semibold text-black transition-all duration-200 bg-transparent border border-black rounded-md sm hover hover focus focus\" role=\"button\">\n                        <svg className=\"w-5 h-5 mr-2 -ml-1\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\n                            <path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth=\"2\" d=\"M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z\" />\n                        </svg>\n                        Contact Sales\n                    </a>\n                </div>\n    \n                <p className=\"mt-6 text-base text-black\">Already have an account? <a href=\"#\" title=\"\" className=\"text-blue-600 transition-all duration-200 hover700 focus700 hover\">Log in</a></p>\n            </div>\n        </div>\n    </section>\n    </div>\n  );\n}\n",
    "rawHtml": "<section class=\"py-10 bg-gray-100 sm:py-16 lg:py-24\">\n    <div class=\"px-4 mx-auto sm:px-6 lg:px-8 max-w-7xl\">\n        <div class=\"text-center\">\n            <h2 class=\"text-3xl font-bold leading-tight text-black sm:text-4xl lg:text-5xl\">Get full access to Celebration</h2>\n            <p class=\"mt-4 text-2xl font-medium\">130+ Hand Crafted Coded Blocks</p>\n\n            <div class=\"flex flex-col items-center justify-center px-16 mt-8 space-y-4 sm:space-y-0 sm:space-x-4 sm:flex-row lg:mt-12 sm:px-0\">\n                <a href=\"#\" title=\"\" class=\"inline-flex items-center justify-center w-full px-8 py-4 text-base font-semibold text-white transition-all duration-200 bg-blue-600 border border-transparent rounded-md sm:w-auto hover:bg-blue-700 focus:bg-blue-700\" role=\"button\"> Try For Free </a>\n\n                <a href=\"#\" title=\"\" class=\"inline-flex items-center justify-center w-full px-8 py-4 text-base font-semibold text-black transition-all duration-200 bg-transparent border border-black rounded-md sm:w-auto hover:bg-black hover:text-white focus:bg-black focus:text-white\" role=\"button\">\n                    <svg class=\"w-5 h-5 mr-2 -ml-1\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\n                        <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z\" />\n                    </svg>\n                    Contact Sales\n                </a>\n            </div>\n\n            <p class=\"mt-6 text-base text-black\">Already have an account? <a href=\"#\" title=\"\" class=\"text-blue-600 transition-all duration-200 hover:text-blue-700 focus:text-blue-700 hover:underline\">Log in</a></p>\n        </div>\n    </div>\n</section>"
