    "rawHtml": "<nav class=\"bg-red-100 py-4 px-2 flex justify-between\">\n  <div>\n    <button class=\"bg-white rounded shadow-md px-2 py-1\">\n      Login\n    </button>\n    <button class=\"bg-white rounded shadow-md px-2 py-1\">\n      Register\n    </button>\n  </div>\n\n  <h1 class=\"text-3xl\">\n    Logo\n  </h1>\n  \n  <ul class=\"list-style-none flex pl-4\">  \n    <li class=\"bg-gray-600 px-2 py-1 mx-2 rounded shadow-sm\">\n      <a href=\"#\" class=\"text-blue-100 hover:text-blue-100 transition-all duration-150\">Home</a>\n    </li>\n    <li class=\"bg-gray-600 px-2 py-1 mx-2 rounded shadow-sm\">\n      <a href=\"#\" class=\"text-blue-100 hover:text-blue-100 transition-all duration-150\">About</a>\n    </li>\n    <li class=\"bg-gray-600 px-2 py-1 mx-2 rounded shadow-sm\">\n      <a href=\"#\" class=\"text-blue-100 hover:text-blue-100 transition-all duration-150\">Contact</a>\n    </li>\n  </ul>\n</nav>"
