    "rawHtml": "<!DOCTYPE html>\n<html lang=\"en\">\n\n<body>\n    <!-- Sticky Navbar with Dropdown -->\n    <nav class=\"bg-white shadow-lg fixed w-full z-10\">\n        <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n            <div class=\"flex justify-between h-16\">\n                <div class=\"flex items-center\">\n                    <a href=\"#\" class=\"flex-shrink-0 flex items-center\">\n                        <img class=\"h-8 w-auto\" src=\"https://tailwindflex.com/images/logo.svg\" alt=\"Logo\">\n                        <span class=\"ml-2 text-xl font-bold text-gray-800\">Company</span>\n                    </a>\n                    <div class=\"hidden md:ml-6 md:flex md:space-x-8\">\n                        <a href=\"#\" class=\"border-indigo-500 text-gray-900 inline-flex items-center px-1 pt-1 border-b-2 text-sm font-medium\">\n                            Home\n                        </a>\n                        <a href=\"#\" class=\"border-transparent text-gray-500 hover:border-gray-300 hover:text-gray-700 inline-flex items-center px-1 pt-1 border-b-2 text-sm font-medium\">\n                            About\n                        </a>\n                        <a href=\"#\" class=\"border-transparent text-gray-500 hover:border-gray-300 hover:text-gray-700 inline-flex items-center px-1 pt-1 border-b-2 text-sm font-medium\">\n                            Services\n                        </a>\n                        <a href=\"#\" class=\"border-transparent text-gray-500 hover:border-gray-300 hover:text-gray-700 inline-flex items-center px-1 pt-1 border-b-2 text-sm font-medium\">\n                            Contact\n                        </a>\n                    </div>\n                </div>\n                <div class=\"flex items-center\">\n                    <div class=\"hidden md:ml-4 md:flex md:items-center\">\n                        <button class=\"bg-indigo-600 px-4 py-2 rounded-md text-white text-sm font-medium hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500\">\n                            Sign Up\n                        </button>\n                    </div>\n                    <div class=\"flex items-center md:hidden\">\n                        <button type=\"button\" class=\"inline-flex items-center justify-center p-2 rounded-md text-gray-400 hover:text-gray-500 hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-indigo-500\" aria-expanded=\"false\">\n                            <span class=\"sr-only\">Open main menu</span>\n                            <svg class=\"block h-6 w-6\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" aria-hidden=\"true\">\n                                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\" />\n                            </svg>\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n        \n        <!-- Mobile menu, show/hide based on menu state -->\n        <div class=\"md:hidden hidden\" id=\"mobile-menu\">\n            <div class=\"pt-2 pb-3 space-y-1\">\n                <a href=\"#\" class=\"bg-indigo-50 border-indigo-500 text-indigo-700 block pl-3 pr-4 py-2 border-l-4 text-base font-medium\">\n                    Home\n                </a>\n                <a href=\"#\" class=\"border-transparent text-gray-500 hover:bg-gray-50 hover:border-gray-300 hover:text-gray-700 block pl-3 pr-4 py-2 border-l-4 text-base font-medium\">\n                    About\n                </a>\n                <a href=\"#\" class=\"border-transparent text-gray-500 hover:bg-gray-50 hover:border-gray-300 hover:text-gray-700 block pl-3 pr-4 py-2 border-l-4 text-base font-medium\">\n                    Services\n                </a>\n                <a href=\"#\" class=\"border-transparent text-gray-500 hover:bg-gray-50 hover:border-gray-300 hover:text-gray-700 block pl-3 pr-4 py-2 border-l-4 text-base font-medium\">\n                    Contact\n                </a>\n            </div>\n            <div class=\"pt-4 pb-3 border-t border-gray-200\">\n                <div class=\"flex items-center px-4\">\n                    <button class=\"w-full bg-indigo-600 px-4 py-2 rounded-md text-white text-sm font-medium hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500\">\n                        Sign Up\n                    </button>\n                </div>\n            </div>\n        </div>\n    </nav>\n\n    <!-- Page content -->\n    <div class=\"pt-16\">\n        <div class=\"max-w-7xl mx-auto py-6 sm:px-6 lg:px-8\">\n            <div class=\"px-4 py-6 sm:px-0\">\n                <div class=\"border-4 border-dashed border-gray-200 rounded-lg h-96 flex items-center justify-center\">\n                    <p class=\"text-gray-500 text-xl\">Page Content Goes Here</p>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        // Simple toggle for mobile menu\n        document.querySelector('button[aria-expanded]').addEventListener('click', function() {\n            const mobileMenu = document.getElementById('mobile-menu');\n            const isExpanded = this.getAttribute('aria-expanded') === 'true';\n            this.setAttribute('aria-expanded', !isExpanded);\n            mobileMenu.classList.toggle('hidden');\n        });\n    </script>\n</body>\n</html>"
