    "code": "/**\n * Component: Hero\n * Author: @hasan (https://tailwindflex.com/@hasan)\n * Source: https://tailwindflex.com/@hasan/hero\n * Attribution: Créé par @hasan sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function Hero() {\n  return (\n    <div>\n    <div>\n      <div className=\"flex h-screen items-center justify-center bg-gray-900 p-5\">\n        <div className=\"grid md2 grid-cols-1 items-center gap-10 md10\">\n          <div>\n            <h1 className=\"mb-2 text-3xl font-bold text-white\"><span className=\"text-green-500\">Hi,</span> I'm Full Stack Developer</h1>\n            <p className=\"mb-6 text-white\">Lorem ipsum dolor sit, amet consectetur adipisicing elit. Aut excepturi magnam enim officiis facilis numquam corporis quos accusantium tempora, dolores quod cum facere architecto soluta atque corrupti a alias perferendis.</p>\n            <div className=\"flex justify-center space-x-5\">\n              <button className=\"flex w-full items-center justify-center gap-1 rounded-2xl bg-rose-500 p-5 py-3 font-semibold text-white hover700\">\n                Follow\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" strokeWidth=\"1.5\" stroke=\"currentColor\" className=\"h-6 w-6\">\n                  <path strokeLinecap=\"round\" strokeLinejoin=\"round\" d=\"M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12Z\" />\n                </svg>\n              </button>\n              <button className=\"flex w-full items-center justify-center gap-2 rounded-2xl bg-white p-5 py-3 font-semibold\">\n                Resume\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" strokeWidth=\"1.5\" stroke=\"currentColor\" className=\"h-6 w-6\">\n                  <path strokeLinecap=\"round\" strokeLinejoin=\"round\" d=\"m9 12.75 3 3m0 0 3-3m-3 3v-7.5M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z\" />\n                </svg>\n              </button>\n            </div>\n          </div>\n          <div>\n            <img src=\"https://images.pexels.com/photos/415829/pexels-photo-415829.jpeg?auto=compress&cs=tinysrgb&w=600\" alt=\"\" className=\"md96 size-72 rounded-full \" />\n          </div>\n        </div>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
