    "code": "/**\n * Component: Minimalist Lading page\n * Author: @Starboy (https://tailwindflex.com/@Starboy)\n * Source: https://tailwindflex.com/@Starboy/minimalist-lading-page\n * Attribution: Créé par @Starboy sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function MinimalistLadingPage() {\n  return (\n    <div dangerouslySetInnerHTML={{ __html: \"<!DOCTYPE html>\\n<html lang=\\\"es\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Landing Page - Regístrate</title>\\n    \\n    <link href=\\\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;700;900&display=swap\\\" rel=\\\"stylesheet\\\">\\n    \\n    <style>\\n        body { font-family: 'Inter', sans-serif; }\\n    </style>\\n</head>\\n<body class=\\\"antialiased\\\">\\n\\n    <nav class=\\\"absolute top-0 w-full z-20 flex justify-between items-center p-6 md:px-12\\\">\\n        <div class=\\\"text-white font-bold text-xl tracking-tighter\\\">\\n            </div>\\n\\n        <div class=\\\"flex space-x-4\\\">\\n            <a href=\\\"#\\\" class=\\\"bg-white text-emerald-900 px-6 py-2 rounded-full font-semibold text-sm hover:bg-emerald-50 transition shadow-lg\\\">\\n                Registro\\n            </a>\\n            <a href=\\\"#\\\" class=\\\"bg-white text-emerald-900 px-6 py-2 rounded-full font-semibold text-sm hover:bg-emerald-50 transition shadow-lg\\\">\\n                Donaciones\\n            </a>\\n        </div>\\n    </nav>\\n\\n    <section class=\\\"relative h-screen w-full flex items-center justify-center overflow-hidden\\\">\\n        \\n        <div class=\\\"absolute inset-0 z-0\\\">\\n            <img \\n                src=\\\"https://images.unsplash.com/photo-1531482615713-2afd69097998?q=80&w=2070&auto=format&fit=crop\\\" \\n                alt=\\\"Background Team\\\" \\n                class=\\\"w-full h-full object-cover\\\"\\n            >\\n            <div class=\\\"absolute inset-0 bg-gradient-to-b from-emerald-900/80 via-black/60 to-black/80\\\"></div>\\n        </div>\\n\\n        <div class=\\\"relative z-10 text-center px-4 max-w-5xl mx-auto text-white mt-10\\\">\\n            \\n            <p class=\\\"text-emerald-300 font-medium tracking-widest uppercase mb-2 animate-fade-in-down\\\">\\n                ¡Somos 17,899 y contando!\\n            </p>\\n\\n            <h1 class=\\\"text-6xl md:text-8xl font-black tracking-tight mb-4 drop-shadow-xl\\\">\\n                Regístrate\\n            </h1>\\n\\n            <h2 class=\\\"text-2xl md:text-4xl font-bold mb-8 text-gray-100\\\">\\n                LA DECISIÓN ESTÁ EN TUS MANOS\\n            </h2>\\n\\n            <p class=\\\"text-gray-300 text-lg md:text-xl max-w-3xl mx-auto mb-12 leading-relaxed font-light\\\">\\n                Únete a nuestra comunidad global. Tu participación es clave para impulsar el cambio que queremos ver. \\n                No dejes pasar la oportunidad de ser parte de algo más grande.\\n            </p>\\n\\n            <div class=\\\"flex flex-col md:flex-row gap-4 justify-center items-center w-full\\\">\\n                \\n                <button class=\\\"w-full md:w-auto px-8 py-3 bg-transparent border-2 border-white text-white rounded-full font-bold hover:bg-white hover:text-black transition duration-300\\\">\\n                    Iniciar sesión\\n                </button>\\n\\n                <button class=\\\"w-full md:w-auto px-10 py-4 bg-emerald-500 hover:bg-emerald-400 text-white rounded-full font-bold text-lg shadow-lg shadow-emerald-500/30 transform hover:scale-105 transition duration-300\\\">\\n                    Registro\\n                </button>\\n\\n                <button class=\\\"w-full md:w-auto px-8 py-3 bg-white text-gray-900 rounded-full font-bold hover:bg-gray-100 transition duration-300\\\">\\n                    Donaciones\\n                </button>\\n            </div>\\n        </div>\\n    </section>\\n\\n</body>\\n</html>\" }} />\n  );\n}\n",
    "rawHtml": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Landing Page - Regístrate</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;700;900&display=swap\" rel=\"stylesheet\">\n    \n    <style>\n        body { font-family: 'Inter', sans-serif; }\n    </style>\n</head>\n<body class=\"antialiased\">\n\n    <nav class=\"absolute top-0 w-full z-20 flex justify-between items-center p-6 md:px-12\">\n        <div class=\"text-white font-bold text-xl tracking-tighter\">\n            </div>\n\n        <div class=\"flex space-x-4\">\n            <a href=\"#\" class=\"bg-white text-emerald-900 px-6 py-2 rounded-full font-semibold text-sm hover:bg-emerald-50 transition shadow-lg\">\n                Registro\n            </a>\n            <a href=\"#\" class=\"bg-white text-emerald-900 px-6 py-2 rounded-full font-semibold text-sm hover:bg-emerald-50 transition shadow-lg\">\n                Donaciones\n            </a>\n        </div>\n    </nav>\n\n    <section class=\"relative h-screen w-full flex items-center justify-center overflow-hidden\">\n        \n        <div class=\"absolute inset-0 z-0\">\n            <img \n                src=\"https://images.unsplash.com/photo-1531482615713-2afd69097998?q=80&w=2070&auto=format&fit=crop\" \n                alt=\"Background Team\" \n                class=\"w-full h-full object-cover\"\n            >\n            <div class=\"absolute inset-0 bg-gradient-to-b from-emerald-900/80 via-black/60 to-black/80\"></div>\n        </div>\n\n        <div class=\"relative z-10 text-center px-4 max-w-5xl mx-auto text-white mt-10\">\n            \n            <p class=\"text-emerald-300 font-medium tracking-widest uppercase mb-2 animate-fade-in-down\">\n                ¡Somos 17,899 y contando!\n            </p>\n\n            <h1 class=\"text-6xl md:text-8xl font-black tracking-tight mb-4 drop-shadow-xl\">\n                Regístrate\n            </h1>\n\n            <h2 class=\"text-2xl md:text-4xl font-bold mb-8 text-gray-100\">\n                LA DECISIÓN ESTÁ EN TUS MANOS\n            </h2>\n\n            <p class=\"text-gray-300 text-lg md:text-xl max-w-3xl mx-auto mb-12 leading-relaxed font-light\">\n                Únete a nuestra comunidad global. Tu participación es clave para impulsar el cambio que queremos ver. \n                No dejes pasar la oportunidad de ser parte de algo más grande.\n            </p>\n\n            <div class=\"flex flex-col md:flex-row gap-4 justify-center items-center w-full\">\n                \n                <button class=\"w-full md:w-auto px-8 py-3 bg-transparent border-2 border-white text-white rounded-full font-bold hover:bg-white hover:text-black transition duration-300\">\n                    Iniciar sesión\n                </button>\n\n                <button class=\"w-full md:w-auto px-10 py-4 bg-emerald-500 hover:bg-emerald-400 text-white rounded-full font-bold text-lg shadow-lg shadow-emerald-500/30 transform hover:scale-105 transition duration-300\">\n                    Registro\n                </button>\n\n                <button class=\"w-full md:w-auto px-8 py-3 bg-white text-gray-900 rounded-full font-bold hover:bg-gray-100 transition duration-300\">\n                    Donaciones\n                </button>\n            </div>\n        </div>\n    </section>\n\n</body>\n</html>"
