                 <!-- Card 4 -->\\n                    <div class=\\\"min-w-[160px] md:min-w-[180px] group cursor-pointer\\\">\\n                        <div class=\\\"relative w-full aspect-square rounded-md overflow-hidden mb-3 shadow-lg\\\">\\n                            <img src=\\\"https://images.unsplash.com/photo-1514525253440-b393452e8d26?q=80&w=500\\\" class=\\\"w-full h-full object-cover transition group-hover:opacity-70\\\">\\n                            <button class=\\\"absolute bottom-2 right-2 bg-blue-600 rounded-full p-2 shadow-xl opacity-0 group-hover:opacity-100 transform translate-y-2 group-hover:translate-y-0 transition\\\">\\n                                <svg class=\\\"w-5 h-5 text-white fill-current\\\" viewBox=\\\"0 0 24 24\\\"><path d=\\\"M8 5v14l11-7z\\\"/></svg>\\n                            </button>\\n                        </div>\\n                        <h3 class=\\\"font-bold text-sm truncate\\\">Rock Classics</h3>\\n                        <p class=\\\"text-xs text-gray-400 truncate\\\">Queen, AC/DC</p>\\n                    </div>\\n                </div>\\n            </div>\\n\\n            <!-- Section: Albums -->\\n            <div class=\\\"mb-8\\\">\\n                <h2 class=\\\"text-xl font-bold mb-4\\\">Tendances</h2>\\n                <div class=\\\"flex gap-4 overflow-x-auto no-scrollbar pb-4\\\">\\n                     <!-- Card A -->\\n                     <div class=\\\"min-w-[160px] md:min-w-[180px] group cursor-pointer\\\">\\n                        <div class=\\\"relative w-full aspect-square rounded-md overflow-hidden mb-3 shadow-lg\\\">\\n                            <img src=\\\"https://images.unsplash.com/photo-1619983081563-430f63602796?q=80&w=500\\\" class=\\\"w-full h-full object-cover transition group-hover:opacity-70\\\">\\n                        </div>\\n                        <h3 class=\\\"font-bold text-sm truncate\\\">New Wave</h3>\\n                        <p class=\\\"text-xs text-gray-400 truncate\\\">Various Artists</p>\\n                    </div>\\n                     <!-- Card B -->\\n                     <div class=\\\"min-w-[160px] md:min-w-[180px] group cursor-pointer\\\">\\n                        <div class=\\\"relative w-full aspect-square rounded-md overflow-hidden mb-3 shadow-lg\\\">\\n                            <img src=\\\"https://images.unsplash.com/photo-1621360841013-c768371e93cf?q=80&w=500\\\" class=\\\"w-full h-full object-cover transition group-hover:opacity-70\\\">\\n                        </div>\\n                        <h3 class=\\\"font-bold text-sm truncate\\\">Jazz Night</h3>\\n                        <p class=\\\"text-xs text-gray-400 truncate\\\">Smooth Jazz</p>\\n                    </div>\\n                </div>\\n            </div>\\n\\n        </div>\\n    </main>\\n\\n    <!-- PLAYER BAR (Bas) -->\\n    <footer class=\\\"h-24 bg-neutral-900 border-t border-neutral-800 flex items-center justify-between px-4 z-30 fixed bottom-0 w-full\\\">\\n        \\n        <!-- Left: Track Info -->\\n        <div class=\\\"w-1/4 flex items-center gap-3\\\">\\n            <img id=\\\"player-cover\\\" src=\\\"https://images.unsplash.com/photo-1493225255756-d9584f8606e9?q=80&w=200\\\" class=\\\"w-14 h-14 rounded shadow-md\\\">\\n            <div class=\\\"hidden sm:block\\\">\\n                <h4 id=\\\"player-title\\\" class=\\\"text-sm font-bold text-white hover:underline cursor-pointer\\\">Weekend Vibes</h4>\\n                <p id=\\\"player-artist\\\" class=\\\"text-xs text-gray-400 hover:text-white cursor-pointer\\\">Deezer Mix</p>\\n            </div>\\n            <button class=\\\"text-gray-400 hover:text-blue-500 ml-2\\\">\\n                <svg class=\\\"w-5 h-5\\\" fill=\\\"currentColor\\\" viewBox=\\\"0 0 24 24\\\"><path d=\\\"M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z\\\"/></svg>\\n         