    "code": "/**\n * Component: Stylish profile card with a hover effect\n * Author: @anonymous (https://tailwindflex.com/@anonymous)\n * Source: https://tailwindflex.com/@anonymous/stylish-profile-card-with-a-hover-effect\n * Attribution: Créé par @anonymous sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function StylishProfileCardWithAHoverEffect() {\n  return (\n    <div>\n    <div className=\"max-w-sm mx-auto overflow-hidden bg-white rounded-lg shadow-lg hover400\">\n      <div className=\"relative\">\n        <img className=\"w-full h-48 object-cover\" src=\"https://images.unsplash.com/photo-1557862921-37829c790f19?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw4fHx1c2VyfGVufDB8MHx8fDE2OTQwOTU5Nzl8MA&ixlib=rb-4.0.3&q=80&w=1080\" alt=\"Profile Image\" />\n      </div>\n      <div className=\"px-6 py-4\">\n        <div className=\"text-xl font-semibold text-gray-800\">John Doe</div>\n        <p className=\"text-gray-600\">Front-end Developer</p>\n      </div>\n      <div className=\"px-6 py-4\">\n        <span className=\"inline-block px-2 py-1 font-semibold text-teal-900 bg-teal-200 rounded-full\">Web</span>\n        <span className=\"inline-block px-2 py-1 font-semibold text-indigo-900 bg-indigo-200 rounded-full\">UI/UX</span>\n        <span className=\"inline-block px-2 py-1 font-semibold text-purple-900 bg-purple-200 rounded-full\">Design</span>\n      </div>\n      <div className=\"px-6 py-4\">\n        <a href=\"#\" className=\"text-blue-500 hover\">View Profile</a>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"max-w-sm mx-auto overflow-hidden bg-white rounded-lg shadow-lg hover:shadow-blue-400\">\n  <div class=\"relative\">\n    <img class=\"w-full h-48 object-cover\" src=\"https://images.unsplash.com/photo-1557862921-37829c790f19?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHw4fHx1c2VyfGVufDB8MHx8fDE2OTQwOTU5Nzl8MA&ixlib=rb-4.0.3&q=80&w=1080\" alt=\"Profile Image\">\n  </div>\n  <div class=\"px-6 py-4\">\n    <div class=\"text-xl font-semibold text-gray-800\">John Doe</div>\n    <p class=\"text-gray-600\">Front-end Developer</p>\n  </div>\n  <div class=\"px-6 py-4\">\n    <span class=\"inline-block px-2 py-1 font-semibold text-teal-900 bg-teal-200 rounded-full\">Web</span>\n    <span class=\"inline-block px-2 py-1 font-semibold text-indigo-900 bg-indigo-200 rounded-full\">UI/UX</span>\n    <span class=\"inline-block px-2 py-1 font-semibold text-purple-900 bg-purple-200 rounded-full\">Design</span>\n  </div>\n  <div class=\"px-6 py-4\">\n    <a href=\"#\" class=\"text-blue-500 hover:underline\">View Profile</a>\n  </div>\n</div>"
