    "registryDependencies": [],
    "dependencies": [],
    "code": "/**\n * Component: Responsive user card with tailwind\n * Author: @gopi (https://tailwindflex.com/@gopi)\n * Source: https://tailwindflex.com/@gopi/responsive-user-card-with-tailwind\n * Attribution: Créé par @gopi sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ResponsiveUserCardWithTailwind() {\n  return (\n    <div>\n    <section className=\"mb-2 border bg-neutral-100 p-4 rounded-lg max-w-full bg-neutral-100\">\n        <div className=\"mx-auto\">\n            <div className=\"card md max-w-lg\">\n                <div className=\"w-20 h-20 mx-auto mb-6 md6 flex-shrink-0\">\n                    <img className=\"object-cover rounded-full\" src=\"https://tailwindflex.com/public/images/user.png\" />\n                </div>\n                <div className=\"flex-grow text-center md\">\n                    <p className=\"font-bold\">Senior Developer</p>\n                    <h3 className=\"text-xl heading\">John Doe</h3>\n                    <p className=\"mt-2 mb-3\">John is a Senior Developer, mainly works in backend technologies.</p>\n                    <div>\n                        <span className=\"bg-gray-200 border px-3 py-1.5 rounded-lg text-sm\">Discrete Math</span>\n                        <span className=\"bg-gray-200 border px-3 py-1.5 rounded-lg text-sm\">Topology</span> \n                        <span className=\"bg-gray-200 border px-3 py-1.5 rounded-lg text-sm\">Neural Nets</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n    </div>\n  );\n}\n",
    "rawHtml": "<section class=\"mb-2 border bg-neutral-100 p-4 rounded-lg max-w-full bg-neutral-100\">\n    <div class=\"mx-auto\">\n        <div class=\"card md:flex max-w-lg\">\n            <div class=\"w-20 h-20 mx-auto mb-6 md:mr-6 flex-shrink-0\">\n                <img class=\"object-cover rounded-full\" src=\"https://tailwindflex.com/public/images/user.png\">\n            </div>\n            <div class=\"flex-grow text-center md:text-left\">\n                <p class=\"font-bold\">Senior Developer</p>\n                <h3 class=\"text-xl heading\">John Doe</h3>\n                <p class=\"mt-2 mb-3\">John is a Senior Developer, mainly works in backend technologies.</p>\n                <div>\n                    <span class=\"bg-gray-200 border px-3 py-1.5 rounded-lg text-sm\">Discrete Math</span>\n                    <span class=\"bg-gray-200 border px-3 py-1.5 rounded-lg text-sm\">Topology</span> \n                    <span class=\"bg-gray-200 border px-3 py-1.5 rounded-lg text-sm\">Neural Nets</span>\n                </div>\n            </div>\n        </div>\n    </div>\n</section>"
