    "code": "/**\n * Component: Pricing Card with gradient background\n * Author: @cguy2000 (https://tailwindflex.com/@cguy2000)\n * Source: https://tailwindflex.com/@cguy2000/pricing-card-with-gradient-background\n * Attribution: Créé par @cguy2000 sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function PricingCardWithGradientBackground() {\n  return (\n    <div>\n    <div className=\"relative text-gray-300\" id=\"pricing\">\n      <div aria-hidden=\"true\" className=\"absolute inset-0 h-max w-full m-auto grid grid-cols-2 -space-x-52 opacity-20\">\n        <div className=\"blur-[106px] h-56 bg-gradient-to-br to-purple-400 from-blue-700\"></div>\n        <div className=\"blur-[106px] h-32 bg-gradient-to-r from-cyan-400 to-indigo-600\"></div>\n      </div>\n      <div className=\"max-w-7xl mx-auto px-6 md12 xl6\">\n        <div className=\"mb-10 space-y-4 px-6 md0\">\n          <h2 className=\"text-center text-2xl font-bold text-white sm3xl md4xl\">Pricing</h2>\n        </div>\n        <div className=\"flex flex-col sm justify-center gap-4\">\n          <div\n            className=\"flex flex-col items-center aspect-auto p-4 sm8 border rounded-3xl bg-gray-800 border-gray-700 shadow-gray-600/10 shadow-none m-2 flex-1 max-w-md\">\n            <h2 className=\"text-lg sm font-medium text-white mb-2\">Affordable Pricing</h2>\n            <p className=\"text-lg sm text-center mb-6 mt-4\">\n              <span className=\"text-3xl sm4xl font-bold text-white\">$199</span> / Month\n            </p>\n            <p className=\"text-center mb-6\">Get access to all premium features for just $199 per month. No hidden fees or extra\n              charges.</p>\n            <a target=\"_blank\" rel=\"noreferrer\"\n              className=\"relative flex h-9 w-full items-center justify-center px-4 before before0 before before before before300 hover105 active75 active95 sm\"\n              href=\"#contact\"><span className=\"relative text-sm font-semibold text-black\">Get Started</span></a>\n          </div>\n        </div>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"relative text-gray-300\" id=\"pricing\">\n  <div aria-hidden=\"true\" class=\"absolute inset-0 h-max w-full m-auto grid grid-cols-2 -space-x-52 opacity-20\">\n    <div class=\"blur-[106px] h-56 bg-gradient-to-br to-purple-400 from-blue-700\"></div>\n    <div class=\"blur-[106px] h-32 bg-gradient-to-r from-cyan-400 to-indigo-600\"></div>\n  </div>\n  <div class=\"max-w-7xl mx-auto px-6 md:px-12 xl:px-6\">\n    <div class=\"mb-10 space-y-4 px-6 md:px-0\">\n      <h2 class=\"text-center text-2xl font-bold text-white sm:text-3xl md:text-4xl\">Pricing</h2>\n    </div>\n    <div class=\"flex flex-col sm:flex-row justify-center gap-4\">\n      <div\n        class=\"flex flex-col items-center aspect-auto p-4 sm:p-8 border rounded-3xl bg-gray-800 border-gray-700 shadow-gray-600/10 shadow-none m-2 flex-1 max-w-md\">\n        <h2 class=\"text-lg sm:text-xl font-medium text-white mb-2\">Affordable Pricing</h2>\n        <p class=\"text-lg sm:text-xl text-center mb-6 mt-4\">\n          <span class=\"text-3xl sm:text-4xl font-bold text-white\">$199</span> <!-- -->/ Month\n        </p>\n        <p class=\"text-center mb-6\">Get access to all premium features for just $199 per month. No hidden fees or extra\n          charges.</p>\n        <a target=\"_blank\" rel=\"noreferrer\"\n          class=\"relative flex h-9 w-full items-center justify-center px-4 before:absolute before:inset-0 before:rounded-full before:bg-white before:transition before:duration-300 hover:before:scale-105 active:duration-75 active:before:scale-95 sm:w-max\"\n          href=\"#contact\"><span class=\"relative text-sm font-semibold text-black\">Get Started</span></a>\n      </div>\n    </div>\n  </div>\n</div>"
