    "rawHtml": "<section class=\"w-full bg-white dark:bg-gray-700\">\n  <div class=\"w-full md:w-4/5 mx-auto\">\n    <div class=\"w-full flex flex-col text-center pt-12 md:pt-24\">\n      <h1 class=\"text-4xl md:text-5xl font-semibold text-gray-800 dark:text-white\">\n          The <span class=\"text-emerald-600\"> Pricing</span>\n      </h1>\n      <p class=\"w-full px-[12%] text-normal md:text-xl whitespace-pre-line dark:text-white\">\n        Here on <span class=\"text-emerald-600\">tailwindflex</span>.com you've all you need to build your own <br class=\"hidden lg:inline\" /> components, new templates and share your fantastic results with everyone &#8212; if you want\n      </p>\n    </div>\n    <div class=\"w-full pt-16 flex flex-col md:flex-row items-center\">\n      <div class=\"rounded-md w-[90%] mx-auto md:w-min-1/3 mx-auto items-center border border-gray-300 py-16 px-4 xl:px-24 mb-4 flex flex-col\">\n        <p class=\"text-gray-700 dark:text-gray-300 text-2xl\">Basic</p>\n        <h1 class=\"font-semibold text-6xl pt-2 pb-3 dark:text-white\">$0</h1>\n        <p class=\"text-gray-500\">per month</p>\n        <ul class=\"mt-10 list-image-[url('./YOU-CAN-SET-HERE-YOUR-ARROW-SVG-OR-IMG')] dark:text-gray-300\">\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Access to all modules</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Community support</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Online Playground</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Custom you profile</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Personal subdomain</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Points to earn and use </li>\n        </ul>\n        <button class=\"mt-6 bg-gray-100 rounded-md py-2 px-4 text-black text-xl\">Request Access</button>\n        <small class=\"text-sm mt-2 dark:text-gray-300\">It's free.</small>\n      </div>\n      <div class=\"rounded-md w-[90%] mx-auto md:w-min-1/3 bg-emerald-50/50 dark:bg-gray-50 mx-auto md:!mx-4 items-center border border-gray-300 py-24 px-4 xl:px-24 mb-4 flex flex-col\">\n        <p class=\"text-gray-700 dark:text-gray-500 text-2xl\">Premium</p>\n        <h1 class=\"font-semibold text-6xl pt-2 pb-3 dark:text-black\">$25</h1>\n        <p class=\"text-gray-400\">per month</p>\n        <ul class=\"mt-10 list-image-[url('./YOU-CAN-SET-HERE-YOUR-ARROW-SVG-OR-IMG')] dark:text-gray-300\">\n          <li class=\"mb-2 dark:text-gray-600\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Access to all modules</li>\n          <li class=\"mb-2 dark:text-gray-600\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Community support</li>\n          <li class=\"mb-2 dark:text-gray-600\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Online Playground</li>\n          <li class=\"mb-2 dark:text-gray-600\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Custom you profile</li>\n          <li class=\"mb-2 dark:text-gray-600\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Personal subdomain</li>\n          <li class=\"mb-2 dark:text-gray-600\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Points to earn and use </li>\n        </ul>\n        <button class=\"mt-6 bg-emerald-500 rounded-md py-2 px-4 text-white text-xl\">Request Access</button>\n        <small class=\"text-sm mt-2 dark:text-gray-500\">Perfect, all inclusive.</small>\n      </div>\n      <div class=\"rounded-md w-[90%] mx-auto md:w-min-1/3 mx-auto items-center border border-gray-300 py-16 px-4 xl:px-24 mb-4 flex flex-col\">\n        <p class=\"text-gray-700 dark:text-gray-300 text-2xl\">Standard</p>\n        <h1 class=\"font-semibold text-6xl pt-2 pb-3 dark:text-white\">$12</h1>\n        <p class=\"text-gray-500\">per month</p>\n        <ul class=\"mt-10 list-image-[url('./YOU-CAN-SET-HERE-YOUR-ARROW-SVG-OR-IMG')] dark:text-gray-300\">\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Access to all modules</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Community support</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Online Playground</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Custom you profile</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Personal subdomain</li>\n          <li class=\"mb-2\"><img src=\"https://www.svgrepo.com/show/453892/checkmark.svg\" class=\"inline h-6 w-6 text-gray-500 mr-3 -mt-1\"> Points to earn and use </li>\n        </ul>\n        <button class=\"mt-6 bg-gray-200 rounded-md py-2 px-4 text-black text-xl\">Request Access</button>\n        <small class=\"text-sm mt-2 dark:text-gray-300\">Creators on the way.</small>\n      </div>\n    </div>\n  </div>\n</sector>"
