    "rawHtml": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Why Choose Lueora?</title>\r\n    <link href=\"https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css\" rel=\"stylesheet\">\r\n    <style>\r\n        body {\r\n            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\r\n            background-color: #f0f8ff;\r\n            line-height: 1.5;\r\n        }\r\n\r\n        .comparison-container {\r\n            background: linear-gradient(to bottom, #ebf8ff, #ffffff);\r\n        }\r\n\r\n        .comparison-table th {\r\n            background-color: #e3f2fd;\r\n            color: #0369a1;\r\n        }\r\n\r\n        .comparison-table td {\r\n            background-color: #ffffff;\r\n        }\r\n\r\n        .comparison-table .check {\r\n            color: #10b981;\r\n        }\r\n\r\n        .comparison-table .cross {\r\n            color: #ef4444;\r\n        }\r\n\r\n        .comparison-table tr:hover {\r\n            background-color: #dbeafe;\r\n            transition: background-color 0.3s;\r\n        }\r\n\r\n        .header-title {\r\n            color: #1e3a8a;\r\n        }\r\n\r\n        .sub-title {\r\n            color: #374151;\r\n        }\r\n\r\n        .brand-section {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            margin-top: 2rem;\r\n        }\r\n\r\n        .brand-logo {\r\n            width: 60px;\r\n            height: 60px;\r\n        }\r\n\r\n        .brand-title {\r\n            margin-left: 0.75rem;\r\n            font-size: 1.5rem;\r\n            font-weight: 600;\r\n            color: #1e90ff;\r\n        }\r\n\r\n        footer {\r\n            padding: 1.5rem 0;\r\n            font-size: 0.875rem;\r\n            color: #6b7280;\r\n        }\r\n    </style>\r\n</head>\r\n\r\n<body class=\"comparison-container\">\r\n\r\n    <div class=\"min-h-screen flex flex-col justify-center items-center py-12 px-4 sm:px-6 lg:px-8\">\r\n        <div class=\"w-full max-w-6xl bg-white rounded-lg shadow-xl p-8 md:p-10\">\r\n            <h2 class=\"text-3xl font-bold text-center mt-12 sm:text-5xl header-title\">Why Choose Lueora?</h2>\r\n            <p class=\"max-w-3xl mx-auto mt-4 text-xl text-center sub-title\">See how Lueora stands out from other brands.</p>\r\n\r\n            <div class=\"mt-24 container space-y-12\">\r\n                <div class=\"relative p-8 border border-gray-200 rounded-2xl shadow-lg bg-white\">\r\n                    <table class=\"w-full text-left border-collapse comparison-table\">\r\n                        <thead>\r\n                            <tr>\r\n                                <th class=\"py-4 px-6 font-semibold text-lg\">Feature</th>\r\n                                <th class=\"py-4 px-6 font-semibold text-lg text-center\">Lueora</th>\r\n                                <th class=\"py-4 px-6 font-semibold text-lg text-center\">Other Brands</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr class=\"border-b\">\r\n                                <td class=\"py-4 px-6\">High Quality</td>\r\n                                <td class=\"py-4 px-6 text-center check\">✅</td>\r\n                                <td class=\"py-4 px-6 text-center cross\">❌</td>\r\n                            </tr>\r\n                            <tr class=\"border-b\">\r\n                                <td class=\"py-4 px-6\">Health & Comfort Focused</td>\r\n                                <td class=\"py-4 px-6 text-center check\">✅</td>\r\n                                <td class=\"py-4 px-6 text-center cross\">❌</td>\r\n                            </tr>\r\n                            <tr class=\"border-b\">\r\n                                <td class=\"py-4 px-6\">Fast & Free Shipping</td>\r\n                                <td class=\"py-4 px-6 text-center check\">✅</td>\r\n                                <td class=\"py-4 px-6 text-center cross\">❌</td>\r\n                            </tr>\r\n                            <tr class=\"border-b\">\r\n                                <td class=\"py-4 px-6\">Hassle-Free Refunds</td>\r\n                                <td class=\"py-4 px-6 text-center check\">✅</td>\r\n                                <td class=\"py-4 px-6 text-center cross\">❌</td>\r\n                            </tr>\r\n                            <tr class=\"border-b\">\r\n                                <td class=\"py-4 px-6\">Quick Email Support</td>\r\n                                <td class=\"py-4 px-6 text-center check\">✅</td>\r\n                                <td class=\"py-4 px-6 text-center cross\">❌</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"py-4 px-6\">Innovative Home Solutions</td>\r\n                                <td class=\"py-4 px-6 text-center check\">✅</td>\r\n                                <td class=\"py-4 px-6 text-center cross\">❌</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n\r\n</html>"
