    "code": "/**\n * Component: Responsive Pricing Table with Toggle Switch — Built with Tailwind Flex\n * Author: @umairarshad-dev (https://tailwindflex.com/@umairarshad-dev)\n * Source: https://tailwindflex.com/@umairarshad-dev/responsive-pricing-table-with-toggle-switch-built-with-tailwind-flex\n * Attribution: Créé par @umairarshad-dev sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function ResponsivePricingTableWithToggleSwitchBuiltWithTailwindFlex() {\n  return (\n    <div>\n    <div className=\"max-w-6xl mx-auto px-4 py-12\">\n      <div className=\"flex justify-between items-center mb-10\">\n        <h2 className=\"text-3xl font-bold\">Choose your plan</h2>\n        <div className=\"flex items-center space-x-2\">\n          <span className=\"text-sm font-medium\">Monthly</span>\n          <label className=\"relative inline-flex items-center cursor-pointer\">\n            <input type=\"checkbox\" value=\"\" className=\"sr-only peer\" />\n            <div className=\"w-11 h-6 bg-gray-200 peer-focus peer-focus2 peer-focus500 dark300 rounded-full peer dark700 peer-checked600\"></div>\n            <span className=\"absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-all peer-checked\"></span>\n          </label>\n          <span className=\"text-sm font-medium\">Yearly</span>\n        </div>\n      </div>\n    \n      <div className=\"flex flex-col md gap-6\">\n        \n        <div className=\"flex-1 flex flex-col border rounded-2xl p-6 shadow-md\">\n          <h3 className=\"text-xl font-semibold mb-2\">Basic</h3>\n          <p className=\"text-gray-500 mb-4\">For personal use and simple projects.</p>\n          <div className=\"text-4xl font-bold mb-6\">$15<span className=\"text-base font-normal text-gray-400\">/mo</span></div>\n          <ul className=\"flex-1 space-y-3 text-sm text-gray-600 mb-6\">\n            <li>✔ 5 Projects</li>\n            <li>✔ Community Support</li>\n            <li>✔ Email Access</li>\n          </ul>\n          <button className=\"mt-auto bg-blue-600 text-white py-2 rounded-xl hover700 transition\">Choose Plan</button>\n        </div>\n    \n        \n        <div className=\"flex-1 flex flex-col border-2 border-blue-600 rounded-2xl p-6 shadow-lg bg-blue-50\">\n          <h3 className=\"text-xl font-semibold mb-2 text-blue-700\">Pro</h3>\n          <p className=\"text-gray-600 mb-4\">Best for teams and freelancers.</p>\n          <div className=\"text-4xl font-bold text-blue-700 mb-6\">$39<span className=\"text-base font-normal text-blue-500\">/mo</span></div>\n          <ul className=\"flex-1 space-y-3 text-sm text-gray-700 mb-6\">\n            <li>✔ 25 Projects</li>\n            <li>✔ Priority Support</li>\n            <li>✔ Team Access</li>\n          </ul>\n          <button className=\"mt-auto bg-blue-700 text-white py-2 rounded-xl hover800 transition\">Choose Plan</button>\n        </div>\n    \n        \n        <div className=\"flex-1 flex flex-col border rounded-2xl p-6 shadow-md\">\n          <h3 className=\"text-xl font-semibold mb-2\">Enterprise</h3>\n          <p className=\"text-gray-500 mb-4\">For businesses with advanced needs.</p>\n          <div className=\"text-4xl font-bold mb-6\">$99<span className=\"text-base font-normal text-gray-400\">/mo</span></div>\n          <ul className=\"flex-1 space-y-3 text-sm text-gray-600 mb-6\">\n            <li>✔ Unlimited Projects</li>\n            <li>✔ Dedicated Manager</li>\n            <li>✔ Custom Solutions</li>\n          </ul>\n          <button className=\"mt-auto bg-blue-600 text-white py-2 rounded-xl hover700 transition\">Contact Sales</button>\n        </div>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
    "rawHtml": "<div class=\"max-w-6xl mx-auto px-4 py-12\">\n  <div class=\"flex justify-between items-center mb-10\">\n    <h2 class=\"text-3xl font-bold\">Choose your plan</h2>\n    <div class=\"flex items-center space-x-2\">\n      <span class=\"text-sm font-medium\">Monthly</span>\n      <label class=\"relative inline-flex items-center cursor-pointer\">\n        <input type=\"checkbox\" value=\"\" class=\"sr-only peer\">\n        <div class=\"w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-2 peer-focus:ring-blue-500 dark:peer-focus:ring-blue-300 rounded-full peer dark:bg-gray-700 peer-checked:bg-blue-600\"></div>\n        <span class=\"absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-all peer-checked:translate-x-full\"></span>\n      </label>\n      <span class=\"text-sm font-medium\">Yearly</span>\n    </div>\n  </div>\n\n  <div class=\"flex flex-col md:flex-row gap-6\">\n    <!-- Plan 1 -->\n    <div class=\"flex-1 flex flex-col border rounded-2xl p-6 shadow-md\">\n      <h3 class=\"text-xl font-semibold mb-2\">Basic</h3>\n      <p class=\"text-gray-500 mb-4\">For personal use and simple projects.</p>\n      <div class=\"text-4xl font-bold mb-6\">$15<span class=\"text-base font-normal text-gray-400\">/mo</span></div>\n      <ul class=\"flex-1 space-y-3 text-sm text-gray-600 mb-6\">\n        <li>✔ 5 Projects</li>\n        <li>✔ Community Support</li>\n        <li>✔ Email Access</li>\n      </ul>\n      <button class=\"mt-auto bg-blue-600 text-white py-2 rounded-xl hover:bg-blue-700 transition\">Choose Plan</button>\n    </div>\n\n    <!-- Plan 2 -->\n    <div class=\"flex-1 flex flex-col border-2 border-blue-600 rounded-2xl p-6 shadow-lg bg-blue-50\">\n      <h3 class=\"text-xl font-semibold mb-2 text-blue-700\">Pro</h3>\n      <p class=\"text-gray-600 mb-4\">Best for teams and freelancers.</p>\n      <div class=\"text-4xl font-bold text-blue-700 mb-6\">$39<span class=\"text-base font-normal text-blue-500\">/mo</span></div>\n      <ul class=\"flex-1 space-y-3 text-sm text-gray-700 mb-6\">\n        <li>✔ 25 Projects</li>\n        <li>✔ Priority Support</li>\n        <li>✔ Team Access</li>\n      </ul>\n      <button class=\"mt-auto bg-blue-700 text-white py-2 rounded-xl hover:bg-blue-800 transition\">Choose Plan</button>\n    </div>\n\n    <!-- Plan 3 -->\n    <div class=\"flex-1 flex flex-col border rounded-2xl p-6 shadow-md\">\n      <h3 class=\"text-xl font-semibold mb-2\">Enterprise</h3>\n      <p class=\"text-gray-500 mb-4\">For businesses with advanced needs.</p>\n      <div class=\"text-4xl font-bold mb-6\">$99<span class=\"text-base font-normal text-gray-400\">/mo</span></div>\n      <ul class=\"flex-1 space-y-3 text-sm text-gray-600 mb-6\">\n        <li>✔ Unlimited Projects</li>\n        <li>✔ Dedicated Manager</li>\n        <li>✔ Custom Solutions</li>\n      </ul>\n      <button class=\"mt-auto bg-blue-600 text-white py-2 rounded-xl hover:bg-blue-700 transition\">Contact Sales</button>\n    </div>\n  </div>\n</div>"
