     <!-- Feature 5 -->\r\n            <div class=\"p-4 border-b border-r border-gray-200 text-sm text-gray-700 flex items-center\">Custom Editable\r\n                Templates</div>\r\n            <div class=\"p-4 border-b border-r border-gray-200 text-center flex justify-center items-center\">\r\n                <i class=\"fas fa-times text-red-400 text-lg\"></i> <!-- Not included -->\r\n            </div>\r\n            <div class=\"p-4 border-b border-gray-200 text-center bg-gray-50 flex justify-center items-center\">\r\n                <i class=\"fas fa-check text-green-500 text-lg\"></i>\r\n            </div>\r\n\r\n            <!-- Feature 6 -->\r\n            <div class=\"p-4 border-b border-r border-gray-200 text-sm text-gray-700 flex items-center\">Unlimited Client\r\n                Management</div>\r\n            <div class=\"p-4 border-b border-r border-gray-200 text-center flex justify-center items-center\">\r\n                <i class=\"fas fa-times text-red-400 text-lg\"></i> <!-- Not included -->\r\n            </div>\r\n            <div class=\"p-4 border-b border-gray-200 text-center bg-gray-50 flex justify-center items-center\">\r\n                <i class=\"fas fa-check text-green-500 text-lg\"></i>\r\n            </div>\r\n\r\n            <!-- Feature 7 -->\r\n            <div class=\"p-4 border-b border-r border-gray-200 text-sm text-gray-700 flex items-center\">Custom Branding\r\n            </div>\r\n            <div class=\"p-4 border-b border-r border-gray-200 text-center flex justify-center items-center\">\r\n                <i class=\"fas fa-times text-red-400 text-lg\"></i> <!-- Not included -->\r\n            </div>\r\n            <div class=\"p-4 border-b border-gray-200 text-center bg-gray-50 flex justify-center items-center\">\r\n                <i class=\"fas fa-check text-green-500 text-lg\"></i>\r\n            </div>\r\n\r\n            <!-- Feature 8 -->\r\n            <div class=\"p-4 border-b border-r border-gray-200 text-sm te