    "code": "/**\n * Component: xZCcxzc\n * Author: @dibyanjaya-panda (https://tailwindflex.com/@dibyanjaya-panda)\n * Source: https://tailwindflex.com/@dibyanjaya-panda/xzccxzc\n * Attribution: Créé par @dibyanjaya-panda sur TailwindFlex\n * License: Open Source (TailwindFlex community)\n */\nimport React from \"react\";\n\nexport function Xzccxzc() {\n  return (\n    <div>\n    <div className=\"bg-white dark800 flex justify-center items-center w-screen h-screen p-5\">\n      <div className=\"border shadow-teal-300 shadow-md max-w-2xl p-6 rounded-lg dark700 dark300\">\n        <h1 className=\"text-4xl font-mono fon\">Tailwind Playground</h1>\n        <ul className=\"list-disc text-lg px-6\">\n          <li>Everything here works just like it does when you're running Tailwind CSS locally.</li>\n          <li>The preview updates in real-time as you code.</li>\n          <li>Save and share your compocxzczxcnents with the community.</li>\n        </ul>\n      </div>\n    </div>\n    </div>\n  );\n}\n",
