    "rawHtml": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Acode Master - FB & WhatsApp UI Combo</title>\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n  <style type=\"text/tailwindcss\">\n    @tailwind base;\n    @tailwind components;\n    @tailwind utilities;\n\n    @layer components {\n      .btn-primary {\n        @apply bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500 hover:from-pink-500 hover:to-yellow-500 text-white px-4 py-2 rounded-full transition duration-500 ease-in-out;\n      }\n      .nav-icon {\n        @apply p-2 text-gray-600 hover:text-blue-600 transition duration-300;\n      }\n      .animated-bg {\n        background: linear-gradient(-45deg, #1e3a8a, #9333ea, #db2777, #facc15);\n        background-size: 400% 400%;\n        animation: gradientBG 10s ease infinite;\n      }\n      @keyframes gradientBG {\n        0% { background-position: 0% 50%; }\n        50% { background-position: 100% 50%; }\n        100% { background-position: 0% 50%; }\n      }\n    }\n  </style>\n</head>\n<body class=\"bg-gray-50 font-sans\">\n  <!-- Header -->\n  <nav class=\"fixed top-0 left-0 w-full bg-white shadow z-50\">\n    <div class=\"max-w-7xl mx-auto px-4 py-2 flex justify-between items-center\">\n      <div class=\"flex items-center space-x-3\">\n        <img src=\"data:image/jpeg;base64,\" alt=\"Acode Master Logo\" class=\"w-8 h-8 rounded-full\">\n        <span class=\"font-bold text-lg text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500 animate-pulse\">Acode Master</span>\n      </div>\n      <div class=\"hidden md:flex space-x-6\">\n        <a href=\"#\" class=\"nav-icon\"><i class=\"fas fa-home\"></i></a>\n        <a href=\"#\" class=\"nav-icon\"><i class=\"fas fa-user-friends\"></i></a>\n        <a href=\"#\" class=\"nav-icon\"><i class=\"fas fa-video\"></i></a>\n        <a href=\"#\" class=\"nav-icon\"><i class=\"fas fa-store\"></i></a>\n      </div>\n      <div class=\"flex items-center space-x-4\">\n        <button class=\"relative nav-icon\">\n          <i class=\"fas fa-comments\"></i>\n          <span class=\"absolute top-0 right-0 w-4 h-4 bg-red-500 text-xs text-white rounded-full flex items-center justify-center\">2</span>\n        </button>\n        <button class=\"nav-icon\"><i class=\"fas fa-bell\"></i></button>\n        <img src=\"data:image/jpeg;base64,\" alt=\"Profile\" class=\"h-8 w-8 rounded-full object-cover\">\n      </div>\n    </div>\n  </nav>\n\n  <!-- Sidebar + Chat like WhatsApp -->\n  <div class=\"flex pt-16\">\n    <!-- Sidebar -->\n    <aside class=\"hidden md:block w-64 bg-white border-r min-h-screen p-4\">\n      <div class=\"text-xl font-semibold mb-4\">Chats</div>\n      <ul class=\"space-y-2\">\n        <li class=\"flex items-center space-x-3 hover:bg-gray-100 p-2 rounded cursor-pointer\">\n          <img src=\"data:image/jpeg;base64,\" class=\"h-10 w-10 rounded-full\" alt=\"Imano\">\n          <div>\n            <div class=\"font-medium\">Imano</div>\n            <div class=\"text-sm text-gray-500\">Hey bro, project iragenda...</div>\n          </div>\n        </li>\n        <li class=\"flex items-center space-x-3 hover:bg-gray-100 p-2 rounded cursor-pointer\">\n          <img src=\"data:image/jpeg;base64,\" class=\"h-10 w-10 rounded-full\" alt=\"CodeMaster Team\">\n          <div>\n            <div class=\"font-medium\">CodeMaster Team</div>\n            <div class=\"text-sm text-gray-500\">Let's push update tonight</div>\n          </div>\n        </li>\n      </ul>\n    </aside>\n\n    <!-- Main Chat Window -->\n    <main class=\"flex-1 bg-gray-100 p-6\">\n      <div class=\"bg-white shadow rounded-lg p-4 h-[80vh] flex flex-col\">\n        <div class=\"flex-1 overflow-y-auto space-y-4\">\n          <div class=\"flex items-start space-x-2\">\n            <img src=\"data:image/jpeg;base64,\" class=\"h-8 w-8 rounded-full\" alt=\"Imano\">\n            <div class=\"bg-gray-200 p-2 rounded\">Hello Acode Master!</div>\n          </div>\n          <div class=\"flex items-start justify-end space-x-2\">\n            <div class=\"animated-bg text-white p-2 rounded\">Hey! How can I help?</div>\n            <img src=\"data:image/jpeg;base64,\" class=\"h-8 w-8 rounded-full\" alt=\"You\">\n          </div>\n          <div class=\"flex items-start space-x-2\">\n            <img src=\"data:image/jpeg;base64,\" class=\"h-8 w-8 rounded-full\" alt=\"Imano\">\n            <div class=\"bg-gray-200 p-2 rounded\">Can you add an image like this?</div>\n          </div>\n          <div class=\"flex items-start justify-end space-x-2\">\n            <div class=\"animated-bg text-white p-2 rounded\">Yes, done!</div>\n            <img src=\"data:image/jpeg;base64,\" class=\"h-8 w-8 rounded-full\" alt=\"You\">\n          </div>\n        </div>\n        <div class=\"mt-4 flex items-center\">\n          <input type=\"text\" class=\"flex-1 p-2 border border-gray-300 rounded-full focus:outline-none\" placeholder=\"Type a message...\">\n          <button class=\"ml-2 btn-primary\"><i class=\"fas fa-paper-plane\"></i></button>\n        </div>\n      </div>\n    </main>\n  </div>\n</body>\n</html>"
